pub fn lowerSelectAlloc(
    alloc: std.mem.Allocator,
    sql: []const u8,
    schema: runtime_schema.TableSchema,
    params: []const SqlValue,
) !LoweredSelect {
    if (schema.storage_mode != .relational or schema.primary_key == null) return error.InvalidSqlCatalog;
    var tokens = try tokenizeAlloc(alloc, sql);
    defer freeTokens(alloc, &tokens);

    var parser = Parser{
        .alloc = alloc,
        .tokens = tokens.items,
        .schema = schema,
        .params = params,
    };
    return parser.parseSelect() catch |err| switch (err) {
        error.InvalidRowsRequest => return error.UnsupportedSqlShape,
        else => return err,
    };
}

pub fn lowerQueryPlanAlloc(
    alloc: std.mem.Allocator,
    sql: []const u8,
    schema: runtime_schema.TableSchema,
    params: []const SqlValue,
) !LoweredQueryPlan {
    if (schema.storage_mode != .relational or schema.primary_key == null) return error.InvalidSqlCatalog;
    var tokens = try tokenizeAlloc(alloc, sql);
    defer freeTokens(alloc, &tokens);

    var parser = Parser{
        .alloc = alloc,
        .tokens = tokens.items,
        .schema = schema,
        .params = params,
    };
    var lowered = parser.parseQueryPlan() catch |err| switch (err) {
        error.InvalidRowsRequest => return error.UnsupportedSqlShape,
        else => return err,
    };
    errdefer lowered.deinit(alloc);
    relational_rows.validateRowsQueryPlanCteOutputAlloc(alloc, schema, lowered.plan) catch |err| switch (err) {
        error.InvalidRowsRequest => return error.UnsupportedSqlShape,
        else => return err,
    };
    return lowered;
}

pub fn lowerReadPlanAlloc(
    alloc: std.mem.Allocator,
    sql: []const u8,
    schema: runtime_schema.TableSchema,
    params: []const SqlValue,
) !LoweredReadPlan {
    return try lowerReadPlanWithSchemasAlloc(alloc, sql, schema, schema, params);
}

pub fn lowerReadPlanWithSchemasAlloc(
    alloc: std.mem.Allocator,
    sql: []const u8,
    schema: runtime_schema.TableSchema,
    source_schema: runtime_schema.TableSchema,
    params: []const SqlValue,
) !LoweredReadPlan {
    var saw_invalid_catalog = false;

    if (lowerLateralPlanWithSchemasAlloc(alloc, sql, schema, source_schema, params)) |lowered| {
        return .{ .lateral = lowered };
    } else |err| switch (err) {
        error.UnsupportedSqlShape => {},
        error.InvalidSqlCatalog => saw_invalid_catalog = true,
        else => return err,
    }

    if (lowerWindowPlanAlloc(alloc, sql, schema, params)) |lowered| {
        return .{ .window = lowered };
    } else |err| switch (err) {
        error.UnsupportedSqlShape => {},
        error.InvalidSqlCatalog => saw_invalid_catalog = true,
        else => return err,
    }

    if (lowerAggregatePlanAlloc(alloc, sql, schema, params)) |lowered| {
        return .{ .aggregate = lowered };
    } else |err| switch (err) {
        error.UnsupportedSqlShape => {},
        error.InvalidSqlCatalog => saw_invalid_catalog = true,
        else => return err,
    }

    if (lowerJoinWithSchemasAlloc(alloc, sql, schema, source_schema, params)) |lowered| {
        return .{ .join = lowered };
    } else |err| switch (err) {
        error.UnsupportedSqlShape => {},
        error.InvalidSqlCatalog => saw_invalid_catalog = true,
        else => return err,
    }

    if (lowerQueryPlanAlloc(alloc, sql, schema, params)) |lowered| {
        return .{ .query = lowered };
    } else |err| switch (err) {
        error.UnsupportedSqlShape => if (saw_invalid_catalog) return error.InvalidSqlCatalog else return error.UnsupportedSqlShape,
        else => return err,
    }
}

pub fn lowerReadPlanWithCatalogAlloc(
    alloc: std.mem.Allocator,
    sql: []const u8,
    schema: runtime_schema.TableSchema,
    params: []const SqlValue,
    catalog: table_catalog.CatalogSource,
) !LoweredReadPlan {
    if (try readSourceTableNamesAlloc(alloc, sql)) |resolved_tables| {
        var tables = resolved_tables;
        defer tables.deinit(alloc);
        if (!std.mem.eql(u8, tables.left, tables.source)) {
            const source_schema = try catalogRuntimeSchemaAlloc(alloc, catalog, tables.source);
            defer runtime_schema.freeSchema(alloc, source_schema);
            return try lowerReadPlanWithSchemasAlloc(alloc, sql, schema, source_schema, params);
