pub fn runtimeSchemaFromCreateTablePlanAlloc(
    alloc: std.mem.Allocator,
    plan: CreateTablePlan,
) !runtime_schema.TableSchema {
    if (plan.replace_existing and plan.if_not_exists) return error.InvalidSqlCatalog;
    if (plan.primary_key == null) return error.InvalidSqlCatalog;
    try validateRelationalColumnCatalog(plan.columns);
    try validatePrimaryKeyColumns(plan.columns, plan.primary_key.?);
    try validateUniqueConstraintCatalog(plan.columns, plan.unique_constraints);
    try validateForeignKeyCatalog(plan.columns, plan.foreign_keys);
    try validateRelationalCheckCatalog(plan.columns, plan.checks);

    const default_type = try alloc.dupe(u8, "_default");
    const ttl_field = alloc.dupe(u8, "_timestamp") catch |err| {
        alloc.free(default_type);
        return err;
    };
    var schema: runtime_schema.TableSchema = .{
        .default_type = default_type,
        .ttl_field = ttl_field,
        .enforce_types = true,
        .storage_mode = .relational,
    };
    errdefer runtime_schema.freeSchema(alloc, schema);
    schema.relational_columns = try cloneDdlRelationalColumns(alloc, plan.columns);
    schema.primary_key = try cloneDdlPrimaryKeyMaybe(alloc, plan.primary_key);
    schema.unique_constraints = try cloneDdlUniqueConstraints(alloc, plan.unique_constraints);
    schema.foreign_keys = try cloneDdlForeignKeys(alloc, plan.foreign_keys);
    schema.checks = try cloneDdlRelationalChecks(alloc, plan.checks);
    return schema;
}

pub fn applyDdlPlanToRuntimeSchemaAlloc(
    alloc: std.mem.Allocator,
    current: runtime_schema.TableSchema,
    plan: LoweredDdlPlan,
) !runtime_schema.TableSchema {
    return switch (plan) {
        .create_table => |create_table| applyCreateTablePlanAlloc(alloc, current, create_table),
        .create_index => |create_index| applyCreateIndexPlanAlloc(alloc, current, create_index),
        .drop_index => |drop_index| applyDropIndexPlanAlloc(alloc, current, drop_index),
        .drop_table => error.UnsupportedSqlShape,
        .alter_table => |alter_table| applyAlterTablePlanAlloc(alloc, current, alter_table),
        .create_update_policy => |update_policy| applyCreateUpdatePolicyPlanAlloc(alloc, current, update_policy),
    };
}

pub fn schemaJsonFromCreateTablePlanAlloc(
    alloc: std.mem.Allocator,
    plan: CreateTablePlan,
) ![]u8 {
    const runtime = try runtimeSchemaFromCreateTablePlanAlloc(alloc, plan);
    defer runtime_schema.freeSchema(alloc, runtime);

    var arena_impl = std.heap.ArenaAllocator.init(alloc);
    defer arena_impl.deinit();
    const arena = arena_impl.allocator();
    const root = try schemaJsonValueFromCreateTablePlanAlloc(arena, plan);
    const schema_json = try std.json.Stringify.valueAlloc(alloc, root, .{ .emit_null_optional_fields = false });
    errdefer alloc.free(schema_json);
    try validateDdlAppliedSchemaJsonAlloc(alloc, schema_json);
    return schema_json;
}

pub fn applyDdlPlanToSchemaJsonAlloc(
    alloc: std.mem.Allocator,
    current_schema_json: []const u8,
    plan: LoweredDdlPlan,
) !AppliedDdlSchemaJson {
    switch (plan) {
        .create_table => |create_table| {
            if (current_schema_json.len != 0) {
                if (create_table.replace_existing) return .{
                    .schema_json = try schemaJsonFromCreateTablePlanAlloc(alloc, create_table),
                    .requires_rebuild = true,
                    .validation_required = true,
                    .rewrite_required = true,
                };
                if (!create_table.if_not_exists) return error.InvalidSqlCatalog;
                return .{ .schema_json = try alloc.dupe(u8, current_schema_json) };
            }
            return .{ .schema_json = try schemaJsonFromCreateTablePlanAlloc(alloc, create_table) };
        },
        .drop_table => return error.UnsupportedSqlShape,
        .create_index, .drop_index, .alter_table, .create_update_policy => {},
    }

    if (current_schema_json.len == 0) {
        return switch (plan) {
            .drop_index => |drop_index| if (drop_index.if_exists) .{ .schema_json = try alloc.dupe(u8, current_schema_json) } else error.InvalidSqlCatalog,
            .alter_table => |alter_table| if (alter_table.if_exists) .{ .schema_json = try alloc.dupe(u8, current_schema_json) } else error.InvalidSqlCatalog,
            .create_table => unreachable,
            .drop_table => unreachable,
            .create_index, .create_update_policy => error.InvalidSqlCatalog,
        };
    }
    var arena_impl = std.heap.ArenaAllocator.init(alloc);
    defer arena_impl.deinit();
    const arena = arena_impl.allocator();
    var parsed = try std.json.parseFromSlice(std.json.Value, arena, current_schema_json, .{});
    const root = switch (parsed.value) {
        .object => |*object| object,
        else => return error.InvalidSqlCatalog,
    };

    var result: AppliedDdlSchemaJson = .{ .schema_json = &.{} };
    switch (plan) {
        .create_table => unreachable,
        .drop_table => unreachable,
        .create_index => |create_index| {
            const changed = try applyCreateIndexPlanToSchemaJsonValue(arena, root, create_index);
            result.requires_rebuild = changed;
            result.validation_required = changed and create_index.unique;
        },
        .drop_index => |drop_index| try applyDropIndexPlanToSchemaJsonValue(arena, root, drop_index),
        .alter_table => |alter_table| {
            const flags = alterTablePlanWorkFlags(alter_table);
            result.requires_rebuild = flags.requires_rebuild;
            result.validation_required = flags.validation_required;
            result.rewrite_required = flags.rewrite_required;
            try applyAlterTablePlanToSchemaJsonValue(arena, root, alter_table);
        },
        .create_update_policy => |update_policy| {
            try applyCreateUpdatePolicyPlanToSchemaJsonValue(arena, root, update_policy);
        },
    }
    result.schema_json = try std.json.Stringify.valueAlloc(alloc, parsed.value, .{ .emit_null_optional_fields = false });
    errdefer alloc.free(result.schema_json);
    try validateDdlAppliedSchemaJsonAlloc(alloc, result.schema_json);
    return result;
}

const DdlWorkFlags = struct {
    requires_rebuild: bool = false,
    validation_required: bool = false,
    rewrite_required: bool = false,
};

fn applyCreateTablePlanAlloc(
    alloc: std.mem.Allocator,
    current: runtime_schema.TableSchema,
    plan: CreateTablePlan,
) !runtime_schema.TableSchema {
    if (tableSchemaCatalogExists(current)) {
        if (plan.replace_existing) return try runtimeSchemaFromCreateTablePlanAlloc(alloc, plan);
        if (plan.if_not_exists and current.storage_mode == .relational) return try cloneRelationalRuntimeSchemaAlloc(alloc, current);
        return error.InvalidSqlCatalog;
    }
    return try runtimeSchemaFromCreateTablePlanAlloc(alloc, plan);
}

fn tableSchemaCatalogExists(current: runtime_schema.TableSchema) bool {
    return current.storage_mode == .relational or
        current.dynamic_templates.len != 0 or
        current.full_text_documents.len != 0 or
        current.relational_columns.len != 0 or
        current.primary_key != null or
        current.foreign_keys.len != 0 or
        current.unique_constraints.len != 0 or
        current.checks.len != 0;
}

fn alterTablePlanWorkFlags(plan: AlterTablePlan) DdlWorkFlags {
    var flags: DdlWorkFlags = .{};
    for (plan.operations) |operation| {
        switch (operation) {
            .alter_column_default, .drop_constraint => {},
            .rename_constraint => {},
            .drop_update_policy => {},
            .alter_column_nullability => |nullability| {
                if (!nullability.nullable) flags.validation_required = true;
            },
            .drop_column, .rename_column, .alter_column_type => {
                flags.requires_rebuild = true;
                flags.validation_required = true;
                flags.rewrite_required = true;
            },
            .add_column => |add_column| {
                flags.requires_rebuild = true;
                flags.validation_required = !add_column.column.nullable or
                    add_column.unique_constraints.len != 0 or
                    add_column.foreign_keys.len != 0 or
                    add_column.checks.len != 0;
                flags.rewrite_required = add_column.column.generated != null or
                    add_column.column.default_value != null or
                    !add_column.column.nullable;
            },
            else => {
                flags.requires_rebuild = true;
                flags.validation_required = true;
            },
        }
    }
    return flags;
}

fn isCaseFoldExpressionOp(op: runtime_schema.UniqueExpressionOp) bool {
    return switch (op) {
        .lower, .upper => true,
    };
}

fn relationalGeneratedOpForUniqueExpressionOp(op: runtime_schema.UniqueExpressionOp) runtime_schema.RelationalGeneratedOp {
    return switch (op) {
        .lower => .lower,
        .upper => .upper,
    };
}

fn applyCreateIndexPlanAlloc(
    alloc: std.mem.Allocator,
    current: runtime_schema.TableSchema,
    plan: CreateIndexPlan,
) !runtime_schema.TableSchema {
    var schema = try cloneRelationalRuntimeSchemaAlloc(alloc, current);
    errdefer runtime_schema.freeSchema(alloc, schema);

    if (relationalIndexNameExists(schema, plan.index_name)) {
        if (plan.if_not_exists) return schema;
        return error.InvalidSqlCatalog;
    }

    if (plan.method == .gin) {
        if (plan.unique or plan.columns.len != 1 or plan.expressions.len != 0 or plan.generated_expression != null) return error.UnsupportedSqlShape;
        const column = relationalColumnForDdl(schema.relational_columns, plan.columns[0]) orelse return error.InvalidSqlCatalog;
        switch (column.field_type) {
            .json => if (plan.opclass == .array_ops) return error.InvalidSqlCatalog,
            .array => if (plan.opclass == .jsonb_path_ops) return error.InvalidSqlCatalog,
            else => return error.InvalidSqlCatalog,
        }
    }

    if (plan.unique) {
        const constraint: runtime_schema.UniqueConstraint = .{
            .name = plan.index_name,
            .columns = plan.columns,
            .expressions = plan.expressions,
            .where = plan.where,
            .validation_state = .unvalidated,
        };
        try validateUniqueConstraintForColumns(schema.relational_columns, constraint);
        try appendUniqueConstraintAlloc(alloc, &schema, constraint);
        return schema;
    }

    const index_generation = stableSecondaryIndexGeneration(plan);
    if (plan.generated_expression) |generated_expression| {
        if (plan.columns.len != 0 or plan.expressions.len != 0) return error.UnsupportedSqlShape;
        if (relationalColumnIndex(schema.relational_columns, plan.index_name) != null) return error.InvalidSqlCatalog;
        const column: runtime_schema.RelationalColumn = .{
            .name = plan.index_name,
            .path = plan.index_name,
            .field_type = .keyword,
            .nullable = true,
            .indexed = true,
            .index_lifecycle = .building,
            .index_generation = index_generation,
            .index_name = plan.index_name,
            .generated = generated_expression,
            .index_where = plan.where,
        };
        try validateGeneratedColumnForColumns(schema.relational_columns, column);
        try validateUniquePredicatesForColumns(schema.relational_columns, plan.where);
        try appendRelationalColumnAlloc(alloc, &schema, column);
        return schema;
    }

    if (plan.columns.len == 0 or plan.expressions.len != 0) return error.UnsupportedSqlShape;
    try validateUniquePredicatesForColumns(schema.relational_columns, plan.where);
    try markColumnsIndexedAlloc(alloc, &schema, plan.index_name, plan.columns, plan.where, index_generation);
    return schema;
}

fn relationalIndexNameExists(schema: runtime_schema.TableSchema, index_name: []const u8) bool {
    return uniqueConstraintNameExists(schema.unique_constraints, index_name) or
        relationalColumnIndexForIndexName(schema.relational_columns, index_name) != null;
}

fn applyDropIndexPlanAlloc(
    alloc: std.mem.Allocator,
    current: runtime_schema.TableSchema,
    plan: DropIndexPlan,
) !runtime_schema.TableSchema {
    if (!tableSchemaCatalogExists(current)) {
        if (plan.if_exists) return try cloneEmptyRuntimeSchemaAlloc(alloc, current);
        return error.InvalidSqlCatalog;
    }
    var schema = try cloneRelationalRuntimeSchemaAlloc(alloc, current);
    errdefer runtime_schema.freeSchema(alloc, schema);
    try dropIndexFromRuntimeSchemaAlloc(alloc, &schema, plan);
    return schema;
}

fn applyAlterTablePlanAlloc(
    alloc: std.mem.Allocator,
    current: runtime_schema.TableSchema,
    plan: AlterTablePlan,
) !runtime_schema.TableSchema {
    if (!tableSchemaCatalogExists(current)) {
        if (plan.if_exists) return try cloneEmptyRuntimeSchemaAlloc(alloc, current);
        return error.InvalidSqlCatalog;
    }
    var schema = try cloneRelationalRuntimeSchemaAlloc(alloc, current);
    errdefer runtime_schema.freeSchema(alloc, schema);

    for (plan.operations) |operation| {
        switch (operation) {
            .add_column => |add_column| try addRelationalColumnOperationAlloc(alloc, &schema, add_column),
            .rename_column => |rename_column| try renameRelationalColumnAlloc(alloc, &schema, rename_column),
            .rename_constraint => |rename_constraint| try renameRelationalConstraintAlloc(alloc, &schema, rename_constraint),
            .drop_column => |drop_column| try dropRelationalColumnAlloc(alloc, &schema, drop_column),
            .drop_constraint => |drop_constraint| try dropRelationalConstraintAlloc(alloc, &schema, drop_constraint),
            .drop_update_policy => |drop_update_policy| try dropUpdatePolicyFromRuntimeSchemaAlloc(alloc, &schema, drop_update_policy),
            .alter_column_default => |alter_column_default| try alterRelationalColumnDefaultAlloc(alloc, &schema, alter_column_default),
            .alter_column_nullability => |alter_column_nullability| try alterRelationalColumnNullability(&schema, alter_column_nullability),
            .alter_column_type => |alter_column_type| try alterRelationalColumnTypeAlloc(alloc, &schema, alter_column_type),
            .add_unique_constraint => |constraint| {
                try validateUniqueConstraintForColumns(schema.relational_columns, constraint);
                try appendUniqueConstraintAlloc(alloc, &schema, constraint);
            },
            .add_foreign_key => |foreign_key| {
                try validateForeignKeyForColumns(schema.relational_columns, foreign_key);
                try appendForeignKeyAlloc(alloc, &schema, foreign_key);
            },
            .add_check => |check| {
                try validateCheckForColumns(schema.relational_columns, check);
                try appendRelationalCheckAlloc(alloc, &schema, check);
            },
            .validate_constraint => |constraint_name| try validateConstraintByName(&schema, constraint_name),
        }
    }
    return schema;
}

fn applyCreateUpdatePolicyPlanAlloc(
    alloc: std.mem.Allocator,
    current: runtime_schema.TableSchema,
    plan: CreateUpdatePolicyPlan,
) !runtime_schema.TableSchema {
    var schema = try cloneRelationalRuntimeSchemaAlloc(alloc, current);
    errdefer runtime_schema.freeSchema(alloc, schema);
    try setColumnOnUpdatePolicyAlloc(alloc, &schema, plan.column_name, plan.on_update_value);
    return schema;
}

fn dropUpdatePolicyFromRuntimeSchemaAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    operation: DropUpdatePolicyOperation,
) !void {
    _ = operation.trigger_name;
    var policy_count: usize = 0;
    var policy_index: usize = 0;
    for (schema.relational_columns, 0..) |column, i| {
        if (column.on_update_value == null) continue;
        policy_count += 1;
        policy_index = i;
    }
    if (policy_count == 0) {
        if (operation.if_exists) return;
        return error.InvalidSqlCatalog;
    }
    if (policy_count > 1) return error.InvalidSqlCatalog;
    const columns = @constCast(schema.relational_columns);
    if (columns[policy_index].on_update_value) |value| alloc.free(value.value_json);
    columns[policy_index].on_update_value = null;
}

fn addRelationalColumnOperationAlloc(
    alloc: std.mem.Allocator,
    schema: *runtime_schema.TableSchema,
    operation: AddColumnOperation,
) !void {
    if (relationalColumnIndex(schema.relational_columns, operation.column.name) != null) {
        if (operation.if_not_exists) return;
        return error.InvalidSqlCatalog;
    }
    try validateGeneratedColumnForColumns(schema.relational_columns, operation.column);
    try validateUniquePredicatesForColumns(schema.relational_columns, operation.column.index_where);
    try appendRelationalColumnAlloc(alloc, schema, operation.column);
    for (operation.unique_constraints) |constraint| {
        try validateUniqueConstraintForColumns(schema.relational_columns, constraint);
        try appendUniqueConstraintAlloc(alloc, schema, constraint);
    }
    for (operation.foreign_keys) |foreign_key| {
        try validateForeignKeyForColumns(schema.relational_columns, foreign_key);
        try appendForeignKeyAlloc(alloc, schema, foreign_key);
    }
    for (operation.checks) |check| {
        try validateCheckForColumns(schema.relational_columns, check);
        try appendRelationalCheckAlloc(alloc, schema, check);
    }
}

const InsertSourceTableNames = struct {
    target: []const u8,
    source: []const u8,

    fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        alloc.free(@constCast(self.target));
        alloc.free(@constCast(self.source));
        self.* = undefined;
    }
};

fn insertSourceTableNamesAlloc(alloc: std.mem.Allocator, sql: []const u8) !?InsertSourceTableNames {
    var tokens = try tokenizeAlloc(alloc, sql);
    defer freeTokens(alloc, &tokens);
    if (tokens.items.len == 0 or tokens.items[0].kind != .identifier or !std.ascii.eqlIgnoreCase(tokens.items[0].text, "insert")) return null;

    var index: usize = 1;
    if (!consumeKeyword(tokens.items, &index, "into")) return null;
    _ = consumeKeyword(tokens.items, &index, "only");
    if (index >= tokens.items.len or tokens.items[index].kind != .identifier) return error.UnsupportedSqlShape;
    const target = try normalizeSqlObjectIdentifierAlloc(alloc, tokens.items[index].text);
    var target_transferred = false;
    errdefer if (!target_transferred) alloc.free(target);
    index += 1;

    const select_index = findTopLevelKeyword(tokens.items[index..], "select") orelse {
        alloc.free(target);
        return null;
    };
    const absolute_select = index + select_index;
    const from_index = findTopLevelKeyword(tokens.items[absolute_select + 1 ..], "from") orelse return error.UnsupportedSqlShape;
    var source_index = absolute_select + 1 + from_index + 1;
    _ = consumeKeyword(tokens.items, &source_index, "only");
    if (source_index >= tokens.items.len or tokens.items[source_index].kind != .identifier) return error.UnsupportedSqlShape;
    const source = try normalizeSqlObjectIdentifierAlloc(alloc, tokens.items[source_index].text);
    errdefer alloc.free(source);

    target_transferred = true;
    return .{ .target = target, .source = source };
}

fn joinedWriteSourceTableNamesAlloc(alloc: std.mem.Allocator, sql: []const u8) !?InsertSourceTableNames {
    var tokens = try tokenizeAlloc(alloc, sql);
    defer freeTokens(alloc, &tokens);
    if (tokens.items.len == 0 or tokens.items[0].kind != .identifier) return null;

    if (std.ascii.eqlIgnoreCase(tokens.items[0].text, "update")) {
        var target_index: usize = 1;
        _ = consumeKeyword(tokens.items, &target_index, "only");
        if (target_index >= tokens.items.len or tokens.items[target_index].kind != .identifier) return error.UnsupportedSqlShape;
        const target = try normalizeSqlObjectIdentifierAlloc(alloc, tokens.items[target_index].text);
        var target_transferred = false;
        errdefer if (!target_transferred) alloc.free(target);

        const from_index = findTopLevelKeyword(tokens.items[target_index + 1 ..], "from") orelse {
            alloc.free(target);
            return null;
        };
        var source_index = target_index + 1 + from_index + 1;
        _ = consumeKeyword(tokens.items, &source_index, "only");
        if (source_index >= tokens.items.len or tokens.items[source_index].kind != .identifier) return error.UnsupportedSqlShape;
        const source = try normalizeSqlObjectIdentifierAlloc(alloc, tokens.items[source_index].text);
        errdefer alloc.free(source);

        target_transferred = true;
        return .{ .target = target, .source = source };
    }

    if (std.ascii.eqlIgnoreCase(tokens.items[0].text, "delete")) {
        var target_index: usize = 1;
        if (!consumeKeyword(tokens.items, &target_index, "from")) return null;
        _ = consumeKeyword(tokens.items, &target_index, "only");
        if (target_index >= tokens.items.len or tokens.items[target_index].kind != .identifier) return error.UnsupportedSqlShape;
        const target = try normalizeSqlObjectIdentifierAlloc(alloc, tokens.items[target_index].text);
        var target_transferred = false;
        errdefer if (!target_transferred) alloc.free(target);

        const using_index = findTopLevelKeyword(tokens.items[target_index + 1 ..], "using") orelse {
            alloc.free(target);
            return null;
        };
        var source_index = target_index + 1 + using_index + 1;
        _ = consumeKeyword(tokens.items, &source_index, "only");
        if (source_index >= tokens.items.len or tokens.items[source_index].kind != .identifier) return error.UnsupportedSqlShape;
        const source = try normalizeSqlObjectIdentifierAlloc(alloc, tokens.items[source_index].text);
        errdefer alloc.free(source);

        target_transferred = true;
        return .{ .target = target, .source = source };
    }

    return null;
}

const ReadSourceTableNames = struct {
    left: []const u8,
    source: []const u8,

    fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        alloc.free(@constCast(self.left));
        alloc.free(@constCast(self.source));
        self.* = undefined;
    }
};

fn readSourceTableNamesAlloc(alloc: std.mem.Allocator, sql: []const u8) !?ReadSourceTableNames {
    var tokens = try tokenizeAlloc(alloc, sql);
    defer freeTokens(alloc, &tokens);
    if (tokens.items.len == 0 or tokens.items[0].kind != .identifier or !std.ascii.eqlIgnoreCase(tokens.items[0].text, "select")) return null;

    const from_index = findTopLevelKeyword(tokens.items, "from") orelse return null;
    var left_index = from_index + 1;
    _ = consumeKeyword(tokens.items, &left_index, "only");
    if (left_index >= tokens.items.len or tokens.items[left_index].kind != .identifier) return error.UnsupportedSqlShape;
    const left = try normalizeSqlObjectIdentifierAlloc(alloc, tokens.items[left_index].text);
    var left_transferred = false;
    errdefer if (!left_transferred) alloc.free(left);

    const join_index = if (findTopLevelKeyword(tokens.items[left_index + 1 ..], "join")) |relative|
        left_index + 1 + relative
    else {
        alloc.free(left);
        return null;
    };
    var source_index = join_index + 1;
    if (consumeKeyword(tokens.items, &source_index, "lateral")) {
        if (source_index >= tokens.items.len or tokens.items[source_index].kind != .lparen) return error.UnsupportedSqlShape;
        const close_index = findMatchingRParenIndex(tokens.items, source_index) orelse return error.UnsupportedSqlShape;
        const inner_from = findTopLevelKeyword(tokens.items[source_index + 1 .. close_index], "from") orelse return error.UnsupportedSqlShape;
        source_index = source_index + 1 + inner_from + 1;
    }
    _ = consumeKeyword(tokens.items, &source_index, "only");
    if (source_index >= tokens.items.len or tokens.items[source_index].kind != .identifier) return error.UnsupportedSqlShape;
    const source = try normalizeSqlObjectIdentifierAlloc(alloc, tokens.items[source_index].text);
    errdefer alloc.free(source);

    left_transferred = true;
    return .{ .left = left, .source = source };
}

fn consumeKeyword(tokens: []const Token, index: *usize, keyword: []const u8) bool {
    if (index.* >= tokens.len) return false;
    const token = tokens[index.*];
    if (token.kind != .identifier or !std.ascii.eqlIgnoreCase(token.text, keyword)) return false;
    index.* += 1;
    return true;
}

fn findTopLevelKeyword(tokens: []const Token, keyword: []const u8) ?usize {
    var depth: usize = 0;
    for (tokens, 0..) |token, i| {
        switch (token.kind) {
            .lparen => depth += 1,
            .rparen => {
                if (depth == 0) return null;
                depth -= 1;
            },
            .semicolon => if (depth == 0) return null,
            .identifier => if (depth == 0 and std.ascii.eqlIgnoreCase(token.text, keyword)) return i,
            else => {},
        }
    }
    return null;
}

fn findMatchingRParenIndex(tokens: []const Token, lparen_index: usize) ?usize {
    if (lparen_index >= tokens.len or tokens[lparen_index].kind != .lparen) return null;
    var depth: usize = 1;
    var index = lparen_index + 1;
    while (index < tokens.len) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen => depth += 1,
            .rparen => {
                depth -= 1;
                if (depth == 0) return index;
            },
            else => {},
        }
    }
    return null;
}

fn catalogRuntimeSchemaAlloc(
    alloc: std.mem.Allocator,
    catalog: table_catalog.CatalogSource,
    table_name: []const u8,
) !runtime_schema.TableSchema {
    var snapshot = try catalog.adminSnapshot();
    defer catalog.freeAdminSnapshot(&snapshot);
    const schema_json = catalogTableSchemaJson(&snapshot, table_name) orelse return error.InvalidSqlCatalog;
    if (schema_json.len == 0) return error.InvalidSqlCatalog;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    return try schema_api.deriveRuntimeTableSchema(alloc, parsed);
}

fn catalogTableSchemaJson(snapshot: *const metadata_api.AdminSnapshot, table_name: []const u8) ?[]const u8 {
    for (snapshot.tables) |table| {
        if (std.mem.eql(u8, table.name, table_name)) return table.schema_json;
    }
    return null;
}

const AppParitySourceSchemaCatalog = struct {
    tables: [1]metadata_table_manager.TableRecord,

    fn init(table_name: []const u8, source_schema_json: []const u8) @This() {
        return .{ .tables = .{
            .{ .table_id = 90_001, .name = table_name, .placement_role = "data", .schema_json = source_schema_json },
        } };
    }

    fn iface(self: *@This()) table_catalog.CatalogSource {
        return .{
            .ptr = self,
            .vtable = &.{
                .admin_snapshot = adminSnapshot,
                .free_admin_snapshot = freeAdminSnapshot,
            },
        };
    }

    fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        return .{
            .status = .{ .metadata_group_id = 1, .metrics = .{} },
            .tables = self.tables[0..],
            .ranges = @constCast((&[_]metadata_table_manager.RangeRecord{})[0..]),
            .stores = @constCast((&[_]metadata_table_manager.StoreRecord{})[0..]),
            .placement_intents = @constCast((&[_]raft_reconciler.PlacementIntent{})[0..]),
            .split_transitions = @constCast((&[_]metadata_transition_state.SplitTransitionRecord{})[0..]),
            .merge_transitions = @constCast((&[_]metadata_transition_state.MergeTransitionRecord{})[0..]),
        };
    }

    fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
};

fn appParitySourceTableNameAlloc(alloc: std.mem.Allocator, entry: AppParityCorpusEntry) !?[]const u8 {
    if (entry.source_schema_json.len == 0) return null;

    switch (entry.family) {
        .insert_source => {
            var tables = (try insertSourceTableNamesAlloc(alloc, entry.sql)) orelse return error.InvalidSqlCatalog;
            defer tables.deinit(alloc);
            return try alloc.dupe(u8, tables.source);
        },
        .update_joined_source,
        .delete_joined_source,
        => {
            var tables = (try joinedWriteSourceTableNamesAlloc(alloc, entry.sql)) orelse return error.InvalidSqlCatalog;
            defer tables.deinit(alloc);
            return try alloc.dupe(u8, tables.source);
        },
        .read,
        .join,
        .lateral,
        => {
            var tables = (try readSourceTableNamesAlloc(alloc, entry.sql)) orelse return error.InvalidSqlCatalog;
            defer tables.deinit(alloc);
            return try alloc.dupe(u8, tables.source);
        },
        else => return error.InvalidSqlCatalog,
    }
}

const Parser = struct {
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: usize = 0,
    schema: runtime_schema.TableSchema = .{},
    joined_source_schema: ?runtime_schema.TableSchema = null,
    params: []const SqlValue = &.{},
    unique_resolver: ?relational_rows.UniqueSelectorResolver = null,
    mutation_claim: ?db_mod.types.RowClaimRequest = null,
    returning_expression_qualifiers: []const []const u8 = &.{},
    field_expression_qualifiers: []const []const u8 = &.{},
    joined_target_expression_qualifiers: []const []const u8 = &.{},
    joined_source_expression_qualifiers: []const []const u8 = &.{},
    insert_source_allows_different_table: bool = false,
    row_expression_field_source_override: ?db_mod.types.RelationalRowsExpressionFieldSource = null,
    conflict_existing_qualifiers: []const []const u8 = &.{},

    fn parseDdlPlan(self: *@This()) !LoweredDdlPlan {
        if (self.matchKeyword("create")) {
            if (self.matchKeyword("or")) {
                try self.expectKeyword("replace");
                if (self.peekKeyword("trigger")) {
                    return .{ .create_update_policy = try self.parseCreateTriggerPolicyDdl() };
                }
                if (!self.peekKeyword("table")) return error.UnsupportedSqlShape;
                var create_table = try self.parseCreateTableDdl();
                if (create_table.if_not_exists) {
                    create_table.deinit(self.alloc);
                    return error.UnsupportedSqlShape;
                }
                create_table.replace_existing = true;
                return .{ .create_table = create_table };
            }
            const unique = self.matchKeyword("unique");
            if (self.peekKeyword("index")) {
                return .{ .create_index = try self.parseCreateIndexDdl(unique) };
            }
            if (unique) return error.UnsupportedSqlShape;
            if (self.peekKeyword("trigger")) {
                return .{ .create_update_policy = try self.parseCreateTriggerPolicyDdl() };
            }
            return .{ .create_table = try self.parseCreateTableDdl() };
        }
        if (self.matchKeyword("alter")) {
            return .{ .alter_table = try self.parseAlterTableDdl() };
        }
        if (self.matchKeyword("drop")) {
            if (self.peekKeyword("table")) return .{ .drop_table = try self.parseDropTableDdl() };
            if (self.peekKeyword("trigger")) return .{ .alter_table = try self.parseDropTriggerPolicyDdl() };
            return .{ .drop_index = try self.parseDropIndexDdl() };
        }
        return error.UnsupportedSqlShape;
    }

    fn parseDropTableDdl(self: *@This()) !DropTablePlan {
        try self.expectKeyword("table");
        var if_exists = false;
        if (self.matchKeyword("if")) {
            try self.expectKeyword("exists");
            if_exists = true;
        }
        const table_name = try self.parseSqlObjectIdentifierOwned();
        var table_name_transferred = false;
        errdefer if (!table_name_transferred) self.alloc.free(table_name);
        if (self.match(.comma) != null) return error.UnsupportedSqlShape;
        const cascade = self.matchKeyword("cascade");
        if (!cascade) _ = self.matchKeyword("restrict");
        if (self.match(.semicolon) != null and !self.atEnd()) return error.UnsupportedSqlShape;
        if (!self.atEnd()) return error.UnsupportedSqlShape;
        table_name_transferred = true;
        return .{ .table_name = table_name, .if_exists = if_exists, .cascade = cascade };
    }

    fn parseDropIndexDdl(self: *@This()) !DropIndexPlan {
        try self.expectKeyword("index");
        _ = self.matchKeyword("concurrently");
        var if_exists = false;
        if (self.matchKeyword("if")) {
            try self.expectKeyword("exists");
            if_exists = true;
        }
        const index_name = try self.parseSqlObjectIdentifierOwned();
        var index_name_transferred = false;
        errdefer if (!index_name_transferred) self.alloc.free(index_name);
        _ = self.matchKeyword("cascade") or self.matchKeyword("restrict");
        if (self.match(.semicolon) != null and !self.atEnd()) return error.UnsupportedSqlShape;
        if (!self.atEnd()) return error.UnsupportedSqlShape;
        index_name_transferred = true;
        return .{ .index_name = index_name, .if_exists = if_exists };
