    fn parseDropTriggerPolicyDdl(self: *@This()) !AlterTablePlan {
        try self.expectKeyword("trigger");
        var if_exists = false;
        if (self.matchKeyword("if")) {
            try self.expectKeyword("exists");
            if_exists = true;
        }
        const trigger_name = try self.parseIdentifierOwned();
