    fn parseOptionalDistinctOnAlloc(self: *@This()) ![]const []const u8 {
        if (!self.matchKeyword("distinct")) return &.{};
        if (!self.matchKeyword("on")) return error.UnsupportedSqlShape;
        try self.expect(.lparen);
        var fields = std.ArrayListUnmanaged([]const u8).empty;
        errdefer {
            for (fields.items) |field| self.alloc.free(field);
            fields.deinit(self.alloc);
        }
        while (true) {
            const parsed_field = try self.parseFieldExpressionOwned();
            defer self.alloc.free(parsed_field);
            const field = try self.normalizeRowExpressionFieldAlloc(parsed_field);
            var field_transferred = false;
            errdefer if (!field_transferred) self.alloc.free(field);
            if (self.peekKind(.lparen) or self.peekKind(.arrow_text) or self.peekKind(.arrow_json)) return error.UnsupportedSqlShape;
            if (relationalColumnForField(self.schema, field, null) == null) return error.InvalidSqlCatalog;
            try fields.append(self.alloc, field);
            field_transferred = true;
            if (self.match(.comma) == null) break;
        }
        try self.expect(.rparen);
        if (fields.items.len == 0) return error.UnsupportedSqlShape;
        return try fields.toOwnedSlice(self.alloc);
    }

    fn validateDistinctOnOrder(
        self: *@This(),
        distinct_on: []const []const u8,
        order_by: []const db_mod.types.RelationalRowsQueryOrder,
    ) !void {
        _ = self;
        if (order_by.len < distinct_on.len) return error.UnsupportedSqlShape;
        for (distinct_on, 0..) |field, i| {
            if (order_by[i].expression != null or !std.mem.eql(u8, order_by[i].field, field)) return error.UnsupportedSqlShape;
        }
    }

    fn selectListContainsField(select: SelectList, field: []const u8) bool {
        if (select.select_all) return true;
        for (select.fields) |selected| {
            if (std.mem.eql(u8, selected, field)) return true;
        }
        for (select.field_aliases) |projection| {
            if (std.mem.eql(u8, projection.output, field) or std.mem.eql(u8, projection.field, field)) return true;
        }
        return false;
    }

