    }

    fn parseConflictExpressionWithExpectedAlloc(
        self: *@This(),
        column: runtime_schema.RelationalColumn,
        insert_columns: []const []const u8,
        expected_type: ?runtime_schema.AntflyType,
    ) anyerror!db_mod.types.RelationalRowsExpression {
        if (self.peekKeyword("cast")) return try self.parseConflictCastExpressionAlloc(column, insert_columns);
        if (self.peekKeyword("case")) return try self.parseConflictCaseExpressionAlloc(column, insert_columns);
        if (self.peekKeyword("lower") or self.peekKeyword("upper") or self.peekKeyword("trim")) return try self.parseConflictCaseFoldExpressionAlloc(column, insert_columns, expected_type);
        if (self.peekKeyword("replace")) return try self.parseConflictReplaceExpressionAlloc(column, insert_columns, expected_type);
        if (self.peekKeyword("coalesce")) return try self.parseConflictCoalesceExpressionAlloc(column, insert_columns, expected_type);
        if (self.peekKeyword("nullif")) return try self.parseConflictNullifExpressionAlloc(column, insert_columns);
        if (self.peekLengthFunctionKeyword()) return try self.parseConflictLengthExpressionAlloc(column, insert_columns, expected_type);
        if (self.peekKeyword("abs")) return try self.parseConflictAbsExpressionAlloc(column, insert_columns);
        if (self.peekKeyword("round")) return try self.parseConflictRoundExpressionAlloc(column, insert_columns);
        if (self.peekFunctionCall("floor")) return try self.parseConflictFloorCeilExpressionAlloc(column, insert_columns, .floor);
        if (self.peekFunctionCall("ceil")) return try self.parseConflictFloorCeilExpressionAlloc(column, insert_columns, .ceil);
        if (self.peekKeyword("greatest") or self.peekKeyword("least")) return try self.parseConflictGreatestLeastExpressionAlloc(column, insert_columns, expected_type);
        if (self.peekKeyword("array_length")) return try self.parseConflictArrayLengthExpressionAlloc(insert_columns);
        if (self.peekKeyword("now") or self.peekKeyword("current_timestamp")) return try self.parseConflictNowExpressionAlloc(expected_type);
        if (self.peekKeyword("interval")) {
            if (expected_type) |field_type| {
                if (field_type != .numeric and field_type != .datetime) return error.UnsupportedSqlShape;
            }
            return try self.parseIntervalRowExpressionAlloc();
        }
        return try self.parseConflictExpressionOperandAlloc(column, insert_columns, expected_type);
    }

    fn parseConflictExpressionOperandAlloc(
        self: *@This(),
        column: runtime_schema.RelationalColumn,
        insert_columns: []const []const u8,
        expected_type: ?runtime_schema.AntflyType,
    ) anyerror!db_mod.types.RelationalRowsExpression {
        if (self.peekKind(.minus)) {
            return try self.parseConflictUnaryNegativeExpressionAlloc(column, insert_columns, expected_type);
        }
        if (self.peekKind(.lparen)) {
            return try self.parseParenthesizedConflictExpressionAlloc(column, insert_columns, expected_type);
        }
        if (self.peekKeyword("cast") or
            self.peekKeyword("case") or
            self.peekKeyword("lower") or
            self.peekKeyword("upper") or
            self.peekKeyword("trim") or
            self.peekKeyword("replace") or
            self.peekKeyword("coalesce") or
            self.peekKeyword("nullif") or
            self.peekLengthFunctionKeyword() or
            self.peekKeyword("abs") or
            self.peekKeyword("round") or
            self.peekFunctionCall("floor") or
            self.peekFunctionCall("ceil") or
            self.peekKeyword("greatest") or
            self.peekKeyword("least") or
            self.peekKeyword("array_length") or
            self.peekKeyword("now") or
            self.peekKeyword("current_timestamp") or
            self.peekKeyword("interval"))
        {
            return try self.parseConflictExpressionAlloc(column, insert_columns);
        }
        if (self.peekKind(.identifier) and
            !self.peekKeyword("null") and
            !self.peekKeyword("true") and
            !self.peekKeyword("false"))
        {
            return try self.parseConflictFieldExpressionAlloc(insert_columns, expected_type);
        }
        const value_json = try self.parseJsonValueAlloc();
        errdefer self.alloc.free(value_json);
        return .{ .kind = .value, .value_json = value_json };
    }

    fn parseParenthesizedConflictExpressionAlloc(
        self: *@This(),
        column: runtime_schema.RelationalColumn,
        insert_columns: []const []const u8,
        expected_type: ?runtime_schema.AntflyType,
    ) anyerror!db_mod.types.RelationalRowsExpression {
        try self.expect(.lparen);
        var expression = try self.parseConflictExpressionWithExpectedAlloc(column, insert_columns, expected_type);
        var expression_owned = true;
        errdefer if (expression_owned) freeExpression(self.alloc, expression);
        if (self.peekArithmeticOperator()) |_| {
            try self.validateNumericOrDatetimeRowExpression(expression);
            expression_owned = false;
            expression = try self.parseConflictArithmeticExpressionRestAlloc(expression, column, insert_columns, 0);
            expression_owned = true;
            try self.validateNumericRowExpression(expression);
        }
        if (self.peekKind(.pipe_concat)) {
            expression_owned = false;
            expression = try self.parseConflictPipeConcatExpressionRestAlloc(expression, column, insert_columns);
            expression_owned = true;
            try self.validateTextRowExpression(expression);
        }
        try self.expect(.rparen);
        expression_owned = false;
        return expression;
    }

    fn parseConflictUnaryNegativeExpressionAlloc(
        self: *@This(),
        column: runtime_schema.RelationalColumn,
        insert_columns: []const []const u8,
        expected_type: ?runtime_schema.AntflyType,
    ) anyerror!db_mod.types.RelationalRowsExpression {
        _ = self.match(.minus) orelse return error.UnsupportedSqlShape;
        if (self.match(.number)) |token| {
            return .{
                .kind = .value,
                .value_json = try std.fmt.allocPrint(self.alloc, "-{s}", .{token.text}),
            };
        }

        const operand = try self.parseConflictExpressionOperandAlloc(column, insert_columns, expected_type);
        var operand_transferred = false;
        errdefer if (!operand_transferred) freeExpression(self.alloc, operand);
        const negative_one = try self.alloc.dupe(u8, "-1");
        var negative_one_transferred = false;
        errdefer if (!negative_one_transferred) self.alloc.free(negative_one);
        const operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 2);
        var operands_transferred = false;
        errdefer if (!operands_transferred) self.alloc.free(operands);
        operands[0] = .{ .kind = .value, .value_json = negative_one };
        operands[1] = operand;
        negative_one_transferred = true;
        operand_transferred = true;
        operands_transferred = true;
        return .{
            .kind = .mul,
            .operands = operands,
        };
    }

    fn parseConflictFieldExpressionAlloc(
        self: *@This(),
        insert_columns: []const []const u8,
        expected_type: ?runtime_schema.AntflyType,
    ) !db_mod.types.RelationalRowsExpression {
        const token = self.match(.identifier) orelse return error.UnsupportedSqlShape;
        const source: db_mod.types.RelationalRowsExpressionFieldSource = if (std.mem.startsWith(u8, token.text, "excluded.")) {
            const field = token.text["excluded.".len..];
            const source_column = relationalColumnForField(self.schema, field, null) orelse return error.InvalidSqlCatalog;
            if (expected_type) |field_type| if (source_column.field_type != field_type) return error.UnsupportedSqlShape;
            if (!conflictProposedColumnAvailable(insert_columns, source_column, field)) return error.UnsupportedSqlShape;
            return .{
                .kind = .field,
                .field = try self.alloc.dupe(u8, field),
                .field_source = .proposed,
            };
        } else blk: {
            const field = self.conflictExistingFieldName(token.text) orelse token.text;
            const source_column = relationalColumnForField(self.schema, field, null) orelse return error.InvalidSqlCatalog;
            if (expected_type) |field_type| if (source_column.field_type != field_type) return error.UnsupportedSqlShape;
            break :blk .existing;
        };
        const field = self.conflictExistingFieldName(token.text) orelse token.text;
        return .{
            .kind = .field,
            .field = try self.alloc.dupe(u8, field),
            .field_source = source,
        };
    }

    fn parseConflictNowExpressionAlloc(
        self: *@This(),
        expected_type: ?runtime_schema.AntflyType,
    ) !db_mod.types.RelationalRowsExpression {
        if (expected_type) |field_type| {
            if (field_type != .numeric and field_type != .datetime) return error.UnsupportedSqlShape;
        }
        return try self.parseNowRowExpressionAlloc();
    }

    fn parseConflictCastExpressionAlloc(
        self: *@This(),
        column: runtime_schema.RelationalColumn,
