    fn parseConflictArithmeticExpressionRestAlloc(
        self: *@This(),
        lhs: db_mod.types.RelationalRowsExpression,
        column: runtime_schema.RelationalColumn,
        insert_columns: []const []const u8,
        min_precedence: u8,
    ) anyerror!db_mod.types.RelationalRowsExpression {
        var current = lhs;
        var current_owned = true;
        errdefer if (current_owned) freeExpression(self.alloc, current);

        while (self.peekArithmeticOperator()) |op| {
            if (op.precedence < min_precedence) break;
            _ = self.match(op.token) orelse unreachable;
            var rhs = if (self.peekKeyword("interval"))
                try self.parseIntervalRowExpressionAlloc()
            else
                try self.parseConflictExpressionAlloc(column, insert_columns);
            var rhs_owned = true;
            errdefer if (rhs_owned) freeExpression(self.alloc, rhs);

            while (self.peekArithmeticOperator()) |next_op| {
                if (next_op.precedence <= op.precedence) break;
                rhs_owned = false;
                rhs = try self.parseConflictArithmeticExpressionRestAlloc(rhs, column, insert_columns, next_op.precedence);
                rhs_owned = true;
            }

            const operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 2);
            var operands_owned = true;
            errdefer if (operands_owned) self.alloc.free(operands);
            operands[0] = current;
            operands[1] = rhs;
            current_owned = false;
            rhs_owned = false;
            operands_owned = false;
            current = .{
                .kind = op.kind,
                .operands = operands,
            };
            current_owned = true;
            try self.validateNumericRowExpression(current);
        }

        current_owned = false;
        return current;
    }

    fn peekArithmeticRhsKeyword(self: *@This(), keyword: []const u8) bool {
        if (self.pos + 2 >= self.tokens.len) return false;
        const op = self.tokens[self.pos + 1].kind;
        if (op != .plus and op != .minus and op != .star and op != .slash) return false;
        const rhs = self.tokens[self.pos + 2];
        return rhs.kind == .identifier and std.ascii.eqlIgnoreCase(rhs.text, keyword);
    }

