    fn joinedMutationSourceBodyJsonAlloc(
        self: *@This(),
        op: []const u8,
        source_table: []const u8,
        tail: ParsedJoinedMutationTail,
        source_assignments: []const JoinedMutationSourceAssignment,
        patch: []const FieldJsonValue,
    ) ![]u8 {
        const join = tail.join;
        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.print("{{\"op\":{f},\"source_table\":{f},\"target_side\":\"left\",\"join\":{{\"left\":", .{
            std.json.fmt(op, .{}),
            std.json.fmt(source_table, .{}),
        });
        try self.writeMutationSourceQueryJson(writer, join.left);
        try writer.writeAll(",\"right\":");
        try self.writeMutationSourceQueryJson(writer, join.right);
        try writer.writeAll(",\"on\":[");
        for (join.on, 0..) |predicate, i| {
            if (i != 0) try writer.writeByte(',');
            try writer.print("{{\"left_field\":{f},\"right_field\":{f}}}", .{
                std.json.fmt(predicate.left_field, .{}),
                std.json.fmt(predicate.right_field, .{}),
            });
        }
        try writer.writeByte(']');
        if (join.order_by.len > 0) {
            try writer.writeAll(",\"order_by\":[");
            for (join.order_by, 0..) |order, i| {
                if (i != 0) try writer.writeByte(',');
                if (order.expression != null) return error.UnsupportedSqlShape;
                try writer.print("{{\"field\":{f}", .{std.json.fmt(order.field, .{})});
                if (order.direction == .desc) try writer.writeAll(",\"direction\":\"desc\"");
                try writer.writeByte('}');
            }
            try writer.writeByte(']');
        }
        if (join.limit) |limit| try writer.print(",\"limit\":{d}", .{limit});
        if (join.offset != 0) try writer.print(",\"offset\":{d}", .{join.offset});
        try writer.writeByte('}');
        if (tail.match_expression_predicates.len > 0) {
            try writer.writeAll(",\"match_expression_where\":[");
            for (tail.match_expression_predicates, 0..) |condition, i| {
                if (i != 0) try writer.writeByte(',');
                try writeRowExpressionConditionJson(writer, condition);
            }
            try writer.writeByte(']');
        }
        if (tail.match_expression_or_predicates.len > 0) {
            try writer.writeByte(',');
            try writeRowExpressionPredicateGroupsJson(writer, "match_expression_any", tail.match_expression_or_predicates);
        }
        if (tail.match_expression_not_predicates.len > 0) {
            try writer.writeByte(',');
            try writeRowExpressionPredicateGroupsJson(writer, "match_expression_not", tail.match_expression_not_predicates);
        }
        if (tail.match_expression_array_contains.len > 0) {
            try writer.writeAll(",\"match_expression_array_contains\":[");
            for (tail.match_expression_array_contains, 0..) |predicate, i| {
                if (i != 0) try writer.writeByte(',');
                try writer.writeAll("{\"expr\":");
                try writeRowExpressionJson(writer, predicate.expression);
                try writer.writeAll(",\"value\":");
                try writer.writeAll(predicate.value_json);
                try writer.writeByte('}');
            }
            try writer.writeByte(']');
        }
        if (source_assignments.len > 0) {
            try writer.writeAll(",\"source_assignments\":[");
            for (source_assignments, 0..) |assignment, i| {
                if (i != 0) try writer.writeByte(',');
                try writer.print("{{\"target_field\":{f},\"side\":{f},\"field\":{f}}}", .{
                    std.json.fmt(assignment.field, .{}),
                    std.json.fmt("right", .{}),
                    std.json.fmt(assignment.source_field, .{}),
                });
            }
            try writer.writeByte(']');
        }
        if (patch.len > 0) {
            try writer.writeAll(",\"patch\":{");
            for (patch, 0..) |item, i| {
                if (i != 0) try writer.writeByte(',');
                try writer.print("{f}:", .{std.json.fmt(item.field, .{})});
                try writer.writeAll(item.value_json);
            }
            try writer.writeByte('}');
        }
        try self.writeReturningProjectionJson(writer, tail.returning);
        try writer.writeByte('}');
        return try out.toOwnedSlice();
    }

    fn writeMutationSourceQueryJson(
        self: *@This(),
        writer: *std.Io.Writer,
        source: db_mod.types.RelationalRowsQueryRequest,
    ) !void {
        _ = self;
        try writer.writeByte('{');
        var wrote = false;
        if (source.predicates.len > 0 or
            source.array_contains.len > 0 or
            source.array_eq.len > 0 or
            source.array_any.len > 0 or
            source.in_predicates.len > 0 or
            source.json_contains.len > 0 or
            source.json_path_eq.len > 0 or
            source.json_path_exists.len > 0 or
            source.text_patterns.len > 0 or
            source.or_predicates.len > 0 or
            source.not_predicates.len > 0)
        {
            try writer.writeAll("\"where\":{");
            var wrote_where = false;
            if (source.predicates.len > 0 or source.array_contains.len > 0 or source.array_eq.len > 0 or source.array_any.len > 0 or source.in_predicates.len > 0 or source.json_contains.len > 0 or source.json_path_eq.len > 0 or source.json_path_exists.len > 0 or source.text_patterns.len > 0) {
                try writer.writeAll("\"all\":[");
                var wrote_atom = false;
                try writeRelationalCheckAtomsJson(writer, &wrote_atom, source.predicates);
                try writeInPredicateAtomsJson(writer, &wrote_atom, source.in_predicates);
                try writeTextPatternPredicateAtomsJson(writer, &wrote_atom, source.text_patterns);
                try writeStructuredValuePredicateAtomsJson(writer, &wrote_atom, "array_any", source.array_any);
                try writeStructuredValuePredicateAtomsJson(writer, &wrote_atom, "array_contains", source.array_contains);
                try writeStructuredValuePredicateAtomsJson(writer, &wrote_atom, "array_eq", source.array_eq);
                try writeStructuredValuePredicateAtomsJson(writer, &wrote_atom, "json_contains", source.json_contains);
                try writeJsonPathEqPredicateAtomsJson(writer, &wrote_atom, source.json_path_eq);
                try writeJsonPathExistsPredicateAtomsJson(writer, &wrote_atom, source.json_path_exists);
                try writer.writeByte(']');
                wrote_where = true;
            }
            if (source.or_predicates.len > 0) {
                if (wrote_where) try writer.writeByte(',');
                try writer.writeAll("\"any\":[");
                for (source.or_predicates, 0..) |group, group_i| {
                    if (group_i != 0) try writer.writeByte(',');
                    if (group.predicates.len == 1) {
                        try writeRelationalCheckAtomJson(writer, group.predicates[0]);
                    } else {
                        try writer.writeAll("{\"all\":[");
                        var wrote_atom = false;
                        try writeRelationalCheckAtomsJson(writer, &wrote_atom, group.predicates);
                        try writer.writeAll("]}");
                    }
                }
                try writer.writeByte(']');
                wrote_where = true;
            }
            if (source.not_predicates.len > 0) {
                if (wrote_where) try writer.writeByte(',');
                try writer.writeAll("\"not\":[");
                for (source.not_predicates, 0..) |group, group_i| {
                    if (group_i != 0) try writer.writeByte(',');
                    if (group.predicates.len == 1) {
                        try writeRelationalCheckAtomJson(writer, group.predicates[0]);
                    } else {
                        try writer.writeAll("{\"all\":[");
                        var wrote_atom = false;
                        try writeRelationalCheckAtomsJson(writer, &wrote_atom, group.predicates);
                        try writer.writeAll("]}");
                    }
                }
                try writer.writeByte(']');
            }
            try writer.writeByte('}');
            wrote = true;
        }
        if (source.expression_predicates.len > 0) {
            if (wrote) try writer.writeByte(',');
            try writer.writeAll("\"expression_where\":[");
            for (source.expression_predicates, 0..) |condition, i| {
                if (i != 0) try writer.writeByte(',');
                try writeRowExpressionConditionJson(writer, condition);
            }
            try writer.writeByte(']');
            wrote = true;
        }
        if (source.expression_or_predicates.len > 0) {
            if (wrote) try writer.writeByte(',');
            try writeRowExpressionPredicateGroupsJson(writer, "expression_any", source.expression_or_predicates);
            wrote = true;
        }
        if (source.expression_not_predicates.len > 0) {
            if (wrote) try writer.writeByte(',');
            try writeRowExpressionPredicateGroupsJson(writer, "expression_not", source.expression_not_predicates);
            wrote = true;
        }
        if (source.expression_array_contains.len > 0) {
            if (wrote) try writer.writeByte(',');
            try writer.writeAll("\"expression_array_contains\":[");
            for (source.expression_array_contains, 0..) |predicate, i| {
                if (i != 0) try writer.writeByte(',');
                try writer.writeAll("{\"expr\":");
                try writeRowExpressionJson(writer, predicate.expression);
                try writer.writeAll(",\"value\":");
                try writer.writeAll(predicate.value_json);
                try writer.writeByte('}');
            }
            try writer.writeByte(']');
            wrote = true;
        }
        if (source.order_by.len > 0) {
            if (wrote) try writer.writeByte(',');
            try writer.writeAll("\"order_by\":[");
            for (source.order_by, 0..) |order, i| {
                if (i != 0) try writer.writeByte(',');
                if (order.expression) |expression| {
                    try writer.writeAll("{\"expr\":");
                    try writeRowExpressionJson(writer, expression);
                } else {
                    try writer.print("{{\"field\":{f}", .{std.json.fmt(order.field, .{})});
                }
                if (order.direction == .desc) try writer.writeAll(",\"direction\":\"desc\"");
                try writer.writeByte('}');
            }
            try writer.writeByte(']');
            wrote = true;
        }
        if (source.limit) |limit| {
            if (wrote) try writer.writeByte(',');
            try writer.print("\"limit\":{d}", .{limit});
            wrote = true;
        }
        if (source.offset != 0) {
            if (wrote) try writer.writeByte(',');
            try writer.print("\"offset\":{d}", .{source.offset});
            wrote = true;
        }
        if (source.row_claim) |claim| {
            if (wrote) try writer.writeByte(',');
            const txn_id = claim.txn_id orelse return error.UnsupportedRowsQuery;
            const txn_hex = encodeSqlTxnIdHex(txn_id);
            try writer.print("\"row_claim\":{{\"mode\":\"for_update\",\"skip_locked\":{},\"lease_ms\":{d},\"owner_id\":{f},\"transaction_id\":\"{s}\"}}", .{
                claim.skip_locked,
                claim.lease_ms,
                std.json.fmt(claim.owner_id, .{}),
                txn_hex,
            });
        }
        try writer.writeByte('}');
    }

    fn writeReturningJson(self: *@This(), writer: *std.Io.Writer, returning_fields: []const []const u8) !void {
        _ = self;
        if (returning_fields.len == 0) return;
        try writer.writeAll(",\"returning\":[");
        for (returning_fields, 0..) |field, i| {
            if (i != 0) try writer.writeByte(',');
            try writer.print("{f}", .{std.json.fmt(field, .{})});
        }
        try writer.writeByte(']');
    }

    fn writeReturningProjectionJson(self: *@This(), writer: *std.Io.Writer, returning: ReturningProjection) !void {
        if (returning.fields.len > 0) try self.writeReturningJson(writer, returning.fields);
        if (returning.expressions.len == 0) return;
        try writer.writeAll(",\"returning_expressions\":[");
        for (returning.expressions, 0..) |projection, i| {
            if (i != 0) try writer.writeByte(',');
            try writer.print("{{\"as\":{f},\"expr\":", .{std.json.fmt(projection.output, .{})});
            try writeRowExpressionJson(writer, projection.expression);
            try writer.writeByte('}');
        }
        try writer.writeByte(']');
    }

    fn writeRowExpressionJson(writer: *std.Io.Writer, expression: db_mod.types.RelationalRowsExpression) !void {
        switch (expression.kind) {
            .field => {
                try writer.print("{{\"field\":{f}", .{std.json.fmt(expression.field, .{})});
                if (expression.field_source != .row) {
                    try writer.print(",\"source\":{f}", .{std.json.fmt(rowExpressionFieldSourceName(expression.field_source), .{})});
                }
                try writer.writeByte('}');
            },
            .value => {
                try writer.writeAll("{\"value\":");
                try writer.writeAll(expression.value_json);
                try writer.writeByte('}');
            },
            .now => {
                try writer.writeAll("{\"op\":\"now\",\"args\":[]}");
            },
            .case => {
                try writer.writeAll("{\"op\":\"case\",\"cases\":[");
                for (expression.case_branches, 0..) |branch, i| {
                    if (i != 0) try writer.writeByte(',');
                    try writer.writeAll("{\"when\":{\"lhs\":");
                    try writeRowExpressionJson(writer, branch.when.lhs);
                    try writer.print(",\"op\":{f}", .{std.json.fmt(rowExpressionConditionOpName(branch.when.op), .{})});
                    if (branch.when.rhs.len == 1) {
                        try writer.writeAll(",\"rhs\":");
                        try writeRowExpressionJson(writer, branch.when.rhs[0]);
                    }
                    try writer.writeAll("},\"then\":");
                    try writeRowExpressionJson(writer, branch.then);
                    try writer.writeByte('}');
                }
                try writer.writeAll("],\"else\":");
                if (expression.case_else.len != 1) return error.UnsupportedSqlShape;
                try writeRowExpressionJson(writer, expression.case_else[0]);
                try writer.writeByte('}');
            },
            .cast => {
                if (expression.operands.len != 1) return error.UnsupportedSqlShape;
                const cast_type = expression.cast_type orelse return error.UnsupportedSqlShape;
                try writer.print("{{\"op\":\"cast\",\"to\":{f},\"args\":[", .{std.json.fmt(rowExpressionCastTypeName(cast_type), .{})});
                try writeRowExpressionJson(writer, expression.operands[0]);
                try writer.writeAll("]}");
            },
            .json_extract => {
                if (expression.operands.len != 1 or expression.json_path.len == 0) return error.UnsupportedSqlShape;
                try writer.writeAll("{\"op\":\"json_extract\",\"args\":[");
                try writeRowExpressionJson(writer, expression.operands[0]);
                try writer.print("],\"path\":{f}", .{std.json.fmt(expression.json_path, .{})});
                if (expression.json_as_text) try writer.writeAll(",\"as_text\":true");
                try writer.writeByte('}');
            },
            else => {
                try writer.print("{{\"op\":{f},\"args\":[", .{std.json.fmt(rowExpressionOpName(expression.kind), .{})});
                for (expression.operands, 0..) |operand, i| {
                    if (i != 0) try writer.writeByte(',');
                    try writeRowExpressionJson(writer, operand);
                }
                try writer.writeAll("]}");
            },
        }
    }

    fn writeRowExpressionConditionJson(writer: *std.Io.Writer, condition: db_mod.types.RelationalRowsExpressionCondition) !void {
        try writer.writeAll("{\"lhs\":");
        try writeRowExpressionJson(writer, condition.lhs);
        try writer.print(",\"op\":{f}", .{std.json.fmt(rowExpressionConditionOpName(condition.op), .{})});
        if (condition.rhs.len == 1) {
            try writer.writeAll(",\"rhs\":");
            try writeRowExpressionJson(writer, condition.rhs[0]);
        }
        try writer.writeByte('}');
    }

    fn writeRowExpressionPredicateGroupsJson(
        writer: *std.Io.Writer,
        field_name: []const u8,
        groups: []const db_mod.types.RelationalRowsExpressionPredicateGroup,
    ) !void {
        try writer.print("{f}:[", .{std.json.fmt(field_name, .{})});
        for (groups, 0..) |group, group_i| {
            if (group_i != 0) try writer.writeByte(',');
            try writer.writeAll("{\"all\":[");
            for (group.conditions, 0..) |condition, condition_i| {
                if (condition_i != 0) try writer.writeByte(',');
                try writeRowExpressionConditionJson(writer, condition);
            }
            try writer.writeAll("]}");
        }
        try writer.writeByte(']');
    }

    fn rowExpressionOpName(kind: db_mod.types.RelationalRowsExpressionKind) []const u8 {
        return switch (kind) {
            .field, .value => unreachable,
            .now => "now",
            .coalesce => "coalesce",
            .lower => "lower",
            .upper => "upper",
            .trim => "trim",
            .replace => "replace",
            .concat => "concat",
            .length => "length",
            .nullif => "nullif",
            .greatest => "greatest",
            .least => "least",
            .abs => "abs",
            .round => "round",
            .floor => "floor",
            .ceil => "ceil",
            .add => "add",
            .sub => "sub",
            .mul => "mul",
            .div => "div",
            .case => unreachable,
            .cast => unreachable,
            .json_extract => unreachable,
            .array_length => "array_length",
            .string_to_array => "string_to_array",
            .interval_ns => "interval_ns",
        };
    }

    fn rowExpressionDefaultOutputName(kind: db_mod.types.RelationalRowsExpressionKind) []const u8 {
        return switch (kind) {
            .field => "field",
            .value => "value",
            .case => "case",
            .cast => "cast",
            .json_extract => "json_extract",
            else => rowExpressionOpName(kind),
        };
    }

    fn rowExpressionFieldSourceName(source: db_mod.types.RelationalRowsExpressionFieldSource) []const u8 {
        return switch (source) {
            .row => "row",
            .existing => "existing",
            .proposed => "proposed",
            .source => "source",
        };
    }

    fn rowExpressionCastTypeName(cast_type: db_mod.types.RelationalRowsExpressionCastType) []const u8 {
        return switch (cast_type) {
            .text => "text",
            .numeric => "numeric",
            .bool => "bool",
        };
    }

    fn rowExpressionConditionOpName(op: runtime_schema.RelationalCheckOp) []const u8 {
        return switch (op) {
            .eq => "eq",
            .ne => "ne",
            .gt => "gt",
            .gte => "gte",
            .lt => "lt",
            .lte => "lte",
            .is_null => "is_null",
            .is_not_null => "is_not_null",
            .is_distinct => "is_distinct",
            .is_not_distinct => "is_not_distinct",
        };
    }

    fn parseWhere(
        self: *@This(),
        predicates: *std.ArrayListUnmanaged(runtime_schema.RelationalCheck),
        json_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate),
        json_path_eq: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathEqPredicate),
        json_path_exists: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate),
        array_any: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayAnyPredicate),
        array_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate),
        array_eq: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate),
        in_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate),
        text_patterns: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate),
        or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
        not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
        access_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup),
        access_not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup),
        expression_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition),
        expression_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        expression_not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        expression_array_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate),
    ) !void {
        if (self.whereHasTopLevelOr()) {
            if (self.whereTopLevelOrHasExpressionPredicateStart()) {
                try self.parseExpressionOrWhere(expression_or_predicates);
            } else if (self.whereTopLevelOrHasAccessPredicate()) {
                try self.parseAccessOrWhere(access_or_predicates);
            } else {
                try self.parseScalarOrWhere(or_predicates);
            }
            return;
        }
        while (true) {
            if (self.canParseScalarNotWhere()) {
                try self.parseScalarNotWhere(not_predicates);
            } else if (self.canParseExpressionNotWhere()) {
                try self.parseExpressionNotWhere(expression_not_predicates);
            } else if (self.canParseAccessNotWhere()) {
                try self.parseAccessNotWhere(access_not_predicates);
            } else if (self.peekKeyword("string_to_array")) {
                if (self.stringToArrayPredicateIsContainment()) {
                    const predicate = try self.parseExpressionArrayContainsPredicateAlloc();
                    var predicate_transferred = false;
                    errdefer if (!predicate_transferred) freeExpressionArrayContainsOne(self.alloc, predicate);
                    try expression_array_contains.append(self.alloc, predicate);
                    predicate_transferred = true;
                } else {
                    try self.parseExpressionWhereConditions(expression_predicates, expression_or_predicates, expression_not_predicates);
                }
            } else if (try self.canParseExpressionWhereCondition()) {
                try self.parseExpressionWhereConditions(expression_predicates, expression_or_predicates, expression_not_predicates);
            } else {
                try self.parseWhereAtom(predicates, json_contains, json_path_eq, json_path_exists, array_any, array_contains, array_eq, in_predicates, text_patterns, or_predicates, false);
            }
            if (!self.matchKeyword("and")) break;
        }
    }

    fn valueEqualsAnyArrayPredicateCanStart(self: *@This()) bool {
        if (self.pos >= self.tokens.len) return false;
        const value_end = switch (self.tokens[self.pos].kind) {
            .string, .number, .placeholder => self.pos + 1,
            .minus => blk: {
                if (self.pos + 1 >= self.tokens.len or self.tokens[self.pos + 1].kind != .number) return false;
                break :blk self.pos + 2;
            },
            .identifier => blk: {
                const text = self.tokens[self.pos].text;
                if (!std.ascii.eqlIgnoreCase(text, "null") and
                    !std.ascii.eqlIgnoreCase(text, "true") and
                    !std.ascii.eqlIgnoreCase(text, "false"))
                {
                    return false;
                }
                break :blk self.pos + 1;
            },
            else => return false,
        };
        if (value_end + 3 >= self.tokens.len) return false;
        return self.tokens[value_end].kind == .eq and
            self.tokens[value_end + 1].kind == .identifier and
            sqlKeywordIsAnyOrSome(self.tokens[value_end + 1].text) and
            self.tokens[value_end + 2].kind == .lparen and
            self.tokens[value_end + 3].kind == .identifier;
    }

    fn canParseExpressionWhereCondition(self: *@This()) !bool {
        if (self.peekStandaloneSqlBooleanLiteral() != null) return true;
        if (self.nextRowExpressionHasTopLevelPipeConcat()) return true;
        if (self.peekKind(.minus)) return true;
        if (self.peekKeyword("array_length") or
            self.peekKeyword("case") or
            self.peekKeyword("cast") or
            self.peekKeyword("coalesce") or
            self.peekKeyword("nullif") or
            self.peekLengthFunctionKeyword() or
            self.peekKeyword("abs") or
            self.peekKeyword("round") or
            self.peekFunctionCall("floor") or
            self.peekFunctionCall("ceil") or
            self.peekKeyword("greatest") or
            self.peekKeyword("least")) return true;
        if (self.expressionNullSafeDistinctPredicateCanStartAt(self.pos)) return true;
        if (self.peekKeyword("lower") or self.peekKeyword("upper")) return !(try self.generatedExpressionCallHasGeneratedColumn());
        if (self.peekKeyword("trim")) return true;
        if (self.peekKeyword("replace")) return true;
        if (self.peekKeyword("concat")) return !(try self.generatedExpressionCallHasGeneratedColumn());
        if (self.jsonExtractNullSafeDistinctPredicateCanStartAt(self.pos)) return true;
        if (self.jsonExtractMembershipPredicateCanStartAt(self.pos)) return true;
        if (self.peekKind(.identifier) and
            !self.peekKeyword("null") and
            !self.peekKeyword("true") and
            !self.peekKeyword("false") and
            self.pos + 1 < self.tokens.len)
        {
            return switch (self.tokens[self.pos + 1].kind) {
                .plus, .minus, .star, .slash, .pipe_concat => true,
                else => false,
            };
        }
        return false;
    }

    fn whereTopLevelOrHasExpressionPredicateStart(self: *@This()) bool {
        var depth: usize = 0;
        var i = self.pos;
        var expect_predicate_start = true;
        while (i < self.tokens.len) : (i += 1) {
            const token = self.tokens[i];
            switch (token.kind) {
                .lparen => {
                    if (depth == 0 and expect_predicate_start) {
                        const inner = self.predicateStartIndexAfterOpenParens(i);
                        if (self.expressionCanStartAt(inner) or self.jsonExtractExpressionPredicateCanStartAt(inner)) return true;
                    }
                    depth += 1;
                    expect_predicate_start = false;
                },
                .rparen => if (depth > 0) {
                    depth -= 1;
                },
                .semicolon => if (depth == 0) return false,
                .identifier => if (depth == 0) {
                    if (tokenStartsWhereTailClause(token.text)) return false;
                    if (std.ascii.eqlIgnoreCase(token.text, "and") or std.ascii.eqlIgnoreCase(token.text, "or")) {
                        expect_predicate_start = true;
                        continue;
                    }
                    if (expect_predicate_start and (self.expressionCanStartAt(i) or self.jsonExtractExpressionPredicateCanStartAt(i))) return true;
                    expect_predicate_start = false;
                },
                .number, .string, .placeholder, .minus => if (depth == 0) {
                    if (expect_predicate_start and self.expressionCanStartAt(i)) return true;
                    expect_predicate_start = false;
                },
                else => if (depth == 0 and expect_predicate_start) {
                    expect_predicate_start = false;
                },
            }
        }
        return false;
    }

    fn whereTopLevelOrHasAccessPredicate(self: *@This()) bool {
        var depth: usize = 0;
        var i = self.pos;
        while (i < self.tokens.len) : (i += 1) {
            const token = self.tokens[i];
            switch (token.kind) {
                .lparen => depth += 1,
                .rparen => if (depth > 0) {
                    depth -= 1;
                },
                .semicolon => if (depth == 0) return false,
                .arrow_text, .arrow_json, .at_contains, .question => return true,
                .identifier => {
                    if (depth == 0 and tokenStartsWhereTailClause(token.text)) return false;
                    if (std.ascii.eqlIgnoreCase(token.text, "like") or
                        std.ascii.eqlIgnoreCase(token.text, "ilike"))
                    {
                        return true;
                    }
                    if (i + 2 < self.tokens.len and
                        (self.tokens[i + 1].kind == .eq or self.tokens[i + 1].kind == .neq) and
                        self.tokens[i + 2].kind == .identifier and
                        std.ascii.eqlIgnoreCase(self.tokens[i + 2].text, "array"))
                    {
                        return true;
                    }
                },
                else => {},
            }
        }
        return false;
    }

    fn canParseAccessNotWhere(self: *@This()) bool {
        if (!self.peekKeyword("not")) return false;
        var i = self.pos + 1;
        while (i < self.tokens.len and self.tokens[i].kind == .lparen) : (i += 1) {}
        if (i >= self.tokens.len) return false;
        var depth: usize = 0;
        while (i < self.tokens.len) : (i += 1) {
            const token = self.tokens[i];
            switch (token.kind) {
                .lparen => depth += 1,
                .rparen => if (depth == 0) {
                    return false;
                } else {
                    depth -= 1;
                },
                .arrow_text, .arrow_json, .at_contains, .question => return true,
                .identifier => {
                    if (std.ascii.eqlIgnoreCase(token.text, "like") or
                        std.ascii.eqlIgnoreCase(token.text, "ilike"))
                    {
                        return true;
                    }
                    if (i + 2 < self.tokens.len and
                        (self.tokens[i + 1].kind == .eq or self.tokens[i + 1].kind == .neq) and
                        self.tokens[i + 2].kind == .identifier and
                        std.ascii.eqlIgnoreCase(self.tokens[i + 2].text, "array"))
                    {
                        return true;
                    }
                },
                else => {},
            }
        }
        return false;
    }

    fn accessPredicateGroupHasAnyPredicate(group: db_mod.types.RelationalRowsAccessPredicateGroup) bool {
        return group.predicates.len > 0 or
            group.array_any.len > 0 or
            group.array_contains.len > 0 or
            group.array_eq.len > 0 or
            group.in_predicates.len > 0 or
            group.json_contains.len > 0 or
            group.json_path_eq.len > 0 or
            group.json_path_exists.len > 0 or
            group.text_patterns.len > 0;
    }

    fn parseAccessPredicateGroupAlloc(self: *@This()) !db_mod.types.RelationalRowsAccessPredicateGroup {
        var predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
        errdefer {
            freeRelationalChecks(self.alloc, predicates.items);
            predicates.deinit(self.alloc);
        }
        var json_path_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathEqPredicate).empty;
        errdefer {
            freeJsonPathEq(self.alloc, json_path_eq.items);
            json_path_eq.deinit(self.alloc);
        }
        var json_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate).empty;
        errdefer {
            freeJsonContains(self.alloc, json_contains.items);
            json_contains.deinit(self.alloc);
        }
        var json_path_exists = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate).empty;
        errdefer {
            freeJsonPathExists(self.alloc, json_path_exists.items);
            json_path_exists.deinit(self.alloc);
        }
        var array_any = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayAnyPredicate).empty;
        errdefer {
            freeArrayAny(self.alloc, array_any.items);
            array_any.deinit(self.alloc);
        }
        var array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate).empty;
        errdefer {
            freeArrayContains(self.alloc, array_contains.items);
            array_contains.deinit(self.alloc);
        }
        var array_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate).empty;
        errdefer {
            freeArrayEq(self.alloc, array_eq.items);
            array_eq.deinit(self.alloc);
        }
        var in_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate).empty;
        errdefer {
            freeInPredicates(self.alloc, in_predicates.items);
            in_predicates.deinit(self.alloc);
        }
        var text_patterns = std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate).empty;
        errdefer {
            freeTextPatterns(self.alloc, text_patterns.items);
            text_patterns.deinit(self.alloc);
        }
        var nested_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup).empty;
        defer {
            freePredicateGroups(self.alloc, nested_or_predicates.items);
            nested_or_predicates.deinit(self.alloc);
        }

        while (true) {
            try self.parseWhereAtom(
                &predicates,
                &json_contains,
                &json_path_eq,
                &json_path_exists,
                &array_any,
                &array_contains,
                &array_eq,
                &in_predicates,
                &text_patterns,
                &nested_or_predicates,
                false,
            );
            if (nested_or_predicates.items.len > 0) return error.UnsupportedSqlShape;
            if (!self.matchKeyword("and")) break;
        }

        const group = db_mod.types.RelationalRowsAccessPredicateGroup{
            .predicates = try predicates.toOwnedSlice(self.alloc),
            .array_any = try array_any.toOwnedSlice(self.alloc),
            .array_contains = try array_contains.toOwnedSlice(self.alloc),
            .array_eq = try array_eq.toOwnedSlice(self.alloc),
            .in_predicates = try in_predicates.toOwnedSlice(self.alloc),
            .json_contains = try json_contains.toOwnedSlice(self.alloc),
            .json_path_eq = try json_path_eq.toOwnedSlice(self.alloc),
            .json_path_exists = try json_path_exists.toOwnedSlice(self.alloc),
            .text_patterns = try text_patterns.toOwnedSlice(self.alloc),
        };
        if (!accessPredicateGroupHasAnyPredicate(group)) {
            freeAccessPredicateGroup(self.alloc, group);
            return error.UnsupportedSqlShape;
        }
        return group;
    }

    fn parseAccessOrWhere(
        self: *@This(),
        access_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup),
    ) !void {
        while (true) {
            const parenthesized = self.match(.lparen) != null;
            const group = try self.parseAccessPredicateGroupAlloc();
            var group_transferred = false;
            errdefer if (!group_transferred) freeAccessPredicateGroup(self.alloc, group);
            if (parenthesized) try self.expect(.rparen);
            try access_or_predicates.append(self.alloc, group);
            group_transferred = true;
            if (!self.matchKeyword("or")) break;
        }
    }

    fn parseAccessNotWhere(
        self: *@This(),
        access_not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup),
    ) !void {
        try self.expectKeyword("not");
        try self.expect(.lparen);
        while (true) {
            const parenthesized = self.match(.lparen) != null;
            const group = try self.parseAccessPredicateGroupAlloc();
            var group_transferred = false;
            errdefer if (!group_transferred) freeAccessPredicateGroup(self.alloc, group);
            if (parenthesized) try self.expect(.rparen);
            try access_not_predicates.append(self.alloc, group);
            group_transferred = true;
            if (!self.matchKeyword("or")) break;
        }
        try self.expect(.rparen);
    }

    fn parenthesizedExpressionOrWhereCanStart(self: *@This()) bool {
        if (!self.peekKind(.lparen)) return false;
        const inner = self.predicateStartIndexAfterOpenParens(self.pos);
        if (!self.expressionCanStartAt(inner) and !self.jsonExtractExpressionPredicateCanStartAt(inner)) return false;

        var depth: usize = 0;
        var i = self.pos;
        while (i < self.tokens.len) : (i += 1) {
            const token = self.tokens[i];
            switch (token.kind) {
                .lparen => depth += 1,
                .rparen => {
                    if (depth == 0) return false;
                    depth -= 1;
                    if (depth == 0) return false;
                },
                .identifier => if (depth == 1 and std.ascii.eqlIgnoreCase(token.text, "or")) return true,
                .semicolon => return false,
                else => {},
            }
        }
        return false;
    }

    fn predicateStartIndexAfterOpenParens(self: *@This(), index: usize) usize {
        var out = index;
        while (out < self.tokens.len and self.tokens[out].kind == .lparen) : (out += 1) {}
        return out;
    }

    fn jsonExtractExpressionCanStartAt(self: *@This(), index: usize) bool {
        if (index + 2 >= self.tokens.len) return false;
        if (self.tokens[index].kind != .identifier) return false;
        if (self.tokens[index + 1].kind != .arrow_text and self.tokens[index + 1].kind != .arrow_json) return false;
        return self.tokens[index + 2].kind == .string;
    }

    fn jsonExtractExpressionPredicateCanStartAt(self: *@This(), index: usize) bool {
        if (index + 3 >= self.tokens.len) return false;
        if (!self.jsonExtractExpressionCanStartAt(index)) return false;
        return switch (self.tokens[index + 3].kind) {
            .eq, .neq => true,
            else => false,
        };
    }

    fn jsonExtractNullSafeDistinctPredicateCanStartAt(self: *@This(), index: usize) bool {
        if (index + 5 >= self.tokens.len) return false;
        if (!self.jsonExtractExpressionCanStartAt(index)) return false;
        if (self.tokens[index + 3].kind != .identifier or
            !std.ascii.eqlIgnoreCase(self.tokens[index + 3].text, "is"))
        {
            return false;
        }
        var distinct_index = index + 4;
        if (self.tokens[distinct_index].kind == .identifier and
            std.ascii.eqlIgnoreCase(self.tokens[distinct_index].text, "not"))
        {
            distinct_index += 1;
        }
        return distinct_index + 1 < self.tokens.len and
            self.tokens[distinct_index].kind == .identifier and
            std.ascii.eqlIgnoreCase(self.tokens[distinct_index].text, "distinct") and
            self.tokens[distinct_index + 1].kind == .identifier and
            std.ascii.eqlIgnoreCase(self.tokens[distinct_index + 1].text, "from");
    }

    fn expressionNullSafeDistinctPredicateCanStartAt(self: *@This(), index: usize) bool {
        if (!self.expressionCanStartAt(index)) return false;
        var depth: usize = 0;
        var i = index;
        while (i < self.tokens.len) : (i += 1) {
            const token = self.tokens[i];
            switch (token.kind) {
                .lparen => depth += 1,
                .rparen => {
                    if (depth == 0) return false;
                    depth -= 1;
                },
                .identifier => if (depth == 0 and std.ascii.eqlIgnoreCase(token.text, "is")) {
                    var distinct_index = i + 1;
                    if (distinct_index < self.tokens.len and
                        self.tokens[distinct_index].kind == .identifier and
                        std.ascii.eqlIgnoreCase(self.tokens[distinct_index].text, "not"))
                    {
                        distinct_index += 1;
                    }
                    return distinct_index + 1 < self.tokens.len and
                        self.tokens[distinct_index].kind == .identifier and
                        std.ascii.eqlIgnoreCase(self.tokens[distinct_index].text, "distinct") and
                        self.tokens[distinct_index + 1].kind == .identifier and
                        std.ascii.eqlIgnoreCase(self.tokens[distinct_index + 1].text, "from");
                } else if (depth == 0 and rowExpressionBoundaryKeyword(token.text)) {
                    return false;
                },
                .semicolon, .comma => if (depth == 0) return false,
                else => {},
            }
        }
        return false;
    }

    fn jsonExtractMembershipPredicateCanStartAt(self: *@This(), index: usize) bool {
        if (index + 3 >= self.tokens.len) return false;
        if (self.tokens[index].kind != .identifier) return false;
        if (self.tokens[index + 1].kind != .arrow_text and self.tokens[index + 1].kind != .arrow_json) return false;
        if (self.tokens[index + 2].kind != .string) return false;
        const op = self.tokens[index + 3];
        if (op.kind == .identifier and std.ascii.eqlIgnoreCase(op.text, "in")) return true;
        if (op.kind == .identifier and std.ascii.eqlIgnoreCase(op.text, "not")) {
            return index + 4 < self.tokens.len and
                self.tokens[index + 4].kind == .identifier and
                std.ascii.eqlIgnoreCase(self.tokens[index + 4].text, "in");
        }
        if (op.kind == .eq) {
            return index + 4 < self.tokens.len and
                self.tokens[index + 4].kind == .identifier and
                (sqlKeywordIsAnyOrSome(self.tokens[index + 4].text) or
                    std.ascii.eqlIgnoreCase(self.tokens[index + 4].text, "all"));
        }
        if (op.kind == .neq) {
            return index + 4 < self.tokens.len and
                self.tokens[index + 4].kind == .identifier and
                (sqlKeywordIsAnyOrSome(self.tokens[index + 4].text) or
                    std.ascii.eqlIgnoreCase(self.tokens[index + 4].text, "all"));
        }
        return false;
    }

    fn canParseExpressionNotWhere(self: *@This()) bool {
        if (!self.peekKeyword("not") or self.pos + 2 >= self.tokens.len or self.tokens[self.pos + 1].kind != .lparen) return false;
        const inner = self.predicateStartIndexAfterOpenParens(self.pos + 1);
        return self.expressionCanStartAt(inner) or self.jsonExtractExpressionPredicateCanStartAt(inner);
    }

    fn expressionCanStartAt(self: *@This(), index: usize) bool {
        if (index >= self.tokens.len) return false;
        const token = self.tokens[index];
        if (token.kind == .minus) return true;
        if (token.kind == .number or token.kind == .string or token.kind == .placeholder) return true;
        if (token.kind != .identifier) return false;
        if (std.ascii.eqlIgnoreCase(token.text, "array_length") or
            std.ascii.eqlIgnoreCase(token.text, "case") or
            std.ascii.eqlIgnoreCase(token.text, "cast") or
            std.ascii.eqlIgnoreCase(token.text, "coalesce") or
            std.ascii.eqlIgnoreCase(token.text, "current_timestamp") or
            std.ascii.eqlIgnoreCase(token.text, "false") or
            std.ascii.eqlIgnoreCase(token.text, "abs") or
            self.functionCallStartsAt(index, "floor") or
            self.functionCallStartsAt(index, "ceil") or
            std.ascii.eqlIgnoreCase(token.text, "length") or
            std.ascii.eqlIgnoreCase(token.text, "lower") or
            std.ascii.eqlIgnoreCase(token.text, "now") or
            std.ascii.eqlIgnoreCase(token.text, "null") or
            std.ascii.eqlIgnoreCase(token.text, "nullif") or
            std.ascii.eqlIgnoreCase(token.text, "round") or
            std.ascii.eqlIgnoreCase(token.text, "string_to_array") or
            std.ascii.eqlIgnoreCase(token.text, "trim") or
            std.ascii.eqlIgnoreCase(token.text, "replace") or
            std.ascii.eqlIgnoreCase(token.text, "true") or
            std.ascii.eqlIgnoreCase(token.text, "upper"))
        {
            return true;
        }
        if (self.jsonExtractMembershipPredicateCanStartAt(index) or self.jsonExtractNullSafeDistinctPredicateCanStartAt(index)) return true;
        return index + 1 < self.tokens.len and switch (self.tokens[index + 1].kind) {
            .plus, .minus, .star, .slash => true,
            else => false,
        };
    }

    fn parseExpressionNotWhere(
        self: *@This(),
        expression_not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    ) !void {
        try self.expectKeyword("not");
        try self.expect(.lparen);
        while (true) {
            var groups = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
            var groups_transferred = false;
            defer groups.deinit(self.alloc);
            errdefer {
                if (!groups_transferred) freeExpressionPredicateGroups(self.alloc, groups.items);
            }
            try groups.append(self.alloc, .{ .conditions = &.{} });

            while (true) {
                var alternatives = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
                defer alternatives.deinit(self.alloc);
                errdefer freeExpressionPredicateGroups(self.alloc, alternatives.items);
                try self.parseExpressionWhereConditionAlternatives(&alternatives);
                try self.andExpressionPredicateAlternatives(&groups, alternatives.items);
                freeExpressionPredicateGroups(self.alloc, alternatives.items);
                if (!self.matchKeyword("and")) break;
            }
            if (groups.items.len == 0) return error.UnsupportedSqlShape;
            try expression_not_predicates.appendSlice(self.alloc, groups.items);
            groups_transferred = true;

            if (!self.matchKeyword("or")) break;
        }
        try self.expect(.rparen);
    }

    fn parseExpressionOrWhere(
        self: *@This(),
        expression_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    ) !void {
        while (true) {
            const parenthesized = self.match(.lparen) != null;
            while (true) {
                var groups = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
                var groups_transferred = false;
                defer groups.deinit(self.alloc);
                errdefer {
                    if (!groups_transferred) freeExpressionPredicateGroups(self.alloc, groups.items);
                }
                try groups.append(self.alloc, .{ .conditions = &.{} });

                while (true) {
                    var alternatives = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
                    defer alternatives.deinit(self.alloc);
                    errdefer freeExpressionPredicateGroups(self.alloc, alternatives.items);
                    try self.parseExpressionWhereConditionAlternatives(&alternatives);
                    try self.andExpressionPredicateAlternatives(&groups, alternatives.items);
                    freeExpressionPredicateGroups(self.alloc, alternatives.items);
                    if (!self.matchKeyword("and")) break;
                }
                if (groups.items.len == 0) return error.UnsupportedSqlShape;
                try expression_or_predicates.appendSlice(self.alloc, groups.items);
                groups_transferred = true;

                if (!parenthesized or !self.matchKeyword("or")) break;
            }
            if (parenthesized) try self.expect(.rparen);

            if (!self.matchKeyword("or")) break;
        }
    }

    fn andExpressionPredicateAlternatives(
        self: *@This(),
        groups: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        alternatives: []const db_mod.types.RelationalRowsExpressionPredicateGroup,
    ) !void {
        if (groups.items.len == 0 or alternatives.len == 0) return error.UnsupportedSqlShape;
        var combined = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
        var combined_transferred = false;
        errdefer {
            if (!combined_transferred) freeExpressionPredicateGroups(self.alloc, combined.items);
            combined.deinit(self.alloc);
        }

        for (groups.items) |base| {
            for (alternatives) |alternative| {
                const conditions = try cloneExpressionConditionsConcatAlloc(self.alloc, base.conditions, alternative.conditions);
                var conditions_transferred = false;
                errdefer if (!conditions_transferred) {
                    freeExpressionConditions(self.alloc, conditions);
                    if (conditions.len > 0) self.alloc.free(conditions);
                };
                try combined.append(self.alloc, .{ .conditions = conditions });
                conditions_transferred = true;
            }
        }

        freeExpressionPredicateGroups(self.alloc, groups.items);
        groups.deinit(self.alloc);
        groups.* = combined;
        combined_transferred = true;
    }

    fn matchStandaloneSqlBooleanLiteral(self: *@This()) ?bool {
        const enabled = self.peekStandaloneSqlBooleanLiteral() orelse return null;
        self.pos += 1;
        return enabled;
    }

    fn peekStandaloneSqlBooleanLiteral(self: *@This()) ?bool {
        const token = if (self.pos < self.tokens.len) self.tokens[self.pos] else return null;
        if (token.kind != .identifier) return null;
        const enabled = if (std.ascii.eqlIgnoreCase(token.text, "true"))
            true
        else if (std.ascii.eqlIgnoreCase(token.text, "false"))
            false
        else
            return null;
        if (self.pos + 1 >= self.tokens.len) return enabled;
        const next = self.tokens[self.pos + 1];
        return switch (next.kind) {
            .semicolon, .rparen => enabled,
            .identifier => if (std.ascii.eqlIgnoreCase(next.text, "and") or
                std.ascii.eqlIgnoreCase(next.text, "or") or
                tokenStartsWhereTailClause(next.text))
                enabled
            else
                null,
            else => null,
        };
    }

    fn appendBooleanConstantExpressionCondition(
        self: *@This(),
        expression_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition),
        enabled: bool,
    ) !void {
        const condition = try self.booleanConstantExpressionConditionAlloc(enabled);
        var condition_transferred = false;
        errdefer if (!condition_transferred) freeExpressionCondition(self.alloc, condition);
        try expression_predicates.append(self.alloc, condition);
        condition_transferred = true;
    }

    fn appendBooleanConstantExpressionGroup(
        self: *@This(),
        expression_groups: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        enabled: bool,
    ) !void {
        if (enabled) {
            try expression_groups.append(self.alloc, .{ .conditions = &.{} });
            return;
        }
        const conditions = try self.alloc.alloc(db_mod.types.RelationalRowsExpressionCondition, 1);
        var conditions_transferred = false;
        errdefer if (!conditions_transferred) self.alloc.free(conditions);
        conditions[0] = try self.booleanConstantExpressionConditionAlloc(false);
        var condition_transferred = false;
        errdefer if (!condition_transferred) freeExpressionCondition(self.alloc, conditions[0]);
        try expression_groups.append(self.alloc, .{ .conditions = conditions });
        condition_transferred = true;
        conditions_transferred = true;
    }

    fn booleanConstantExpressionConditionAlloc(
        self: *@This(),
        enabled: bool,
    ) !db_mod.types.RelationalRowsExpressionCondition {
        const lhs_json = try self.alloc.dupe(u8, "true");
        var lhs_transferred = false;
        errdefer if (!lhs_transferred) self.alloc.free(lhs_json);
        const rhs_json = try self.alloc.dupe(u8, if (enabled) "true" else "false");
        var rhs_json_transferred = false;
        errdefer if (!rhs_json_transferred) self.alloc.free(rhs_json);
        const rhs = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
        var rhs_transferred = false;
        errdefer if (!rhs_transferred) self.alloc.free(rhs);
        rhs[0] = .{
            .kind = .value,
            .value_json = rhs_json,
        };
        lhs_transferred = true;
        rhs_json_transferred = true;
        rhs_transferred = true;
        return .{
            .lhs = .{
                .kind = .value,
                .value_json = lhs_json,
            },
            .op = .eq,
            .rhs = rhs,
        };
    }

    fn parseExpressionWhereConditionAlternatives(
        self: *@This(),
        alternatives: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    ) !void {
        if (self.matchStandaloneSqlBooleanLiteral()) |enabled| {
            try self.appendBooleanConstantExpressionGroup(alternatives, enabled);
            return;
        }

        const lhs = try self.parseRowExpressionAlloc();
        var lhs_transferred = false;
        errdefer if (!lhs_transferred) freeExpression(self.alloc, lhs);

        if (self.matchKeyword("not")) return error.UnsupportedSqlShape;

        if (self.matchKeyword("in")) {
            try self.appendExpressionInOrGroups(alternatives, lhs);
            freeExpression(self.alloc, lhs);
            lhs_transferred = true;
            return;
        }

        if (self.matchKeyword("between")) {
            const upper_lhs = try cloneExpressionAlloc(self.alloc, lhs);
            var upper_lhs_transferred = false;
            errdefer if (!upper_lhs_transferred) freeExpression(self.alloc, upper_lhs);

            const lower_expression = try self.parseRowExpressionAlloc();
            var lower_transferred = false;
            errdefer if (!lower_transferred) freeExpression(self.alloc, lower_expression);
            try self.expectKeyword("and");
            const upper_expression = try self.parseRowExpressionAlloc();
            var upper_transferred = false;
            errdefer if (!upper_transferred) freeExpression(self.alloc, upper_expression);

            const lower_rhs = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
            var lower_rhs_transferred = false;
            errdefer if (!lower_rhs_transferred) self.alloc.free(lower_rhs);
            lower_rhs[0] = lower_expression;

            const upper_rhs = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
            var upper_rhs_transferred = false;
            errdefer if (!upper_rhs_transferred) self.alloc.free(upper_rhs);
            upper_rhs[0] = upper_expression;

            const conditions = try self.alloc.alloc(db_mod.types.RelationalRowsExpressionCondition, 2);
            var conditions_transferred = false;
            errdefer if (!conditions_transferred) self.alloc.free(conditions);

            conditions[0] = .{
                .lhs = lhs,
                .op = .gte,
                .rhs = lower_rhs,
            };
            lhs_transferred = true;
            lower_transferred = true;
            lower_rhs_transferred = true;

            conditions[1] = .{
                .lhs = upper_lhs,
                .op = .lte,
                .rhs = upper_rhs,
            };
            upper_lhs_transferred = true;
            upper_transferred = true;
            upper_rhs_transferred = true;

            try alternatives.append(self.alloc, .{ .conditions = conditions });
            conditions_transferred = true;
            return;
        }

        const op: runtime_schema.RelationalCheckOp = if (self.matchKeyword("is")) blk: {
            const not = self.matchKeyword("not");
            if (self.matchKeyword("distinct")) {
                try self.expectKeyword("from");
                break :blk if (not) .is_not_distinct else .is_distinct;
            }
            try self.expectKeyword("null");
            break :blk if (not) .is_not_null else .is_null;
        } else try self.parseComparisonOp();

        if (op == .eq and self.matchAnyOrSomeKeyword()) {
            try self.expect(.lparen);
            const values_json = try self.parseJsonArrayValueAlloc();
            defer self.alloc.free(values_json);
            try self.expect(.rparen);
            try self.appendExpressionValuesJsonOrGroups(alternatives, lhs, values_json);
            freeExpression(self.alloc, lhs);
            lhs_transferred = true;
            return;
        }
        if (op == .ne and self.matchAnyOrSomeKeyword()) {
            try self.expect(.lparen);
            const values_json = try self.parseJsonArrayValueAlloc();
            defer self.alloc.free(values_json);
            try self.expect(.rparen);
            try self.appendExpressionValuesJsonComparisonGroups(alternatives, lhs, values_json, .ne);
            freeExpression(self.alloc, lhs);
            lhs_transferred = true;
            return;
        }
        if (op == .eq and self.matchKeyword("all")) {
            try self.expect(.lparen);
            const values_json = try self.parseJsonArrayValueAlloc();
            defer self.alloc.free(values_json);
            try self.expect(.rparen);
            try self.appendExpressionValuesJsonConjunctionGroup(alternatives, lhs, values_json, .eq);
            freeExpression(self.alloc, lhs);
            lhs_transferred = true;
            return;
        }
        if (op == .ne and self.matchKeyword("all")) {
            try self.expect(.lparen);
            const values_json = try self.parseJsonArrayValueAlloc();
            defer self.alloc.free(values_json);
            try self.expect(.rparen);
            try self.appendExpressionValuesJsonConjunctionGroup(alternatives, lhs, values_json, .ne);
            freeExpression(self.alloc, lhs);
            lhs_transferred = true;
            return;
        }

        const rhs = switch (op) {
            .is_null, .is_not_null => &.{},
            else => blk: {
                const out = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
                var out_transferred = false;
                errdefer if (!out_transferred) self.alloc.free(out);
                out[0] = try self.parseRowExpressionAlloc();
                out_transferred = true;
                break :blk out;
            },
        };
        var rhs_transferred = false;
        errdefer if (!rhs_transferred and rhs.len > 0) {
            for (rhs) |expression| freeExpression(self.alloc, expression);
            self.alloc.free(rhs);
        };
        try self.validateExpressionConditionTypes(lhs, op, rhs);

        const conditions = try self.alloc.alloc(db_mod.types.RelationalRowsExpressionCondition, 1);
        var conditions_transferred = false;
        errdefer if (!conditions_transferred) self.alloc.free(conditions);
        conditions[0] = .{
            .lhs = lhs,
            .op = op,
            .rhs = rhs,
        };
        lhs_transferred = true;
        rhs_transferred = true;
        try alternatives.append(self.alloc, .{ .conditions = conditions });
        conditions_transferred = true;
    }

    fn parseExpressionWhereConditions(
        self: *@This(),
        expression_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition),
        expression_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        expression_not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    ) !void {
        if (self.matchStandaloneSqlBooleanLiteral()) |enabled| {
            if (!enabled) try self.appendBooleanConstantExpressionCondition(expression_predicates, false);
            return;
        }

        const lhs = try self.parseRowExpressionAlloc();
        var lhs_transferred = false;
        errdefer if (!lhs_transferred) freeExpression(self.alloc, lhs);

        if (self.matchKeyword("in")) {
            try self.appendExpressionInOrGroups(expression_or_predicates, lhs);
            freeExpression(self.alloc, lhs);
            lhs_transferred = true;
            return;
        }

        if (self.matchKeyword("not")) {
            if (self.matchKeyword("in")) {
                try self.appendExpressionInPredicateGroups(expression_not_predicates, lhs);
                freeExpression(self.alloc, lhs);
                lhs_transferred = true;
                return;
            }
            try self.expectKeyword("between");
            const lower_expression = try self.parseRowExpressionAlloc();
            var lower_transferred = false;
            errdefer if (!lower_transferred) freeExpression(self.alloc, lower_expression);
            try self.expectKeyword("and");
            const upper_expression = try self.parseRowExpressionAlloc();
            var upper_transferred = false;
            errdefer if (!upper_transferred) freeExpression(self.alloc, upper_expression);

            const lower_lhs = try cloneExpressionAlloc(self.alloc, lhs);
            var lower_lhs_transferred = false;
            errdefer if (!lower_lhs_transferred) freeExpression(self.alloc, lower_lhs);
            const upper_lhs = try cloneExpressionAlloc(self.alloc, lhs);
            var upper_lhs_transferred = false;
            errdefer if (!upper_lhs_transferred) freeExpression(self.alloc, upper_lhs);

            const lower_rhs = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
            var lower_rhs_transferred = false;
            errdefer if (!lower_rhs_transferred) self.alloc.free(lower_rhs);
            lower_rhs[0] = lower_expression;

            const upper_rhs = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
            var upper_rhs_transferred = false;
            errdefer if (!upper_rhs_transferred) self.alloc.free(upper_rhs);
            upper_rhs[0] = upper_expression;

            const lower_conditions = try self.alloc.alloc(db_mod.types.RelationalRowsExpressionCondition, 1);
            var lower_conditions_transferred = false;
            errdefer if (!lower_conditions_transferred) self.alloc.free(lower_conditions);
            lower_conditions[0] = .{
                .lhs = lower_lhs,
                .op = .lt,
                .rhs = lower_rhs,
            };
            lower_lhs_transferred = true;
            lower_transferred = true;
            lower_rhs_transferred = true;

            const upper_conditions = try self.alloc.alloc(db_mod.types.RelationalRowsExpressionCondition, 1);
            var upper_conditions_transferred = false;
            errdefer if (!upper_conditions_transferred) self.alloc.free(upper_conditions);
            upper_conditions[0] = .{
                .lhs = upper_lhs,
                .op = .gt,
                .rhs = upper_rhs,
            };
            upper_lhs_transferred = true;
            upper_transferred = true;
            upper_rhs_transferred = true;

            try expression_or_predicates.append(self.alloc, .{ .conditions = lower_conditions });
            lower_conditions_transferred = true;
            try expression_or_predicates.append(self.alloc, .{ .conditions = upper_conditions });
            upper_conditions_transferred = true;
            freeExpression(self.alloc, lhs);
            lhs_transferred = true;
            return;
        }

        if (self.matchKeyword("between")) {
            const upper_lhs = try cloneExpressionAlloc(self.alloc, lhs);
            var upper_lhs_transferred = false;
            errdefer if (!upper_lhs_transferred) freeExpression(self.alloc, upper_lhs);

            const lower_expression = try self.parseRowExpressionAlloc();
            var lower_transferred = false;
            errdefer if (!lower_transferred) freeExpression(self.alloc, lower_expression);
            try self.expectKeyword("and");
            const upper_expression = try self.parseRowExpressionAlloc();
            var upper_transferred = false;
            errdefer if (!upper_transferred) freeExpression(self.alloc, upper_expression);

            const lower_rhs = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
            var lower_rhs_transferred = false;
            errdefer if (!lower_rhs_transferred) self.alloc.free(lower_rhs);
            lower_rhs[0] = lower_expression;

            const upper_rhs = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
            var upper_rhs_transferred = false;
            errdefer if (!upper_rhs_transferred) self.alloc.free(upper_rhs);
            upper_rhs[0] = upper_expression;

            try expression_predicates.append(self.alloc, .{
                .lhs = lhs,
                .op = .gte,
                .rhs = lower_rhs,
            });
            lhs_transferred = true;
            lower_transferred = true;
            lower_rhs_transferred = true;

            try expression_predicates.append(self.alloc, .{
                .lhs = upper_lhs,
                .op = .lte,
                .rhs = upper_rhs,
            });
            upper_lhs_transferred = true;
            upper_transferred = true;
            upper_rhs_transferred = true;
            return;
        }

        const op: runtime_schema.RelationalCheckOp = if (self.matchKeyword("is")) blk: {
            const not = self.matchKeyword("not");
            if (self.matchKeyword("distinct")) {
                try self.expectKeyword("from");
                break :blk if (not) .is_not_distinct else .is_distinct;
            }
            try self.expectKeyword("null");
            break :blk if (not) .is_not_null else .is_null;
        } else try self.parseComparisonOp();

        if (op == .eq and self.matchAnyOrSomeKeyword()) {
            try self.expect(.lparen);
            const values_json = try self.parseJsonArrayValueAlloc();
            defer self.alloc.free(values_json);
            try self.expect(.rparen);
            try self.appendExpressionValuesJsonOrGroups(expression_or_predicates, lhs, values_json);
            freeExpression(self.alloc, lhs);
            lhs_transferred = true;
            return;
        }
        if (op == .ne and self.matchAnyOrSomeKeyword()) {
            try self.expect(.lparen);
            const values_json = try self.parseJsonArrayValueAlloc();
            defer self.alloc.free(values_json);
            try self.expect(.rparen);
            try self.appendExpressionValuesJsonComparisonGroups(expression_or_predicates, lhs, values_json, .ne);
            freeExpression(self.alloc, lhs);
            lhs_transferred = true;
            return;
        }
        if (op == .eq and self.matchKeyword("all")) {
            try self.expect(.lparen);
            const values_json = try self.parseJsonArrayValueAlloc();
            defer self.alloc.free(values_json);
            try self.expect(.rparen);
            try self.appendExpressionValuesJsonConjunction(expression_predicates, lhs, values_json);
            freeExpression(self.alloc, lhs);
            lhs_transferred = true;
            return;
        }
        if (op == .ne and self.matchKeyword("all")) {
            try self.expect(.lparen);
            const values_json = try self.parseJsonArrayValueAlloc();
            defer self.alloc.free(values_json);
            try self.expect(.rparen);
            try self.appendExpressionValuesJsonOrGroups(expression_not_predicates, lhs, values_json);
            freeExpression(self.alloc, lhs);
            lhs_transferred = true;
            return;
        }

        const rhs = switch (op) {
            .is_null, .is_not_null => &.{},
            else => blk: {
                const out = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
                var out_transferred = false;
                errdefer if (!out_transferred) self.alloc.free(out);
                out[0] = try self.parseRowExpressionAlloc();
                out_transferred = true;
                break :blk out;
            },
        };
        var rhs_transferred = false;
        errdefer if (!rhs_transferred and rhs.len > 0) {
            for (rhs) |expression| freeExpression(self.alloc, expression);
            self.alloc.free(rhs);
        };
        try self.validateExpressionConditionTypes(lhs, op, rhs);

        try expression_predicates.append(self.alloc, .{
            .lhs = lhs,
            .op = op,
            .rhs = rhs,
        });
        lhs_transferred = true;
        rhs_transferred = true;
    }

    fn appendExpressionInOrGroups(
        self: *@This(),
        expression_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        lhs: db_mod.types.RelationalRowsExpression,
    ) !void {
        try self.appendExpressionInPredicateGroups(expression_or_predicates, lhs);
    }

    fn appendExpressionInPredicateGroups(
        self: *@This(),
        expression_groups: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        lhs: db_mod.types.RelationalRowsExpression,
    ) !void {
        const values_json = try self.parseSqlInValuesJsonAlloc();
        defer self.alloc.free(values_json);
        try self.appendExpressionValuesJsonOrGroups(expression_groups, lhs, values_json);
    }

    fn appendExpressionValuesJsonConjunction(
        self: *@This(),
        expression_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition),
        lhs: db_mod.types.RelationalRowsExpression,
        values_json: []const u8,
    ) !void {
        var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, values_json, .{}) catch return error.UnsupportedSqlShape;
        defer parsed.deinit();
        if (parsed.value != .array or parsed.value.array.items.len == 0 or parsed.value.array.items.len > max_scalar_or_expanded_branches) return error.UnsupportedSqlShape;
        try self.validateExpressionScalarMembershipValues(lhs, parsed.value);

        for (parsed.value.array.items) |value| {
            const lhs_clone = try cloneExpressionAlloc(self.alloc, lhs);
            var lhs_transferred = false;
            errdefer if (!lhs_transferred) freeExpression(self.alloc, lhs_clone);

            const value_json = try std.json.Stringify.valueAlloc(self.alloc, value, .{});
            var value_transferred = false;
            errdefer if (!value_transferred) self.alloc.free(value_json);

            const rhs = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
            var rhs_transferred = false;
            errdefer if (!rhs_transferred) self.alloc.free(rhs);
            rhs[0] = .{
                .kind = .value,
                .value_json = value_json,
            };
            value_transferred = true;

            try expression_predicates.append(self.alloc, .{
                .lhs = lhs_clone,
                .op = .eq,
                .rhs = rhs,
            });
            lhs_transferred = true;
            rhs_transferred = true;
        }
    }

    fn appendExpressionValuesJsonOrGroups(
        self: *@This(),
        expression_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        lhs: db_mod.types.RelationalRowsExpression,
        values_json: []const u8,
    ) !void {
        try self.appendExpressionValuesJsonComparisonGroups(expression_or_predicates, lhs, values_json, .eq);
    }

    fn appendExpressionValuesJsonConjunctionGroup(
        self: *@This(),
        expression_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        lhs: db_mod.types.RelationalRowsExpression,
        values_json: []const u8,
        op: runtime_schema.RelationalCheckOp,
    ) !void {
        var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, values_json, .{}) catch return error.UnsupportedSqlShape;
        defer parsed.deinit();
        if (parsed.value != .array or parsed.value.array.items.len == 0 or parsed.value.array.items.len > max_scalar_or_expanded_branches) return error.UnsupportedSqlShape;
        try self.validateExpressionScalarMembershipValues(lhs, parsed.value);

        const conditions = try self.alloc.alloc(db_mod.types.RelationalRowsExpressionCondition, parsed.value.array.items.len);
        var condition_count: usize = 0;
        errdefer {
            for (conditions[0..condition_count]) |condition| freeExpressionCondition(self.alloc, condition);
            self.alloc.free(conditions);
        }

        for (parsed.value.array.items) |value| {
            if (op == .ne and value == .null) return error.UnsupportedSqlShape;

            const lhs_clone = try cloneExpressionAlloc(self.alloc, lhs);
            var lhs_transferred = false;
            errdefer if (!lhs_transferred) freeExpression(self.alloc, lhs_clone);

            const value_json = try std.json.Stringify.valueAlloc(self.alloc, value, .{});
            var value_transferred = false;
            errdefer if (!value_transferred) self.alloc.free(value_json);

            const rhs = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
            var rhs_transferred = false;
            errdefer if (!rhs_transferred) self.alloc.free(rhs);
            rhs[0] = .{
                .kind = .value,
                .value_json = value_json,
            };
            value_transferred = true;

            conditions[condition_count] = .{
                .lhs = lhs_clone,
                .op = op,
                .rhs = rhs,
            };
            condition_count += 1;
            lhs_transferred = true;
            rhs_transferred = true;
        }

        try expression_or_predicates.append(self.alloc, .{ .conditions = conditions });
    }

    fn appendExpressionValuesJsonComparisonGroups(
        self: *@This(),
        expression_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        lhs: db_mod.types.RelationalRowsExpression,
        values_json: []const u8,
        op: runtime_schema.RelationalCheckOp,
    ) !void {
        var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, values_json, .{}) catch return error.UnsupportedSqlShape;
        defer parsed.deinit();
        if (parsed.value != .array or parsed.value.array.items.len == 0 or parsed.value.array.items.len > max_scalar_or_expanded_branches) return error.UnsupportedSqlShape;
        try self.validateExpressionScalarMembershipValues(lhs, parsed.value);

        for (parsed.value.array.items) |value| {
            const lhs_clone = try cloneExpressionAlloc(self.alloc, lhs);
            var lhs_transferred = false;
            errdefer if (!lhs_transferred) freeExpression(self.alloc, lhs_clone);

            const value_json = try std.json.Stringify.valueAlloc(self.alloc, value, .{});
            var value_transferred = false;
            errdefer if (!value_transferred) self.alloc.free(value_json);

            const rhs = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
            var rhs_transferred = false;
            errdefer if (!rhs_transferred) self.alloc.free(rhs);
            rhs[0] = .{
                .kind = .value,
                .value_json = value_json,
            };
            value_transferred = true;

            const condition: db_mod.types.RelationalRowsExpressionCondition = .{
                .lhs = lhs_clone,
                .op = op,
                .rhs = rhs,
            };
            var condition_transferred = false;
            errdefer if (!condition_transferred) freeExpressionCondition(self.alloc, condition);
            lhs_transferred = true;
            rhs_transferred = true;

            const conditions = try self.alloc.alloc(db_mod.types.RelationalRowsExpressionCondition, 1);
            var conditions_transferred = false;
            errdefer if (!conditions_transferred) self.alloc.free(conditions);
            conditions[0] = condition;
            condition_transferred = true;

            try expression_or_predicates.append(self.alloc, .{ .conditions = conditions });
            conditions_transferred = true;
        }
    }

    fn validateExpressionScalarMembershipValues(
        self: *@This(),
        lhs: db_mod.types.RelationalRowsExpression,
        values: std.json.Value,
    ) !void {
        if (values != .array) return error.UnsupportedSqlShape;
        const lhs_type = try self.rowExpressionOutputType(lhs);
        if (lhs_type == .array or lhs_type == .json or lhs_type == .embedding) return error.UnsupportedSqlShape;
        for (values.array.items) |value| {
            if (!sqlScalarValueMatches(lhs_type, value)) return error.UnsupportedSqlShape;
        }
    }

    fn validateExpressionConditionTypes(
        self: *@This(),
        lhs: db_mod.types.RelationalRowsExpression,
        op: runtime_schema.RelationalCheckOp,
        rhs: []const db_mod.types.RelationalRowsExpression,
    ) !void {
        switch (op) {
            .is_null, .is_not_null => {
                if (rhs.len != 0) return error.UnsupportedSqlShape;
                return;
            },
            .eq, .ne, .is_distinct, .is_not_distinct, .gt, .gte, .lt, .lte => {
                if (rhs.len != 1) return error.UnsupportedSqlShape;
            },
        }
        const lhs_type = try self.rowExpressionOutputType(lhs);
        const rhs_expression = rhs[0];
        if (try self.rowExpressionIsNullLiteral(rhs_expression)) return;
        const rhs_type = try self.rowExpressionOutputType(rhs_expression);
        if (!sqlExpressionTypesComparable(lhs_type, rhs_type)) return error.UnsupportedSqlShape;
        switch (op) {
            .gt, .gte, .lt, .lte => if (!sqlExpressionTypeIsOrderable(lhs_type) or !sqlExpressionTypeIsOrderable(rhs_type)) return error.UnsupportedSqlShape,
            else => {},
        }
    }

    fn rowExpressionIsNullLiteral(self: *@This(), expression: db_mod.types.RelationalRowsExpression) !bool {
        if (expression.kind != .value) return false;
        var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, expression.value_json, .{}) catch return error.UnsupportedSqlShape;
        defer parsed.deinit();
        return parsed.value == .null;
    }

    fn sqlExpressionTypesComparable(lhs: runtime_schema.AntflyType, rhs: runtime_schema.AntflyType) bool {
        if (sqlExpressionTypeIsTextLike(lhs) and sqlExpressionTypeIsTextLike(rhs)) return true;
        if ((lhs == .datetime and rhs == .numeric) or (lhs == .numeric and rhs == .datetime)) return true;
        return lhs == rhs;
    }

    fn sqlExpressionTypeIsTextLike(field_type: runtime_schema.AntflyType) bool {
        return switch (field_type) {
            .text, .keyword, .link, .html, .search_as_you_type, .blob, .geoshape => true,
            else => false,
        };
    }

    fn sqlExpressionTypeIsOrderable(field_type: runtime_schema.AntflyType) bool {
        return sqlExpressionTypeIsTextLike(field_type) or field_type == .numeric or field_type == .datetime or field_type == .boolean;
    }

    fn stringToArrayPredicateIsContainment(self: *@This()) bool {
        if (!self.peekKeyword("string_to_array")) return false;
        var depth: usize = 0;
        var index = self.pos;
        while (index < self.tokens.len) : (index += 1) {
            const kind = self.tokens[index].kind;
            switch (kind) {
                .lparen => depth += 1,
                .rparen => {
                    if (depth == 0) return false;
                    depth -= 1;
                    if (depth == 0) {
                        return index + 1 < self.tokens.len and self.tokens[index + 1].kind == .at_contains;
                    }
                },
                else => {},
            }
        }
        return false;
    }

    fn parseExpressionArrayContainsPredicateAlloc(self: *@This()) !db_mod.types.RelationalRowsExpressionArrayContainsPredicate {
        const expression = try self.parseStringToArrayRowExpressionAlloc();
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(self.alloc, expression);
        try self.expect(.at_contains);
        const value_json = if (self.peekKeyword("array"))
            try self.parseSqlArrayConstructorJsonAlloc()
        else
            try self.parseJsonDocumentValueAlloc();
        var value_transferred = false;
        errdefer if (!value_transferred) self.alloc.free(value_json);
        try validateJsonStringArray(self.alloc, value_json);

        expression_transferred = true;
        value_transferred = true;
        return .{
            .expression = expression,
            .value_json = value_json,
        };
    }

    fn generatedExpressionCallHasGeneratedColumn(self: *@This()) !bool {
        if (self.peekKeyword("concat")) return (try self.generatedConcatColumnAtCurrent()) != null;
        const op: runtime_schema.RelationalGeneratedOp = if (self.peekKeyword("lower")) .lower else if (self.peekKeyword("upper")) .upper else return false;
        if (self.pos + 3 >= self.tokens.len) return false;
        if (self.tokens[self.pos + 1].kind != .lparen) return false;
        const field = self.tokens[self.pos + 2];
        if (field.kind != .identifier) return false;
        if (self.tokens[self.pos + 3].kind != .rparen) return false;
        const normalized_field = try self.normalizeRowExpressionFieldAlloc(field.text);
        defer self.alloc.free(normalized_field);
        return generatedCaseFoldColumnForField(self.schema, op, normalized_field) != null;
    }

    fn canParseScalarNotWhere(self: *@This()) bool {
        if (!self.peekKeyword("not") or self.pos + 1 >= self.tokens.len or self.tokens[self.pos + 1].kind != .lparen) return false;
        var i = self.pos + 2;
        var depth: usize = 1;
        while (i < self.tokens.len) : (i += 1) {
            const token = self.tokens[i];
            switch (token.kind) {
                .lparen => return false,
                .rparen => {
                    depth -= 1;
                    if (depth == 0) return true;
                },
                .arrow_text, .arrow_json, .at_contains, .question => return false,
                .identifier => {
                    if (std.ascii.eqlIgnoreCase(token.text, "any") or
                        std.ascii.eqlIgnoreCase(token.text, "some") or
                        std.ascii.eqlIgnoreCase(token.text, "between") or
                        std.ascii.eqlIgnoreCase(token.text, "in") or
                        std.ascii.eqlIgnoreCase(token.text, "exists"))
                    {
                        return false;
                    }
                    if (std.ascii.eqlIgnoreCase(token.text, "not")) {
                        if (i == 0 or self.tokens[i - 1].kind != .identifier or
                            !std.ascii.eqlIgnoreCase(self.tokens[i - 1].text, "is"))
                        {
                            return false;
                        }
                    }
                },
                else => {},
            }
        }
        return false;
    }

    fn parseScalarNotWhere(
        self: *@This(),
        not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
    ) !void {
        try self.expectKeyword("not");
        try self.expect(.lparen);
        while (true) {
            var branch = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
            errdefer {
                freeRelationalChecks(self.alloc, branch.items);
                branch.deinit(self.alloc);
            }
            while (true) {
                const predicate = try self.parseScalarWherePredicateAlloc();
                var predicate_transferred = false;
                errdefer if (!predicate_transferred) freeRelationalCheck(self.alloc, predicate);
                try branch.append(self.alloc, predicate);
                predicate_transferred = true;
                if (!self.matchKeyword("and")) break;
            }
            if (branch.items.len == 0) return error.UnsupportedSqlShape;

            const predicates = try branch.toOwnedSlice(self.alloc);
            branch = .empty;
            var predicates_transferred = false;
            errdefer if (!predicates_transferred) {
                freeRelationalChecks(self.alloc, predicates);
                if (predicates.len > 0) self.alloc.free(predicates);
            };
            try not_predicates.append(self.alloc, .{ .predicates = predicates });
            predicates_transferred = true;
            branch.deinit(self.alloc);

            if (!self.matchKeyword("or")) break;
        }
        try self.expect(.rparen);
    }

    fn parseScalarOrWhere(
        self: *@This(),
        or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
    ) !void {
        while (true) {
            const parenthesized = self.match(.lparen) != null;
            var branches = std.ArrayListUnmanaged(ScalarOrCheckBranch).empty;
            errdefer self.freeScalarOrCheckBranches(&branches);
            try branches.append(self.alloc, .empty);

            while (true) {
                if (try self.parseScalarBooleanIsNotIntoOrBranches(&branches)) {
                    // Expanded as native OR branches.
                } else if (!(try self.parseScalarWhereSetIntoOrBranches(&branches))) {
                    const predicate = try self.parseScalarWherePredicateAlloc();
                    defer freeRelationalCheck(self.alloc, predicate);
                    try self.appendRelationalCheckCloneToScalarOrBranches(&branches, predicate);
                }
                if (!self.matchKeyword("and")) break;
            }

            if (branches.items.len == 0) return error.UnsupportedSqlShape;
            if (parenthesized) try self.expect(.rparen);
            for (branches.items) |*branch| {
                if (branch.items.len == 0) return error.UnsupportedSqlShape;
                const predicates = try branch.toOwnedSlice(self.alloc);
                branch.* = .empty;
                var predicates_transferred = false;
                errdefer if (!predicates_transferred) {
                    freeRelationalChecks(self.alloc, predicates);
                    if (predicates.len > 0) self.alloc.free(predicates);
                };
                try or_predicates.append(self.alloc, .{ .predicates = predicates });
                predicates_transferred = true;
            }
            branches.deinit(self.alloc);

            if (!self.matchKeyword("or")) break;
        }
    }

    fn parseScalarBooleanIsNotIntoOrBranches(
        self: *@This(),
        branches: *std.ArrayListUnmanaged(ScalarOrCheckBranch),
    ) !bool {
        const saved_pos = self.pos;
        const parsed_field = self.parseFieldExpressionOwned() catch |err| {
            self.pos = saved_pos;
            return switch (err) {
                error.UnsupportedSqlShape => false,
                else => err,
            };
        };
        defer self.alloc.free(parsed_field);
        if (!self.matchKeyword("is")) {
            self.pos = saved_pos;
            return false;
        }
        if (!self.matchKeyword("not")) {
            self.pos = saved_pos;
            return false;
        }
        if (!(self.peekKeyword("true") or self.peekKeyword("false"))) {
            self.pos = saved_pos;
            return false;
        }

        const field = try self.normalizeRowExpressionFieldAlloc(parsed_field);
        defer self.alloc.free(field);
        const column = relationalColumnForField(self.schema, field, .boolean) orelse return error.InvalidSqlCatalog;
        const value = (try self.parseSqlBooleanIsValue(column)) orelse return error.UnsupportedSqlShape;
        try self.expandBooleanIsNotIntoOrBranches(branches, field, value);
        return true;
    }

    fn parseScalarWhereSetIntoOrBranches(
        self: *@This(),
        branches: *std.ArrayListUnmanaged(ScalarOrCheckBranch),
    ) !bool {
        if (!self.peekSimpleScalarSetPredicate()) return false;

        const field = try self.parseFieldExpressionOwned();
        defer self.alloc.free(field);
        const column = relationalColumnForField(self.schema, field, null) orelse return error.InvalidSqlCatalog;
        if (column.field_type == .array or column.field_type == .json) return error.UnsupportedSqlShape;

        if (self.matchKeyword("not")) {
            try self.expectKeyword("in");
            const values_json = try self.parseSqlInValuesJsonAlloc();
            defer self.alloc.free(values_json);
            try self.appendScalarValuesJsonToOrBranches(branches, field, values_json, .ne);
            return true;
        }
        if (self.matchKeyword("in")) {
            const values_json = try self.parseSqlInValuesJsonAlloc();
            defer self.alloc.free(values_json);
            try self.expandScalarValuesJsonIntoOrBranches(branches, field, values_json, .eq);
            return true;
        }

        const op = try self.parseComparisonOp();
        if (op == .eq and self.matchAnyOrSomeKeyword()) {
            try self.expect(.lparen);
            const values_json = try self.parseJsonArrayValueAlloc();
            defer self.alloc.free(values_json);
            try self.expect(.rparen);
            try self.expandScalarValuesJsonIntoOrBranches(branches, field, values_json, .eq);
            return true;
        }
        if (op == .ne and self.matchAnyOrSomeKeyword()) {
            try self.expect(.lparen);
            const values_json = try self.parseJsonArrayValueAlloc();
            defer self.alloc.free(values_json);
            try self.expect(.rparen);
            try self.expandScalarValuesJsonIntoOrBranches(branches, field, values_json, .ne);
            return true;
        }
        if (op == .eq and self.matchKeyword("all")) {
            try self.expect(.lparen);
            const values_json = try self.parseJsonArrayValueAlloc();
            defer self.alloc.free(values_json);
            try self.expect(.rparen);
            try self.appendScalarValuesJsonToOrBranches(branches, field, values_json, .eq);
            return true;
        }
        if (op == .ne and self.matchKeyword("all")) {
            try self.expect(.lparen);
            const values_json = try self.parseJsonArrayValueAlloc();
            defer self.alloc.free(values_json);
            try self.expect(.rparen);
            try self.appendScalarValuesJsonToOrBranches(branches, field, values_json, .ne);
            return true;
        }
        return error.UnsupportedSqlShape;
    }

    fn expandScalarValuesJsonIntoOrBranches(
        self: *@This(),
        branches: *std.ArrayListUnmanaged(ScalarOrCheckBranch),
        field: []const u8,
        values_json: []const u8,
        op: runtime_schema.RelationalCheckOp,
    ) !void {
        var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, values_json, .{}) catch return error.UnsupportedSqlShape;
        defer parsed.deinit();
        if (parsed.value != .array or parsed.value.array.items.len == 0) return error.UnsupportedSqlShape;
        if (branches.items.len == 0 or branches.items.len > max_scalar_or_expanded_branches / parsed.value.array.items.len) return error.UnsupportedSqlShape;

        var expanded = std.ArrayListUnmanaged(ScalarOrCheckBranch).empty;
        errdefer self.freeScalarOrCheckBranches(&expanded);
        for (branches.items) |*source_branch| {
            for (parsed.value.array.items) |value| {
                if (op == .ne and value == .null) return error.UnsupportedSqlShape;
                var expanded_branch = ScalarOrCheckBranch.empty;
                var expanded_branch_transferred = false;
                errdefer if (!expanded_branch_transferred) {
                    freeRelationalChecks(self.alloc, expanded_branch.items);
                    expanded_branch.deinit(self.alloc);
                };

                try self.cloneScalarOrBranchInto(&expanded_branch, source_branch.*);
                try self.appendScalarJsonValueCheckToBranch(&expanded_branch, field, value, op);

                try expanded.append(self.alloc, expanded_branch);
                expanded_branch_transferred = true;
            }
        }

        self.freeScalarOrCheckBranches(branches);
        branches.* = expanded;
    }

    fn appendScalarValuesJsonToOrBranches(
        self: *@This(),
        branches: *std.ArrayListUnmanaged(ScalarOrCheckBranch),
        field: []const u8,
        values_json: []const u8,
        op: runtime_schema.RelationalCheckOp,
    ) !void {
        var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, values_json, .{}) catch return error.UnsupportedSqlShape;
        defer parsed.deinit();
        if (parsed.value != .array or parsed.value.array.items.len == 0 or parsed.value.array.items.len > max_scalar_or_expanded_branches) return error.UnsupportedSqlShape;
        if (branches.items.len == 0) return error.UnsupportedSqlShape;

        for (branches.items) |*branch| {
            for (parsed.value.array.items) |value| {
                if (op == .ne and value == .null) return error.UnsupportedSqlShape;
                try self.appendScalarJsonValueCheckToBranch(branch, field, value, op);
            }
        }
    }

    fn appendScalarJsonValueCheckToBranch(
        self: *@This(),
        branch: *ScalarOrCheckBranch,
        field: []const u8,
        value: std.json.Value,
        op: runtime_schema.RelationalCheckOp,
    ) !void {
        const value_json = try std.json.Stringify.valueAlloc(self.alloc, value, .{});
        var value_transferred = false;
        errdefer if (!value_transferred) self.alloc.free(value_json);
        const owned_field = try self.alloc.dupe(u8, field);
        var field_transferred = false;
        errdefer if (!field_transferred) self.alloc.free(owned_field);
        try branch.append(self.alloc, .{
            .name = "",
            .field = owned_field,
            .op = op,
            .value_json = value_json,
        });
        value_transferred = true;
        field_transferred = true;
    }

    fn initRelationalBooleanCheck(
        self: *@This(),
        out: *runtime_schema.RelationalCheck,
        field: []const u8,
        op: runtime_schema.RelationalCheckOp,
        value: bool,
    ) !void {
        const owned_field = try self.alloc.dupe(u8, field);
        var field_transferred = false;
        errdefer if (!field_transferred) self.alloc.free(owned_field);
        const value_json = try self.alloc.dupe(u8, booleanJson(value));
        var value_transferred = false;
        errdefer if (!value_transferred) self.alloc.free(value_json);
        out.* = .{
            .name = "",
            .field = owned_field,
            .op = op,
            .value_json = value_json,
        };
        field_transferred = true;
        value_transferred = true;
    }

    fn initRelationalNullCheck(
        self: *@This(),
        out: *runtime_schema.RelationalCheck,
        field: []const u8,
        op: runtime_schema.RelationalCheckOp,
    ) !void {
        const owned_field = try self.alloc.dupe(u8, field);
        var field_transferred = false;
        errdefer if (!field_transferred) self.alloc.free(owned_field);
        out.* = .{
            .name = "",
            .field = owned_field,
            .op = op,
            .value_json = null,
        };
        field_transferred = true;
    }

    fn appendScalarBooleanCheckToBranch(
        self: *@This(),
        branch: *ScalarOrCheckBranch,
        field: []const u8,
        op: runtime_schema.RelationalCheckOp,
        value: bool,
    ) !void {
        var check: runtime_schema.RelationalCheck = undefined;
        try self.initRelationalBooleanCheck(&check, field, op, value);
        var check_transferred = false;
        errdefer if (!check_transferred) freeRelationalCheck(self.alloc, check);
        try branch.append(self.alloc, check);
        check_transferred = true;
    }

    fn appendScalarNullCheckToBranch(
        self: *@This(),
        branch: *ScalarOrCheckBranch,
        field: []const u8,
        op: runtime_schema.RelationalCheckOp,
    ) !void {
        var check: runtime_schema.RelationalCheck = undefined;
        try self.initRelationalNullCheck(&check, field, op);
        var check_transferred = false;
        errdefer if (!check_transferred) freeRelationalCheck(self.alloc, check);
        try branch.append(self.alloc, check);
        check_transferred = true;
    }

    fn peekConflictExistingFieldIncrement(
        self: *@This(),
        field: []const u8,
        column: runtime_schema.RelationalColumn,
    ) bool {
        if (column.field_type != .numeric) return false;
        if (!self.peekKind(.identifier) or self.pos + 1 >= self.tokens.len) return false;
        const source = self.tokens[self.pos].text;
        if (!std.mem.eql(u8, source, field)) return false;
        const op = self.tokens[self.pos + 1].kind;
        if (op != .plus and op != .minus) return false;
        return !self.peekArithmeticRhsKeyword("interval");
    }

    fn peekSimpleScalarSetPredicate(self: *@This()) bool {
        if (self.pos + 1 >= self.tokens.len or self.tokens[self.pos].kind != .identifier) return false;
        if (self.pos + 2 < self.tokens.len and
            self.tokens[self.pos + 1].kind == .identifier and
            std.ascii.eqlIgnoreCase(self.tokens[self.pos + 1].text, "not") and
            self.tokens[self.pos + 2].kind == .identifier and
            std.ascii.eqlIgnoreCase(self.tokens[self.pos + 2].text, "in"))
        {
            return true;
        }
        if (self.tokens[self.pos + 1].kind == .identifier and std.ascii.eqlIgnoreCase(self.tokens[self.pos + 1].text, "in")) return true;
        if (self.pos + 2 >= self.tokens.len) return false;
        if (self.tokens[self.pos + 1].kind != .eq and self.tokens[self.pos + 1].kind != .neq) return false;
        return self.tokens[self.pos + 2].kind == .identifier and
            (sqlKeywordIsAnyOrSome(self.tokens[self.pos + 2].text) or
                std.ascii.eqlIgnoreCase(self.tokens[self.pos + 2].text, "all"));
    }

    fn appendRelationalCheckCloneToScalarOrBranches(
        self: *@This(),
        branches: *std.ArrayListUnmanaged(ScalarOrCheckBranch),
        predicate: runtime_schema.RelationalCheck,
    ) !void {
        if (branches.items.len == 0) return error.UnsupportedSqlShape;
        for (branches.items) |*branch| {
            try self.appendRelationalCheckClone(branch, predicate);
        }
    }

    fn cloneScalarOrBranchInto(
        self: *@This(),
        dest: *ScalarOrCheckBranch,
        source: ScalarOrCheckBranch,
    ) !void {
        for (source.items) |predicate| {
            try self.appendRelationalCheckClone(dest, predicate);
        }
    }

    fn appendRelationalCheckClone(
        self: *@This(),
        branch: *ScalarOrCheckBranch,
        predicate: runtime_schema.RelationalCheck,
    ) !void {
        const cloned = try cloneQueryRelationalCheckAlloc(self.alloc, predicate);
        var cloned_transferred = false;
        errdefer if (!cloned_transferred) freeRelationalCheck(self.alloc, cloned);
        try branch.append(self.alloc, cloned);
        cloned_transferred = true;
    }

    fn freeScalarOrCheckBranches(
        self: *@This(),
        branches: *std.ArrayListUnmanaged(ScalarOrCheckBranch),
    ) void {
        for (branches.items) |*branch| {
            freeRelationalChecks(self.alloc, branch.items);
            branch.deinit(self.alloc);
        }
        branches.deinit(self.alloc);
    }

    fn parseSqlBooleanIsValueAlloc(
        self: *@This(),
        column: runtime_schema.RelationalColumn,
        not: bool,
    ) !?[]const u8 {
        if (!(self.peekKeyword("true") or self.peekKeyword("false"))) return null;
        if (not) return error.UnsupportedSqlShape;
        if (column.field_type != .boolean) return error.InvalidSqlCatalog;
        if (self.matchKeyword("true")) return try self.alloc.dupe(u8, "true");
        try self.expectKeyword("false");
        return try self.alloc.dupe(u8, "false");
    }

    fn parseSqlBooleanIsValue(self: *@This(), column: runtime_schema.RelationalColumn) !?bool {
        if (!(self.peekKeyword("true") or self.peekKeyword("false"))) return null;
        if (column.field_type != .boolean) return error.InvalidSqlCatalog;
        if (self.matchKeyword("true")) return true;
        try self.expectKeyword("false");
        return false;
    }

    fn parseSqlBooleanIsUnknown(self: *@This(), column: runtime_schema.RelationalColumn) !bool {
        if (!self.matchKeyword("unknown")) return false;
        if (column.field_type != .boolean) return error.InvalidSqlCatalog;
        return true;
    }

    fn booleanJson(value: bool) []const u8 {
        return if (value) "true" else "false";
    }

    fn parseScalarWherePredicateAlloc(self: *@This()) !runtime_schema.RelationalCheck {
        const parsed_field = try self.parseFieldExpressionOwned();
        defer self.alloc.free(parsed_field);
        const field = try self.normalizeRowExpressionFieldAlloc(parsed_field);
        var field_transferred = false;
        errdefer if (!field_transferred) self.alloc.free(field);
        if (self.peekKind(.arrow_text) or self.peekKind(.arrow_json) or self.peekKind(.at_contains) or self.peekKind(.question)) return error.UnsupportedSqlShape;
        const column = relationalColumnForField(self.schema, field, null) orelse return error.InvalidSqlCatalog;
        if (column.field_type == .array or column.field_type == .json) return error.UnsupportedSqlShape;

        if (self.matchKeyword("is")) {
            const not = self.matchKeyword("not");
            if (self.matchKeyword("distinct")) {
                try self.expectKeyword("from");
                const value_json = try self.parseSqlColumnValueAlloc(column);
                var value_transferred = false;
                errdefer if (!value_transferred) self.alloc.free(value_json);
                field_transferred = true;
                value_transferred = true;
                return .{
                    .name = "",
                    .field = field,
                    .op = if (not) .is_not_distinct else .is_distinct,
                    .value_json = value_json,
                };
            }
            if (try self.parseSqlBooleanIsUnknown(column)) {
                field_transferred = true;
                return .{
                    .name = "",
                    .field = field,
                    .op = if (not) .is_not_null else .is_null,
                    .value_json = null,
                };
            }
            if (try self.parseSqlBooleanIsValueAlloc(column, not)) |value_json| {
                var value_transferred = false;
                errdefer if (!value_transferred) self.alloc.free(value_json);
                field_transferred = true;
                value_transferred = true;
                return .{
                    .name = "",
                    .field = field,
                    .op = .eq,
                    .value_json = value_json,
                };
            }
            const op: runtime_schema.RelationalCheckOp = if (not) blk: {
                try self.expectKeyword("null");
                break :blk .is_not_null;
            } else blk: {
                try self.expectKeyword("null");
                break :blk .is_null;
            };
            field_transferred = true;
            return .{
                .name = "",
                .field = field,
                .op = op,
                .value_json = null,
            };
        }

        if (self.peekKeyword("in") or self.peekKeyword("not")) return error.UnsupportedSqlShape;
        if (self.peekKeyword("between")) return error.UnsupportedSqlShape;
        const op = try self.parseComparisonOp();
        if (self.peekKind(.identifier) and sqlKeywordIsAnyOrSome(self.tokens[self.pos].text)) return error.UnsupportedSqlShape;
        const value_json = try self.parseSqlColumnValueAlloc(column);
        var value_transferred = false;
        errdefer if (!value_transferred) self.alloc.free(value_json);
        field_transferred = true;
        value_transferred = true;
        return .{
            .name = "",
            .field = field,
            .op = op,
            .value_json = value_json,
        };
    }

    fn parseWhereAtom(
        self: *@This(),
        predicates: *std.ArrayListUnmanaged(runtime_schema.RelationalCheck),
        json_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate),
        json_path_eq: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathEqPredicate),
        json_path_exists: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate),
        array_any: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayAnyPredicate),
        array_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate),
        array_eq: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate),
        in_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate),
        text_patterns: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate),
        or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
        negated: bool,
    ) !void {
        if (!negated and self.matchKeyword("not")) {
            try self.expect(.lparen);
            try self.parseWhereAtom(predicates, json_contains, json_path_eq, json_path_exists, array_any, array_contains, array_eq, in_predicates, text_patterns, or_predicates, true);
            try self.expect(.rparen);
            return;
        }
        if (!negated and self.valueEqualsAnyArrayPredicateCanStart()) {
            const value_json = try self.parseJsonValueAlloc();
            var value_transferred = false;
            errdefer if (!value_transferred) self.alloc.free(value_json);
            try self.expect(.eq);
            if (!self.matchAnyOrSomeKeyword()) return error.UnsupportedSqlShape;
            try self.expect(.lparen);
            const parsed_field = try self.parseFieldExpressionOwned();
            defer self.alloc.free(parsed_field);
            const field = try self.normalizeRowExpressionFieldAlloc(parsed_field);
            var field_transferred = false;
            errdefer if (!field_transferred) self.alloc.free(field);
            const column = relationalColumnForField(self.schema, field, .array) orelse return error.InvalidSqlCatalog;
            try self.validateSqlArrayElementValueJson(column, value_json);
            try self.expect(.rparen);
            try array_any.append(self.alloc, .{
                .field = field,
                .value_json = value_json,
            });
            field_transferred = true;
            value_transferred = true;
            return;
        }
        const parsed_field = try self.parseFieldExpressionOwned();
        defer self.alloc.free(parsed_field);
        const field = try self.normalizeRowExpressionFieldAlloc(parsed_field);
        var field_transferred = false;
        defer if (!field_transferred) self.alloc.free(field);
        const maybe_column = relationalColumnForField(self.schema, field, null);

        if (self.peekKind(.arrow_text) or self.peekKind(.arrow_json)) {
            const as_text = self.match(.arrow_text) != null;
            if (!as_text) try self.expect(.arrow_json);
            const path = try self.parseJsonPathOwned();
            var path_transferred = false;
            errdefer if (!path_transferred) self.alloc.free(path);
            try self.expect(.eq);
            const value_json = if (as_text)
                try self.parseJsonValueAlloc()
            else
                try self.parseJsonDocumentValueAlloc();
            var value_transferred = false;
            errdefer if (!value_transferred) self.alloc.free(value_json);
            if (relationalColumnForField(self.schema, field, .json) == null) return error.InvalidSqlCatalog;
            const predicate_field = try self.alloc.dupe(u8, field);
            var predicate_field_transferred = false;
            errdefer if (!predicate_field_transferred) self.alloc.free(predicate_field);
            try json_path_eq.append(self.alloc, .{
                .field = predicate_field,
                .path = path,
                .value_json = value_json,
            });
            predicate_field_transferred = true;
            path_transferred = true;
            value_transferred = true;
            return;
        }
        if (self.match(.at_contains) != null) {
            const column = maybe_column orelse return error.InvalidSqlCatalog;
            const value_json = try self.parseStructuredPredicateValueAlloc(column);
            var value_transferred = false;
            errdefer if (!value_transferred) self.alloc.free(value_json);
            if (column.field_type == .array) {
                try self.validateSqlArrayValueJson(column, value_json);
                try array_contains.append(self.alloc, .{
                    .field = field,
                    .value_json = value_json,
                });
                field_transferred = true;
                value_transferred = true;
                return;
            }
            if (column.field_type != .json) return error.InvalidSqlCatalog;
            try json_contains.append(self.alloc, .{
                .field = field,
                .value_json = value_json,
            });
            field_transferred = true;
            value_transferred = true;
            return;
        }
        if (self.match(.question) != null) {
            if (relationalColumnForField(self.schema, field, .json) == null) return error.InvalidSqlCatalog;
            const path = try self.parseJsonExistencePathOwned();
            var path_transferred = false;
            errdefer if (!path_transferred) self.alloc.free(path);
            try json_path_exists.append(self.alloc, .{
                .field = field,
                .path = path,
            });
            field_transferred = true;
            path_transferred = true;
            return;
        }
        const column = maybe_column orelse return error.InvalidSqlCatalog;
        if (self.matchKeyword("is")) {
            const not = self.matchKeyword("not");
            if (self.matchKeyword("distinct")) {
                try self.expectKeyword("from");
                const value_json = try self.parseSqlColumnValueAlloc(column);
                var value_transferred = false;
                errdefer if (!value_transferred) self.alloc.free(value_json);
                try predicates.append(self.alloc, .{
                    .name = "",
                    .field = field,
                    .op = if (not) .is_not_distinct else .is_distinct,
                    .value_json = value_json,
                });
                value_transferred = true;
                field_transferred = true;
                return;
            }
            if (try self.parseSqlBooleanIsUnknown(column)) {
                try predicates.append(self.alloc, .{
                    .name = "",
                    .field = field,
                    .op = if (not) .is_not_null else .is_null,
                    .value_json = null,
                });
                field_transferred = true;
                return;
            }
            if (try self.parseSqlBooleanIsValue(column)) |value| {
                if (not) {
                    try self.appendBooleanIsNotPredicateGroups(or_predicates, field, value);
                    return;
                }
                const value_json = try self.alloc.dupe(u8, booleanJson(value));
                var value_transferred = false;
                errdefer if (!value_transferred) self.alloc.free(value_json);
                try predicates.append(self.alloc, .{
                    .name = "",
                    .field = field,
                    .op = .eq,
                    .value_json = value_json,
                });
                value_transferred = true;
                field_transferred = true;
                return;
            }
            const op: runtime_schema.RelationalCheckOp = if (not) blk: {
                try self.expectKeyword("null");
                break :blk .is_not_null;
            } else blk: {
                try self.expectKeyword("null");
                break :blk .is_null;
            };
            try predicates.append(self.alloc, .{
                .name = "",
                .field = field,
                .op = op,
                .value_json = null,
            });
            field_transferred = true;
            return;
        }
        if (self.matchKeyword("like") or self.matchKeyword("ilike")) {
            const case_insensitive = std.ascii.eqlIgnoreCase(self.tokens[self.pos - 1].text, "ilike");
            try self.appendTextPatternPredicate(text_patterns, field, column, case_insensitive, negated);
            return;
        }
        if (self.matchKeyword("between")) {
            try self.appendBetweenPredicate(predicates, or_predicates, field, column, negated);
            return;
        }
        if (self.matchKeyword("not")) {
            if (self.matchKeyword("between")) {
                try self.appendBetweenPredicate(predicates, or_predicates, field, column, true);
                return;
            }
            if (self.matchKeyword("like") or self.matchKeyword("ilike")) {
                const case_insensitive = std.ascii.eqlIgnoreCase(self.tokens[self.pos - 1].text, "ilike");
                try self.appendTextPatternPredicate(text_patterns, field, column, case_insensitive, true);
                return;
            }
            try self.expectKeyword("in");
            if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
            const values_json = try self.parseSqlInValuesJsonAlloc();
            var values_transferred = false;
            errdefer if (!values_transferred) self.alloc.free(values_json);
            try self.validateSqlScalarValuesJson(column, values_json);
            try in_predicates.append(self.alloc, .{
                .field = field,
                .values_json = values_json,
                .negated = true,
            });
            field_transferred = true;
            values_transferred = true;
            return;
        }
        if (self.matchKeyword("in")) {
            if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
            const values_json = try self.parseSqlInValuesJsonAlloc();
            var values_transferred = false;
            errdefer if (!values_transferred) self.alloc.free(values_json);
            try self.validateSqlScalarValuesJson(column, values_json);
            try in_predicates.append(self.alloc, .{
                .field = field,
                .values_json = values_json,
                .negated = false,
            });
            field_transferred = true;
            values_transferred = true;
            return;
        }

        const op = try self.parseComparisonOp();
        if (op == .eq and self.matchAnyOrSomeKeyword()) {
            if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
            try self.expect(.lparen);
            const values_json = try self.parseJsonArrayValueAlloc();
            var values_transferred = false;
            errdefer if (!values_transferred) self.alloc.free(values_json);
            try self.expect(.rparen);
            try self.validateSqlScalarValuesJson(column, values_json);
            try in_predicates.append(self.alloc, .{
                .field = field,
                .values_json = values_json,
                .negated = negated,
            });
            field_transferred = true;
            values_transferred = true;
            return;
        }
        if (op == .ne and self.matchAnyOrSomeKeyword()) {
            if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
            try self.expect(.lparen);
            const values_json = try self.parseJsonArrayValueAlloc();
            defer self.alloc.free(values_json);
            try self.expect(.rparen);
            try self.validateSqlScalarValuesJson(column, values_json);
            if (negated) {
                try self.appendScalarAllEqualityPredicates(predicates, field, values_json);
            } else {
                try self.appendScalarValuesJsonOrGroups(or_predicates, field, values_json, .ne);
            }
            return;
        }
        if (op == .eq and self.matchKeyword("all")) {
            if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
            try self.expect(.lparen);
            const values_json = try self.parseJsonArrayValueAlloc();
            defer self.alloc.free(values_json);
            try self.expect(.rparen);
            try self.validateSqlScalarValuesJson(column, values_json);
            try self.appendScalarAllEqualityPredicates(predicates, field, values_json);
            return;
        }
        if (op == .ne and self.matchKeyword("all")) {
            if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
            try self.expect(.lparen);
            const values_json = try self.parseJsonArrayValueAlloc();
            var values_transferred = false;
            errdefer if (!values_transferred) self.alloc.free(values_json);
            try self.expect(.rparen);
            try self.validateSqlScalarValuesJson(column, values_json);
            try in_predicates.append(self.alloc, .{
                .field = field,
                .values_json = values_json,
                .negated = !negated,
            });
            field_transferred = true;
            values_transferred = true;
            return;
        }
        if (negated) return error.UnsupportedSqlShape;
        const value_json = if (column.field_type == .array and op == .eq)
            try self.parseArrayPredicateValueAlloc()
        else
            try self.parseSqlColumnValueAlloc(column);
        var value_transferred = false;
        errdefer if (!value_transferred) self.alloc.free(value_json);
        if (column.field_type == .array) {
            if (op != .eq) return error.UnsupportedSqlShape;
            try self.validateSqlArrayValueJson(column, value_json);
            try array_eq.append(self.alloc, .{
                .field = field,
                .value_json = value_json,
            });
            field_transferred = true;
            value_transferred = true;
            return;
        }
        try predicates.append(self.alloc, .{
            .name = "",
            .field = field,
            .op = op,
            .value_json = value_json,
        });
        field_transferred = true;
        value_transferred = true;
    }

    fn appendBetweenPredicate(
        self: *@This(),
        predicates: *std.ArrayListUnmanaged(runtime_schema.RelationalCheck),
        or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
        field: []const u8,
        column: runtime_schema.RelationalColumn,
        negated: bool,
    ) !void {
        if (column.field_type == .array or column.field_type == .json) return error.InvalidSqlCatalog;
        const lower_json = try self.parseSqlColumnValueAlloc(column);
        var lower_transferred = false;
        errdefer if (!lower_transferred) self.alloc.free(lower_json);
        try self.expectKeyword("and");
        const upper_json = try self.parseSqlColumnValueAlloc(column);
        var upper_transferred = false;
        errdefer if (!upper_transferred) self.alloc.free(upper_json);

        if (!negated) {
            const lower_field = try self.alloc.dupe(u8, field);
            var lower_field_transferred = false;
            errdefer if (!lower_field_transferred) self.alloc.free(lower_field);
            const upper_field = try self.alloc.dupe(u8, field);
            var upper_field_transferred = false;
            errdefer if (!upper_field_transferred) self.alloc.free(upper_field);
            try predicates.append(self.alloc, .{
                .name = "",
                .field = lower_field,
                .op = .gte,
                .value_json = lower_json,
            });
            lower_field_transferred = true;
            lower_transferred = true;
            try predicates.append(self.alloc, .{
                .name = "",
                .field = upper_field,
                .op = .lte,
                .value_json = upper_json,
            });
            upper_field_transferred = true;
            upper_transferred = true;
            return;
        }

        const lower_group = try self.alloc.alloc(runtime_schema.RelationalCheck, 1);
        var lower_group_transferred = false;
        errdefer if (!lower_group_transferred) self.alloc.free(lower_group);
        const lower_field = try self.alloc.dupe(u8, field);
        var lower_field_transferred = false;
        errdefer if (!lower_field_transferred) self.alloc.free(lower_field);
        lower_group[0] = .{
            .name = "",
            .field = lower_field,
            .op = .lt,
            .value_json = lower_json,
        };
        lower_field_transferred = true;
        lower_transferred = true;

        const upper_group = try self.alloc.alloc(runtime_schema.RelationalCheck, 1);
        var upper_group_transferred = false;
        errdefer if (!upper_group_transferred) self.alloc.free(upper_group);
        const upper_field = try self.alloc.dupe(u8, field);
        var upper_field_transferred = false;
        errdefer if (!upper_field_transferred) self.alloc.free(upper_field);
        upper_group[0] = .{
            .name = "",
            .field = upper_field,
            .op = .gt,
            .value_json = upper_json,
        };
        upper_field_transferred = true;
        upper_transferred = true;

        try or_predicates.append(self.alloc, .{ .predicates = lower_group });
        lower_group_transferred = true;
        try or_predicates.append(self.alloc, .{ .predicates = upper_group });
        upper_group_transferred = true;
    }

    fn appendBooleanIsNotPredicateGroups(
        self: *@This(),
        or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
        field: []const u8,
        value: bool,
    ) !void {
        const ne_group = try self.alloc.alloc(runtime_schema.RelationalCheck, 1);
        var ne_group_transferred = false;
        var ne_group_initialized = false;
        errdefer if (!ne_group_transferred) {
            if (ne_group_initialized) freeRelationalChecks(self.alloc, ne_group);
            self.alloc.free(ne_group);
        };
        try self.initRelationalBooleanCheck(&ne_group[0], field, .ne, value);
        ne_group_initialized = true;

        const null_group = try self.alloc.alloc(runtime_schema.RelationalCheck, 1);
        var null_group_transferred = false;
        var null_group_initialized = false;
        errdefer if (!null_group_transferred) {
            if (null_group_initialized) freeRelationalChecks(self.alloc, null_group);
            self.alloc.free(null_group);
        };
        try self.initRelationalNullCheck(&null_group[0], field, .is_null);
        null_group_initialized = true;

        try or_predicates.append(self.alloc, .{ .predicates = ne_group });
        ne_group_transferred = true;
        try or_predicates.append(self.alloc, .{ .predicates = null_group });
        null_group_transferred = true;
    }

    fn expandBooleanIsNotIntoOrBranches(
        self: *@This(),
        branches: *std.ArrayListUnmanaged(ScalarOrCheckBranch),
        field: []const u8,
        value: bool,
    ) !void {
        if (branches.items.len == 0 or branches.items.len > max_scalar_or_expanded_branches / 2) return error.UnsupportedSqlShape;

        var expanded = std.ArrayListUnmanaged(ScalarOrCheckBranch).empty;
        errdefer self.freeScalarOrCheckBranches(&expanded);
        for (branches.items) |*source_branch| {
            var ne_branch = ScalarOrCheckBranch.empty;
            var ne_branch_transferred = false;
            errdefer if (!ne_branch_transferred) {
                freeRelationalChecks(self.alloc, ne_branch.items);
                ne_branch.deinit(self.alloc);
            };
            try self.cloneScalarOrBranchInto(&ne_branch, source_branch.*);
            try self.appendScalarBooleanCheckToBranch(&ne_branch, field, .ne, value);
            try expanded.append(self.alloc, ne_branch);
            ne_branch_transferred = true;

            var null_branch = ScalarOrCheckBranch.empty;
            var null_branch_transferred = false;
            errdefer if (!null_branch_transferred) {
                freeRelationalChecks(self.alloc, null_branch.items);
                null_branch.deinit(self.alloc);
            };
            try self.cloneScalarOrBranchInto(&null_branch, source_branch.*);
            try self.appendScalarNullCheckToBranch(&null_branch, field, .is_null);
            try expanded.append(self.alloc, null_branch);
            null_branch_transferred = true;
        }

        self.freeScalarOrCheckBranches(branches);
        branches.* = expanded;
    }

    fn appendScalarValuesJsonOrGroups(
        self: *@This(),
        or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
        field: []const u8,
        values_json: []const u8,
        op: runtime_schema.RelationalCheckOp,
    ) !void {
        var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, values_json, .{}) catch return error.UnsupportedSqlShape;
        defer parsed.deinit();
        if (parsed.value != .array or parsed.value.array.items.len == 0 or parsed.value.array.items.len > max_scalar_or_expanded_branches) return error.UnsupportedSqlShape;

        for (parsed.value.array.items) |value| {
            const group = try self.alloc.alloc(runtime_schema.RelationalCheck, 1);
            var group_transferred = false;
            var group_initialized = false;
            errdefer if (!group_transferred) {
                if (group_initialized) freeRelationalChecks(self.alloc, group);
                self.alloc.free(group);
            };

            const owned_field = try self.alloc.dupe(u8, field);
            var field_transferred = false;
            errdefer if (!field_transferred) self.alloc.free(owned_field);

            const value_json = try std.json.Stringify.valueAlloc(self.alloc, value, .{});
            var value_transferred = false;
            errdefer if (!value_transferred) self.alloc.free(value_json);

            group[0] = .{
                .name = "",
                .field = owned_field,
                .op = op,
                .value_json = value_json,
            };
            group_initialized = true;
            field_transferred = true;
            value_transferred = true;

            try or_predicates.append(self.alloc, .{ .predicates = group });
            group_transferred = true;
        }
    }

    fn appendScalarAllEqualityPredicates(
