    fn expressionFromCoalesceProjectionAlloc(
        self: *@This(),
        projection: db_mod.types.RelationalRowsCoalesceProjection,
    ) !db_mod.types.RelationalRowsExpression {
        var expression_projection = try expressionProjectionFromCoalesceAlloc(self.alloc, projection);
        self.alloc.free(expression_projection.output);
        expression_projection.output = "";
        return expression_projection.expression;
    }

    fn cloneOrderForNullTestAlloc(
        self: *@This(),
        order: db_mod.types.RelationalRowsQueryOrder,
    ) !db_mod.types.RelationalRowsQueryOrder {
        if (order.expression) |expression| {
            return .{ .expression = try cloneExpressionAlloc(self.alloc, expression) };
        }
        if (order.field.len == 0) return error.UnsupportedSqlShape;
        return .{ .field = try self.alloc.dupe(u8, order.field) };
    }

    fn parseOrderExpressionAlloc(self: *@This()) !db_mod.types.RelationalRowsQueryOrder {
        if (self.peekParenthesizedNullTestProjection()) {
            _ = self.match(.lparen) orelse unreachable;
            const parsed_field = try self.parseFieldExpressionOwned();
            defer self.alloc.free(parsed_field);
            const field = try self.normalizeRowExpressionFieldAlloc(parsed_field);
            var field_transferred = false;
            errdefer if (!field_transferred) self.alloc.free(field);
            if (relationalColumnForField(self.schema, field, null) == null) return error.InvalidSqlCatalog;
            try self.expectKeyword("is");
            const null_test: db_mod.types.RelationalRowsQueryOrderNullTest = if (self.matchKeyword("not")) blk: {
                try self.expectKeyword("null");
                break :blk .is_not_null;
            } else blk: {
                try self.expectKeyword("null");
                break :blk .is_null;
            };
            try self.expect(.rparen);
            field_transferred = true;
            return .{ .field = field, .null_test = null_test };
        }
        if (self.peekKind(.lparen)) {
            const expression = try self.parseParenthesizedRowExpressionAlloc();
            var expression_transferred = false;
            errdefer if (!expression_transferred) freeExpression(self.alloc, expression);
            try self.validateNumericOrDatetimeRowExpression(expression);
            expression_transferred = true;
            return .{ .expression = expression };
        }

        if (self.nextRowExpressionHasTopLevelPipeConcat()) {
            const expression = try self.parseRowExpressionAlloc();
            var expression_transferred = false;
            errdefer if (!expression_transferred) freeExpression(self.alloc, expression);
            try self.validateTextRowExpression(expression);
            expression_transferred = true;
            return .{ .expression = expression };
        }
        if (self.peekKeyword("lower") or self.peekKeyword("upper") or self.peekKeyword("trim")) {
            const expression = try self.parseCaseFoldRowExpressionAlloc();
            var expression_transferred = false;
            errdefer if (!expression_transferred) freeExpression(self.alloc, expression);
            if (expression.kind != .trim and expression.operands.len == 1 and expression.operands[0].kind == .field) {
                const generated_op: runtime_schema.RelationalGeneratedOp = switch (expression.kind) {
                    .lower => .lower,
                    .upper => .upper,
                    else => unreachable,
                };
                if (generatedCaseFoldColumnForField(self.schema, generated_op, expression.operands[0].field)) |generated| {
                    const field = try self.alloc.dupe(u8, generated.name);
                    freeExpression(self.alloc, expression);
                    expression_transferred = true;
