                }
            }
            expression_transferred = true;
            return .{ .expression = expression };
        }
        if (self.peekKeyword("concat")) {
            if (try self.generatedConcatColumnAtCurrent()) |generated| {
                const consumed = try self.parseFieldExpressionOwned();
                defer self.alloc.free(consumed);
                return .{ .field = try self.alloc.dupe(u8, generated.name) };
            }
            const expression = try self.parseRowExpressionAlloc();
            return .{ .expression = expression };
        }
        if (self.peekKeyword("array_length") or self.peekKeyword("case") or self.peekKeyword("cast") or self.peekKeyword("coalesce") or self.peekKeyword("replace") or self.peekKeyword("nullif") or self.peekLengthFunctionKeyword() or self.peekKeyword("abs") or self.peekKeyword("round") or self.peekFunctionCall("floor") or self.peekFunctionCall("ceil") or self.peekKeyword("greatest") or self.peekKeyword("least")) {
            const expression = try self.parseRowExpressionAlloc();
            return .{ .expression = expression };
        }
        if (self.peekKind(.minus)) {
            const expression = try self.parseRowExpressionAlloc();
            try self.validateNumericRowExpression(expression);
            return .{ .expression = expression };
        }

        const parsed_field = try self.parseFieldExpressionOwned();
        defer self.alloc.free(parsed_field);
        const field = try self.normalizeRowExpressionFieldAlloc(parsed_field);
        var field_transferred = false;
        errdefer if (!field_transferred) self.alloc.free(field);
        if (relationalColumnForField(self.schema, field, null) == null) return error.InvalidSqlCatalog;
        if (self.peekArithmeticOperator()) |_| {
            const column = relationalColumnForField(self.schema, field, null) orelse return error.InvalidSqlCatalog;
            if (column.field_type != .numeric and column.field_type != .datetime) return error.InvalidSqlCatalog;
            field_transferred = true;
            const expression = try self.parseArithmeticExpressionRestAlloc(.{ .kind = .field, .field = field }, 0);
            try self.validateNumericRowExpression(expression);
            return .{ .expression = expression };
        }
        field_transferred = true;
        return .{ .field = field };
    }

    fn parseGroupBy(self: *@This(), group_by: *std.ArrayListUnmanaged([]const u8)) !void {
        while (true) {
            const field = try self.parseFieldExpressionOwned();
            var field_transferred = false;
            errdefer if (!field_transferred) self.alloc.free(field);
            if (self.peekKind(.lparen) or self.peekKind(.arrow_text) or self.peekKind(.arrow_json)) return error.UnsupportedSqlShape;
            if (relationalColumnForField(self.schema, field, null) == null) return error.InvalidSqlCatalog;
            try group_by.append(self.alloc, field);
            field_transferred = true;
            if (self.match(.comma) == null) break;
        }
    }

    fn parseAggregateGroupBy(
        self: *@This(),
        group_by: *std.ArrayListUnmanaged([]const u8),
        group_expressions: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionProjection),
        select: AggregateSelectList,
    ) !void {
        while (true) {
            if (self.match(.number)) |token| {
                const ordinal = std.fmt.parseInt(u32, token.text, 10) catch return error.UnsupportedSqlShape;
                try self.appendAggregateGroupByOrdinal(group_by, group_expressions, select, ordinal);
            } else if (self.peekStandaloneAggregateGroupIdentifier()) {
                const raw_field = try self.parseFieldExpressionOwned();
                try self.appendAggregateGroupByFieldOrAlias(group_by, group_expressions, select, raw_field);
            } else {
                const item = try self.parseSelectItem();
                var item_transferred = false;
                errdefer if (!item_transferred) freeSelectItem(self.alloc, item);
                switch (item) {
                    .field => |field| try group_by.append(self.alloc, field),
                    .expression => |projection| try group_expressions.append(self.alloc, projection),
                    else => return error.UnsupportedSqlShape,
                }
                item_transferred = true;
            }
            if (self.match(.comma) == null) break;
        }
    }

    fn peekStandaloneAggregateGroupIdentifier(self: *@This()) bool {
        if (!self.peekKind(.identifier)) return false;
        if (self.pos + 1 >= self.tokens.len) return true;
        return switch (self.tokens[self.pos + 1].kind) {
            .lparen, .arrow_json, .arrow_text, .plus, .minus, .star, .slash, .pipe_concat => false,
            else => true,
        };
    }

    fn appendAggregateGroupByFieldOrAlias(
        self: *@This(),
        group_by: *std.ArrayListUnmanaged([]const u8),
        group_expressions: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionProjection),
        select: AggregateSelectList,
        raw_field: []const u8,
    ) !void {
        var raw_owned = true;
        defer if (raw_owned) self.alloc.free(raw_field);

        const normalized_field: ?[]const u8 = self.normalizeRowExpressionFieldAlloc(raw_field) catch |err| switch (err) {
            error.InvalidSqlCatalog => null,
            else => return err,
        };
        if (normalized_field) |field| {
            var field_owned = true;
            errdefer if (field_owned) self.alloc.free(field);
            if (relationalColumnForField(self.schema, field, null) != null) {
                try group_by.append(self.alloc, field);
                field_owned = false;
                raw_owned = false;
                self.alloc.free(raw_field);
                return;
            }
            self.alloc.free(field);
            field_owned = false;
        }

        for (select.group_expressions) |projection| {
            if (std.mem.eql(u8, projection.output, raw_field)) {
                try group_expressions.append(self.alloc, try cloneExpressionProjection(self.alloc, projection));
                return;
            }
        }
        return error.InvalidSqlCatalog;
    }

    fn appendAggregateGroupByOrdinal(
        self: *@This(),
        group_by: *std.ArrayListUnmanaged([]const u8),
        group_expressions: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionProjection),
        select: AggregateSelectList,
        ordinal: u32,
    ) !void {
        if (ordinal == 0) return error.UnsupportedSqlShape;
        const index: usize = @intCast(ordinal - 1);
        if (index >= select.outputs.len) return error.UnsupportedSqlShape;
        const output = select.outputs[index];
        switch (output.kind) {
            .group_field => try group_by.append(self.alloc, try self.alloc.dupe(u8, select.group_fields[output.index])),
            .group_expression => try group_expressions.append(self.alloc, try cloneExpressionProjection(self.alloc, select.group_expressions[output.index])),
            .aggregation => return error.UnsupportedSqlShape,
        }
    }

    fn parseAggregateOrderBy(
        self: *@This(),
        order_by: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    ) !void {
        while (true) {
            var order = if (self.match(.number)) |token| blk: {
                const ordinal = std.fmt.parseInt(u32, token.text, 10) catch return error.UnsupportedSqlShape;
                break :blk db_mod.types.RelationalRowsQueryOrder{ .field = try self.aggregateOutputFieldByOrdinalAlloc(group_fields, group_expressions, aggregations, ordinal) };
            } else if (self.peekAggregateOutputOrderExpression()) blk: {
                break :blk try self.parseAggregateOutputOrderExpressionAlloc(group_fields, group_expressions, aggregations);
            } else blk: {
                const field = try self.parseAggregateOutputFieldAlloc(group_fields, group_expressions, aggregations);
                if (!aggregateOutputFieldIsUnique(group_fields, group_expressions, aggregations, field)) {
                    self.alloc.free(field);
                    return error.UnsupportedSqlShape;
                }
                break :blk db_mod.types.RelationalRowsQueryOrder{ .field = field };
            };
            var order_transferred = false;
            errdefer if (!order_transferred) {
                if (order.field.len > 0) self.alloc.free(order.field);
                if (order.expression) |expression| freeExpression(self.alloc, expression);
            };
            const explicit_nulls_first = try self.applyOrderModifiers(&order);
            try self.appendOrderWithNullPlacement(order_by, order, explicit_nulls_first);
            order_transferred = true;
            if (self.match(.comma) == null) break;
        }
    }

    fn peekAggregateOutputOrderExpression(self: *@This()) bool {
        if (self.peekKind(.lparen)) return true;
        if (self.peekKind(.minus)) return true;
        if (self.nextRowExpressionHasTopLevelPipeConcat()) return true;
        if (self.peekKeyword("lower") or
            self.peekKeyword("upper") or
            self.peekKeyword("trim") or
            self.peekKeyword("replace") or
            self.peekKeyword("concat") or
            self.peekKeyword("array_length") or
            self.peekKeyword("string_to_array") or
            self.peekKeyword("case") or
            self.peekKeyword("cast") or
            self.peekKeyword("coalesce") or
            self.peekKeyword("nullif") or
            self.peekLengthFunctionKeyword() or
            self.peekKeyword("abs") or
            self.peekKeyword("round") or
            self.peekFunctionCall("floor") or
            self.peekFunctionCall("ceil") or
            self.peekKeyword("greatest") or
            self.peekKeyword("least"))
        {
            return true;
        }
        if (self.peekKind(.identifier) and self.pos + 1 < self.tokens.len) {
            return switch (self.tokens[self.pos + 1].kind) {
                .plus, .minus, .star, .slash, .pipe_concat, .arrow_json, .arrow_text => true,
                else => false,
            };
        }
        return false;
    }

    fn parseAggregateOutputOrderExpressionAlloc(
        self: *@This(),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    ) !db_mod.types.RelationalRowsQueryOrder {
        const output_columns = try self.aggregateOutputColumnsAlloc(group_fields, group_expressions, aggregations);
        defer if (output_columns.len > 0) self.alloc.free(output_columns);
        const prior_schema = self.schema;
        self.schema = .{
            .storage_mode = .relational,
            .relational_columns = output_columns,
        };
        defer self.schema = prior_schema;
        return try self.parseOrderExpressionAlloc();
    }

    fn aggregateOutputFieldByOrdinalAlloc(
        self: *@This(),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
        ordinal: u32,
    ) ![]const u8 {
        if (ordinal == 0) return error.UnsupportedSqlShape;
        var index: usize = @intCast(ordinal - 1);
        if (index < group_fields.len) return try self.alloc.dupe(u8, group_fields[index]);
        index -= group_fields.len;
        if (index < group_expressions.len) return try self.alloc.dupe(u8, group_expressions[index].output);
        index -= group_expressions.len;
        if (index < aggregations.len) return try self.alloc.dupe(u8, aggregations[index].name);
        return error.UnsupportedSqlShape;
    }

    fn parseWindowOutputOrderBy(
        self: *@This(),
        order_by: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder),
        select: WindowSelectList,
    ) !void {
        while (true) {
            var order = if (self.match(.number)) |token| blk: {
                const ordinal = std.fmt.parseInt(u32, token.text, 10) catch return error.UnsupportedSqlShape;
                const field = try self.windowOutputFieldByOrdinalAlloc(select, ordinal);
                if (!windowOutputFieldIsUnique(select.fields, select.windows, field)) {
                    self.alloc.free(field);
                    return error.UnsupportedSqlShape;
                }
                break :blk db_mod.types.RelationalRowsQueryOrder{ .field = field };
            } else if (self.peekWindowOutputOrderExpression()) blk: {
                break :blk try self.parseWindowOutputOrderExpressionAlloc(select);
            } else blk: {
                const field = try self.parseIdentifierOwned();
                if (!windowOutputFieldIsUnique(select.fields, select.windows, field)) {
                    self.alloc.free(field);
                    return error.UnsupportedSqlShape;
                }
                break :blk db_mod.types.RelationalRowsQueryOrder{ .field = field };
            };
            var order_transferred = false;
            errdefer if (!order_transferred) {
                if (order.field.len > 0) self.alloc.free(order.field);
                if (order.expression) |expression| freeExpression(self.alloc, expression);
            };
            const explicit_nulls_first = try self.applyOrderModifiers(&order);
            try self.appendOrderWithNullPlacement(order_by, order, explicit_nulls_first);
            order_transferred = true;
            if (self.match(.comma) == null) break;
        }
    }

    fn peekWindowOutputOrderExpression(self: *@This()) bool {
        return self.peekAggregateOutputOrderExpression();
    }

    fn parseWindowOutputOrderExpressionAlloc(
        self: *@This(),
        select: WindowSelectList,
    ) !db_mod.types.RelationalRowsQueryOrder {
        const output_columns = try self.windowOutputColumnsAlloc(select);
        defer if (output_columns.len > 0) self.alloc.free(output_columns);
        const prior_schema = self.schema;
        self.schema = .{
            .storage_mode = .relational,
            .relational_columns = output_columns,
        };
        defer self.schema = prior_schema;
        return try self.parseOrderExpressionAlloc();
    }

    fn windowOutputFieldByOrdinalAlloc(
        self: *@This(),
        select: WindowSelectList,
        ordinal: u32,
    ) ![]const u8 {
        if (ordinal == 0) return error.UnsupportedSqlShape;
        const index: usize = @intCast(ordinal - 1);
        if (index >= select.outputs.len) return error.UnsupportedSqlShape;
        const output = select.outputs[index];
        return switch (output.kind) {
            .field => try self.alloc.dupe(u8, select.fields[output.index]),
            .window => try self.alloc.dupe(u8, select.windows[output.index].output),
        };
    }

    fn windowOutputColumnsAlloc(
        self: *@This(),
        select: WindowSelectList,
    ) ![]runtime_schema.RelationalColumn {
        const total = select.fields.len + select.windows.len;
        if (total == 0) return &.{};
        const out = try self.alloc.alloc(runtime_schema.RelationalColumn, total);
        var initialized: usize = 0;
        errdefer self.alloc.free(out);
        for (select.fields) |field| {
            if (aggregateOutputColumnExists(out[0..initialized], field)) return error.UnsupportedSqlShape;
            const column = relationalColumnForField(self.schema, field, null) orelse return error.InvalidSqlCatalog;
            out[initialized] = .{
                .name = field,
                .path = field,
                .field_type = column.field_type,
                .array_item_type = column.array_item_type,
                .nullable = column.nullable,
            };
            initialized += 1;
        }
        for (select.windows) |window| {
            if (aggregateOutputColumnExists(out[0..initialized], window.output)) return error.UnsupportedSqlShape;
            out[initialized] = .{
                .name = window.output,
                .path = window.output,
                .field_type = try self.windowOutputType(window),
                .nullable = true,
            };
            initialized += 1;
        }
        return out;
    }

    fn windowOutputType(
        self: *@This(),
        window: db_mod.types.RelationalRowsWindowSpec,
    ) !runtime_schema.AntflyType {
        return switch (window.function) {
            .row_number, .rank, .dense_rank, .percent_rank, .cume_dist, .ntile, .count, .sum, .avg => .numeric,
            .lag, .lead, .first_value, .last_value, .nth_value, .min, .max => try self.rowExpressionOutputType(window.value_expression orelse return error.UnsupportedSqlShape),
        };
    }

    fn parseAggregateHaving(
        self: *@This(),
        predicates: *std.ArrayListUnmanaged(runtime_schema.RelationalCheck),
        expressions: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition),
        any_groups: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        not_groups: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    ) !void {
        if (self.whereHasTopLevelOr() or self.aggregateHavingHasBooleanIsNot()) {
            try self.parseAggregateHavingOrGroups(any_groups, group_fields, group_expressions, aggregations);
            return;
        }
        while (true) {
            if (self.canParseAggregateHavingNot()) {
                try self.parseAggregateHavingNotGroup(not_groups, group_fields, group_expressions, aggregations);
            } else if (self.matchStandaloneSqlBooleanLiteral()) |enabled| {
                if (!enabled) try self.appendBooleanConstantExpressionCondition(expressions, false);
            } else if (self.peekAggregateHavingExpression()) {
                const condition = try self.parseAggregateOutputExpressionConditionAlloc(group_fields, group_expressions, aggregations);
                var condition_transferred = false;
                errdefer if (!condition_transferred) freeExpressionCondition(self.alloc, condition);
                try expressions.append(self.alloc, condition);
                condition_transferred = true;
            } else {
                const field = try self.parseAggregateOutputFieldAlloc(group_fields, group_expressions, aggregations);
                var field_transferred = false;
                errdefer if (!field_transferred) self.alloc.free(field);
                if (!aggregateOutputFieldIsUnique(group_fields, group_expressions, aggregations, field)) return error.UnsupportedSqlShape;
                const column = try self.aggregateOutputColumnForFieldAlloc(group_fields, group_expressions, aggregations, field);
                var predicate_transferred = false;
                const op: runtime_schema.RelationalCheckOp = if (self.matchKeyword("is")) blk: {
                    const not = self.matchKeyword("not");
                    if (self.matchKeyword("distinct")) {
                        try self.expectKeyword("from");
                        break :blk if (not) .is_not_distinct else .is_distinct;
                    }
                    if (try self.parseSqlBooleanIsUnknown(column)) {
                        break :blk if (not) .is_not_null else .is_null;
                    }
                    if (try self.parseSqlBooleanIsValueAlloc(column, not)) |value_json| {
                        var value_transferred = false;
                        errdefer if (!value_transferred) self.alloc.free(value_json);
                        try predicates.append(self.alloc, .{
                            .name = "",
                            .field = field,
                            .op = .eq,
                            .value_json = value_json,
                        });
                        field_transferred = true;
                        value_transferred = true;
                        predicate_transferred = true;
                        break :blk .eq;
                    }
                    const null_op: runtime_schema.RelationalCheckOp = if (not) op_blk: {
                        try self.expectKeyword("null");
                        break :op_blk .is_not_null;
                    } else op_blk: {
                        try self.expectKeyword("null");
                        break :op_blk .is_null;
                    };
                    break :blk null_op;
                } else try self.parseComparisonOp();
                if (predicate_transferred) {
                    if (!self.matchKeyword("and")) break;
                    continue;
                }
                const value_json = switch (op) {
                    .is_null, .is_not_null => null,
                    else => try self.parseJsonValueAlloc(),
                };
                var value_transferred = false;
                errdefer if (!value_transferred) if (value_json) |json| self.alloc.free(json);
                try predicates.append(self.alloc, .{
                    .name = "",
                    .field = field,
                    .op = op,
                    .value_json = value_json,
                });
                field_transferred = true;
                value_transferred = true;
            }
            if (!self.matchKeyword("and")) break;
        }
    }

    fn aggregateHavingHasBooleanIsNot(self: *@This()) bool {
        var depth: usize = 0;
        var i = self.pos;
        while (i + 2 < self.tokens.len) : (i += 1) {
            const token = self.tokens[i];
            switch (token.kind) {
                .lparen => depth += 1,
                .rparen => {
                    if (depth == 0) return false;
                    depth -= 1;
                },
                .identifier => {
                    if (depth == 0 and (std.ascii.eqlIgnoreCase(token.text, "order") or
                        std.ascii.eqlIgnoreCase(token.text, "limit") or
                        std.ascii.eqlIgnoreCase(token.text, "offset") or
                        std.ascii.eqlIgnoreCase(token.text, "fetch")))
                    {
                        return false;
                    }
                    if (std.ascii.eqlIgnoreCase(token.text, "is") and
                        self.tokens[i + 1].kind == .identifier and
                        std.ascii.eqlIgnoreCase(self.tokens[i + 1].text, "not") and
                        self.tokens[i + 2].kind == .identifier and
                        (std.ascii.eqlIgnoreCase(self.tokens[i + 2].text, "true") or
                            std.ascii.eqlIgnoreCase(self.tokens[i + 2].text, "false")))
                    {
                        return true;
                    }
                },
                else => {},
            }
        }
        return false;
    }

    fn canParseAggregateHavingNot(self: *@This()) bool {
        return self.peekKeyword("not") and self.pos + 1 < self.tokens.len and self.tokens[self.pos + 1].kind == .lparen;
    }

    fn parseAggregateHavingNotGroup(
        self: *@This(),
        not_groups: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    ) !void {
        try self.expectKeyword("not");
        try self.expect(.lparen);
        var groups = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
        var groups_transferred = false;
        defer groups.deinit(self.alloc);
        errdefer {
            if (!groups_transferred) freeExpressionPredicateGroups(self.alloc, groups.items);
        }
        try groups.append(self.alloc, .{ .conditions = &.{} });

        while (true) {
            var alternatives = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
            defer alternatives.deinit(self.alloc);
            errdefer freeExpressionPredicateGroups(self.alloc, alternatives.items);
            try self.parseAggregateHavingConditionAlternatives(&alternatives, group_fields, group_expressions, aggregations);
            try self.andExpressionPredicateAlternatives(&groups, alternatives.items);
            freeExpressionPredicateGroups(self.alloc, alternatives.items);
            if (!self.matchKeyword("and")) break;
        }
        if (groups.items.len == 0) return error.UnsupportedSqlShape;
        try self.expect(.rparen);

        try not_groups.appendSlice(self.alloc, groups.items);
        groups_transferred = true;
    }

    fn parseAggregateHavingOrGroups(
        self: *@This(),
        any_groups: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    ) !void {
        while (true) {
            const parenthesized = self.matchBooleanGroupOpen();
            var groups = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
            var groups_transferred = false;
            defer groups.deinit(self.alloc);
            errdefer {
                if (!groups_transferred) freeExpressionPredicateGroups(self.alloc, groups.items);
            }
            try groups.append(self.alloc, .{ .conditions = &.{} });

            while (true) {
                var alternatives = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
                defer alternatives.deinit(self.alloc);
                errdefer freeExpressionPredicateGroups(self.alloc, alternatives.items);
                try self.parseAggregateHavingConditionAlternatives(&alternatives, group_fields, group_expressions, aggregations);
                try self.andExpressionPredicateAlternatives(&groups, alternatives.items);
                freeExpressionPredicateGroups(self.alloc, alternatives.items);
                if (!self.matchKeyword("and")) break;
            }
            if (groups.items.len == 0) return error.UnsupportedSqlShape;
            if (parenthesized) try self.expect(.rparen);
            try any_groups.appendSlice(self.alloc, groups.items);
            groups_transferred = true;

            if (!self.matchKeyword("or")) break;
        }
    }

    fn parseAggregateHavingConditionAlternatives(
        self: *@This(),
        alternatives: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    ) !void {
        if (self.matchStandaloneSqlBooleanLiteral()) |enabled| {
            try self.appendBooleanConstantExpressionGroup(alternatives, enabled);
            return;
        }
        if (try self.parseAggregateHavingBooleanIsNotGroups(alternatives, group_fields, group_expressions, aggregations)) {
            return;
        }

        const condition = if (self.peekAggregateHavingExpression())
            try self.parseAggregateOutputExpressionConditionAlloc(group_fields, group_expressions, aggregations)
        else
            try self.parseAggregateOutputFieldExpressionConditionAlloc(group_fields, group_expressions, aggregations);
        var condition_transferred = false;
        errdefer if (!condition_transferred) freeExpressionCondition(self.alloc, condition);

        const conditions = try self.alloc.alloc(db_mod.types.RelationalRowsExpressionCondition, 1);
        var conditions_transferred = false;
        errdefer if (!conditions_transferred) self.alloc.free(conditions);
        conditions[0] = condition;
        condition_transferred = true;
        try alternatives.append(self.alloc, .{ .conditions = conditions });
        conditions_transferred = true;
    }

    fn parseAggregateHavingBooleanIsNotGroups(
        self: *@This(),
        groups: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    ) !bool {
        const saved_pos = self.pos;
        const field = self.parseAggregateOutputFieldAlloc(group_fields, group_expressions, aggregations) catch |err| {
            self.pos = saved_pos;
            return switch (err) {
                error.UnsupportedSqlShape => false,
                else => err,
            };
        };
        defer self.alloc.free(field);
        if (!self.matchKeyword("is")) {
            self.pos = saved_pos;
            return false;
        }
        if (!self.matchKeyword("not")) {
            self.pos = saved_pos;
            return false;
        }
        if (!(self.peekKeyword("true") or self.peekKeyword("false"))) {
            self.pos = saved_pos;
            return false;
        }

        const column = try self.aggregateOutputColumnForFieldAlloc(group_fields, group_expressions, aggregations, field);
        const value = (try self.parseSqlBooleanIsValue(column)) orelse return error.UnsupportedSqlShape;
        try self.appendBooleanIsNotExpressionGroups(groups, field, value);
        return true;
    }

    fn parseAggregateOutputFieldExpressionConditionAlloc(
        self: *@This(),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    ) !db_mod.types.RelationalRowsExpressionCondition {
        const field = try self.parseAggregateOutputFieldAlloc(group_fields, group_expressions, aggregations);
        var field_transferred = false;
        errdefer if (!field_transferred) self.alloc.free(field);
        if (!aggregateOutputFieldIsUnique(group_fields, group_expressions, aggregations, field)) return error.UnsupportedSqlShape;
        const column = try self.aggregateOutputColumnForFieldAlloc(group_fields, group_expressions, aggregations, field);

        const op: runtime_schema.RelationalCheckOp = if (self.matchKeyword("is")) blk: {
            const not = self.matchKeyword("not");
            if (self.matchKeyword("distinct")) {
                try self.expectKeyword("from");
                break :blk if (not) .is_not_distinct else .is_distinct;
            }
            if (try self.parseSqlBooleanIsUnknown(column)) {
                break :blk if (not) .is_not_null else .is_null;
            }
            if (try self.parseSqlBooleanIsValueAlloc(column, not)) |value_json| {
                errdefer self.alloc.free(value_json);
                const lhs_field = field;
                field_transferred = true;
                const rhs = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
                var rhs_transferred = false;
                errdefer if (!rhs_transferred) self.alloc.free(rhs);
                rhs[0] = .{
                    .kind = .value,
                    .value_json = value_json,
                };
                rhs_transferred = true;
                return .{
                    .lhs = .{
                        .kind = .field,
                        .field = lhs_field,
                    },
                    .op = .eq,
                    .rhs = rhs,
                };
            }
            try self.expectKeyword("null");
            break :blk if (not) .is_not_null else .is_null;
        } else try self.parseComparisonOp();

        const lhs: db_mod.types.RelationalRowsExpression = .{
            .kind = .field,
            .field = field,
        };
        field_transferred = true;

        const rhs = switch (op) {
            .is_null, .is_not_null => &.{},
            else => blk: {
                const value_json = try self.parseJsonValueAlloc();
                var value_transferred = false;
                errdefer if (!value_transferred) self.alloc.free(value_json);
                const out = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
                var out_transferred = false;
                errdefer if (!out_transferred) self.alloc.free(out);
                out[0] = .{
                    .kind = .value,
                    .value_json = value_json,
                };
                value_transferred = true;
                out_transferred = true;
                break :blk out;
            },
        };

        return .{
            .lhs = lhs,
            .op = op,
            .rhs = rhs,
        };
    }

    fn aggregateOutputColumnForFieldAlloc(
        self: *@This(),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
        field: []const u8,
    ) !runtime_schema.RelationalColumn {
        const output_columns = try self.aggregateOutputColumnsAlloc(group_fields, group_expressions, aggregations);
        defer if (output_columns.len > 0) self.alloc.free(output_columns);
        for (output_columns) |column| {
            if (std.mem.eql(u8, column.name, field)) return column;
        }
        return error.UnsupportedSqlShape;
    }

    fn peekAggregateHavingExpression(self: *@This()) bool {
        if (self.nextIsAggregateFunction()) return false;
        if (self.pos >= self.tokens.len) return false;
        const token = self.tokens[self.pos];
        if (self.peekParenthesizedExpressionCondition()) return true;
        if (token.kind == .identifier) {
            if (self.pos + 1 >= self.tokens.len) return false;
            const next = self.tokens[self.pos + 1];
            if (next.kind == .eq or next.kind == .neq or next.kind == .gt or next.kind == .gte or next.kind == .lt or next.kind == .lte) return false;
            if (next.kind == .identifier and std.ascii.eqlIgnoreCase(next.text, "is")) return false;
            return true;
        }
        return token.kind == .minus or
            token.kind == .number or
            self.peekKeyword("lower") or
            self.peekKeyword("upper") or
            self.peekKeyword("trim") or
            self.peekKeyword("replace") or
            self.peekKeyword("case") or
            self.peekKeyword("cast") or
            self.peekKeyword("coalesce") or
            self.peekKeyword("nullif") or
            self.peekLengthFunctionKeyword() or
            self.peekKeyword("abs") or
            self.peekKeyword("round") or
            self.peekFunctionCall("floor") or
            self.peekFunctionCall("ceil") or
            self.peekKeyword("greatest") or
            self.peekKeyword("least");
    }

    fn parseAggregateOutputExpressionConditionAlloc(
        self: *@This(),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    ) !db_mod.types.RelationalRowsExpressionCondition {
        const output_columns = try self.aggregateOutputColumnsAlloc(group_fields, group_expressions, aggregations);
        defer if (output_columns.len > 0) self.alloc.free(output_columns);
        const prior_schema = self.schema;
        self.schema = .{
            .storage_mode = .relational,
            .relational_columns = output_columns,
        };
        defer self.schema = prior_schema;
        return try self.parseCaseExpressionConditionAlloc();
    }

    fn aggregateOutputColumnsAlloc(
        self: *@This(),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    ) ![]runtime_schema.RelationalColumn {
        const total = group_fields.len + group_expressions.len + aggregations.len;
        if (total == 0) return &.{};
        const out = try self.alloc.alloc(runtime_schema.RelationalColumn, total);
        var initialized: usize = 0;
        errdefer self.alloc.free(out);
        for (group_fields) |field| {
            if (aggregateOutputColumnExists(out[0..initialized], field)) return error.UnsupportedSqlShape;
            const column = relationalColumnForField(self.schema, field, null) orelse return error.InvalidSqlCatalog;
            out[initialized] = .{
                .name = field,
                .path = field,
                .field_type = column.field_type,
                .array_item_type = column.array_item_type,
                .nullable = column.nullable,
            };
            initialized += 1;
        }
        for (group_expressions) |projection| {
            if (aggregateOutputColumnExists(out[0..initialized], projection.output)) return error.UnsupportedSqlShape;
            out[initialized] = .{
                .name = projection.output,
                .path = projection.output,
                .field_type = try self.rowExpressionOutputType(projection.expression),
                .nullable = true,
            };
            initialized += 1;
        }
        for (aggregations) |aggregation| {
            if (aggregateOutputColumnExists(out[0..initialized], aggregation.name)) return error.UnsupportedSqlShape;
            out[initialized] = .{
                .name = aggregation.name,
                .path = aggregation.name,
                .field_type = aggregateOutputType(aggregation),
                .array_item_type = if (aggregation.op == .array_agg) .keyword else null,
                .nullable = false,
            };
            initialized += 1;
        }
        return out;
    }

    fn parseAggregateOutputFieldAlloc(
        self: *@This(),
        group_fields: []const []const u8,
        group_expressions: []const db_mod.types.RelationalRowsExpressionProjection,
        aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    ) ![]const u8 {
        if (self.nextIsAggregateFunction()) {
            const candidate = try self.parseAggregateSpecAlloc();
            defer freeAggregateSpec(self.alloc, candidate);
            var matched_name: ?[]const u8 = null;
            for (aggregations) |aggregation| {
                if (!aggregateSpecsEquivalent(candidate, aggregation)) continue;
                if (matched_name != null) return error.UnsupportedSqlShape;
                matched_name = aggregation.name;
            }
            const name = matched_name orelse return error.UnsupportedSqlShape;
            return try self.alloc.dupe(u8, name);
        }

        const field = try self.parseIdentifierOwned();
        errdefer self.alloc.free(field);
        if (!aggregateOutputFieldIsUnique(group_fields, group_expressions, aggregations, field)) return error.UnsupportedSqlShape;
        return field;
    }

    fn parseComparisonOp(self: *@This()) !runtime_schema.RelationalCheckOp {
        if (self.match(.eq) != null) return .eq;
        if (self.match(.neq) != null) return .ne;
        if (self.match(.gt) != null) return .gt;
        if (self.match(.gte) != null) return .gte;
        if (self.match(.lt) != null) return .lt;
        if (self.match(.lte) != null) return .lte;
        return error.UnsupportedSqlShape;
    }

    fn parseJsonValueAlloc(self: *@This()) ![]const u8 {
        if (self.peekKeyword("convert_from")) return try self.parseConvertFromJsonAlloc();
        if (self.peekKeyword("to_jsonb")) return try self.parseToJsonbValueJsonAlloc();
        if (self.matchKeyword("null")) return try self.alloc.dupe(u8, "null");
        if (self.matchKeyword("true")) return try self.alloc.dupe(u8, "true");
        if (self.matchKeyword("false")) return try self.alloc.dupe(u8, "false");
        if (self.match(.string)) |token| return try std.json.Stringify.valueAlloc(self.alloc, token.text, .{});
        if (self.match(.number)) |token| return try self.alloc.dupe(u8, token.text);
        if (self.match(.minus) != null) return try self.parseNegativeNumberJsonAlloc();
        if (self.match(.placeholder)) |token| return try self.boundValueJsonAlloc(token);
        return error.UnsupportedSqlShape;
    }

    fn parseToJsonbValueJsonAlloc(self: *@This()) anyerror![]const u8 {
        try self.expectKeyword("to_jsonb");
        try self.expect(.lparen);
        const value_json = try self.parseJsonValueAlloc();
        errdefer self.alloc.free(value_json);
        try self.expect(.rparen);
        return value_json;
    }

    fn parseJsonDocumentValueAlloc(self: *@This()) ![]const u8 {
        if (self.match(.placeholder)) |token| {
            const value = try self.boundValue(token);
            return switch (value) {
                .json => |json| blk: {
                    try validateJsonDocument(self.alloc, json);
                    break :blk try self.alloc.dupe(u8, json);
                },
                else => error.UnsupportedSqlShape,
            };
        }
        if (self.match(.string)) |token| {
            try validateJsonDocument(self.alloc, token.text);
            return try self.alloc.dupe(u8, token.text);
        }
        return error.UnsupportedSqlShape;
    }

    fn appendJsonObjectConcatSetValues(
        self: *@This(),
        field: []const u8,
        json_set: *std.ArrayListUnmanaged(JsonSetValue),
    ) !void {
        const object_json = try self.parseJsonDocumentValueAlloc();
        defer self.alloc.free(object_json);
        var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, object_json, .{}) catch return error.UnsupportedSqlShape;
        defer parsed.deinit();
        if (parsed.value != .object) return error.UnsupportedSqlShape;
        if (parsed.value.object.count() == 0) return error.UnsupportedSqlShape;

        var it = parsed.value.object.iterator();
        while (it.next()) |entry| {
            if (std.mem.indexOfScalar(u8, entry.key_ptr.*, '.') != null) return error.UnsupportedSqlShape;
            const owned_field = try self.alloc.dupe(u8, field);
            var field_transferred = false;
            errdefer if (!field_transferred) self.alloc.free(owned_field);
            const path = try self.alloc.alloc([]const u8, 1);
            var path_transferred = false;
            errdefer if (!path_transferred) self.alloc.free(path);
            path[0] = try self.alloc.dupe(u8, entry.key_ptr.*);
            var path_item_transferred = false;
            errdefer if (!path_item_transferred) self.alloc.free(path[0]);
            const value_json = try std.json.Stringify.valueAlloc(self.alloc, entry.value_ptr.*, .{});
            var value_transferred = false;
            errdefer if (!value_transferred) self.alloc.free(value_json);
            try json_set.append(self.alloc, .{
                .field = owned_field,
                .path = path,
                .value_json = value_json,
            });
            field_transferred = true;
            path_transferred = true;
            path_item_transferred = true;
            value_transferred = true;
        }
    }

    fn parseJsonArrayValueAlloc(self: *@This()) ![]const u8 {
        const value_json = if (self.peekKeyword("array"))
            try self.parseSqlArrayConstructorJsonAlloc()
        else
            try self.parseJsonDocumentValueAlloc();
        errdefer self.alloc.free(value_json);
        try validateJsonArray(self.alloc, value_json);
        return value_json;
    }

    fn parseStructuredPredicateValueAlloc(self: *@This(), column: runtime_schema.RelationalColumn) ![]const u8 {
        return switch (column.field_type) {
            .array => try self.parseArrayPredicateValueAlloc(),
            .json => try self.parseJsonDocumentValueAlloc(),
            else => error.InvalidSqlCatalog,
        };
    }

    fn parseArrayPredicateValueAlloc(self: *@This()) ![]const u8 {
        return if (self.peekKeyword("array"))
            try self.parseSqlArrayConstructorJsonAlloc()
        else
            try self.parseJsonDocumentValueAlloc();
    }

    fn parseSqlArrayConstructorJsonAlloc(self: *@This()) ![]const u8 {
        try self.expectKeyword("array");
        try self.expect(.lbracket);
        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.writeByte('[');
        if (self.match(.rbracket) == null) {
            var first = true;
            while (true) {
                const value_json = try self.parseJsonValueAlloc();
                defer self.alloc.free(value_json);
                if (!first) try writer.writeByte(',');
                try writer.writeAll(value_json);
                first = false;
                if (self.match(.comma) == null) break;
            }
            try self.expect(.rbracket);
        }
        try writer.writeByte(']');
        return try out.toOwnedSlice();
    }

    fn parseSqlInValuesJsonAlloc(self: *@This()) ![]const u8 {
        try self.expect(.lparen);
        if (self.peekKind(.rparen)) return error.UnsupportedSqlShape;

        if (self.match(.placeholder)) |token| {
            const value = try self.boundValue(token);
            if (self.match(.rparen) != null) {
                return switch (value) {
                    .json => |json| blk: {
                        try validateJsonArray(self.alloc, json);
                        break :blk try self.alloc.dupe(u8, json);
                    },
                    else => try self.singleValueJsonArrayAlloc(value),
                };
            }
            const first_json = try value.jsonAlloc(self.alloc);
            defer self.alloc.free(first_json);
            return try self.parseSqlInRemainingValuesJsonAlloc(first_json);
        }

        const first_json = try self.parseJsonValueAlloc();
        defer self.alloc.free(first_json);
        return try self.parseSqlInRemainingValuesJsonAlloc(first_json);
    }

    fn parseSqlInRemainingValuesJsonAlloc(self: *@This(), first_json: []const u8) ![]const u8 {
        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.writeByte('[');
        try writer.writeAll(first_json);
        while (self.match(.comma) != null) {
            const value_json = try self.parseJsonValueAlloc();
            defer self.alloc.free(value_json);
            try writer.writeByte(',');
            try writer.writeAll(value_json);
        }
        try self.expect(.rparen);
        try writer.writeByte(']');
        return try out.toOwnedSlice();
    }

    fn singleValueJsonArrayAlloc(self: *@This(), value: SqlValue) ![]const u8 {
        const value_json = try value.jsonAlloc(self.alloc);
        defer self.alloc.free(value_json);
        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.writeByte('[');
        try writer.writeAll(value_json);
        try writer.writeByte(']');
        return try out.toOwnedSlice();
    }

    fn parseSqlColumnValueAlloc(self: *@This(), column: runtime_schema.RelationalColumn) ![]const u8 {
        if (self.matchKeyword("default")) {
            const default_value = column.default_value orelse return error.UnsupportedSqlShape;
            return try relational_rows.relationalDefaultValueJsonAlloc(self.alloc, default_value);
        }
        if (self.peekKeyword("now") or self.peekKeyword("current_timestamp")) {
            if (column.field_type != .numeric and column.field_type != .datetime) return error.InvalidSqlCatalog;
            return try self.parseNowValueJsonAlloc();
        }
        if (self.peekKeyword("convert_from")) {
            if (column.field_type != .json) return error.InvalidSqlCatalog;
            return try self.parseConvertFromJsonAlloc();
        }
        if (self.peekKeyword("jsonb_build_object")) {
            if (column.field_type != .json) return error.InvalidSqlCatalog;
            return try self.parseJsonbBuildObjectAlloc();
        }
        if (self.peekKeyword("to_jsonb")) {
            if (column.field_type != .json) return error.InvalidSqlCatalog;
            return try self.parseToJsonbValueJsonAlloc();
        }
        if (self.match(.placeholder)) |token| {
            const value = try self.boundValue(token);
            if (column.field_type == .json) {
                return switch (value) {
                    .json => |json| try self.alloc.dupe(u8, json),
                    else => try value.jsonAlloc(self.alloc),
                };
            }
            return try value.jsonAlloc(self.alloc);
        }
        if (self.match(.string)) |token| {
            if (column.field_type == .json) {
                if (jsonValueIsValid(self.alloc, token.text)) return try self.alloc.dupe(u8, token.text);
            }
            return try std.json.Stringify.valueAlloc(self.alloc, token.text, .{});
        }
        if (self.matchKeyword("null")) return try self.alloc.dupe(u8, "null");
        if (self.matchKeyword("true")) return try self.alloc.dupe(u8, "true");
        if (self.matchKeyword("false")) return try self.alloc.dupe(u8, "false");
        if (self.match(.number)) |token| return try self.alloc.dupe(u8, token.text);
        if (self.match(.minus) != null) return try self.parseNegativeNumberJsonAlloc();
        return error.UnsupportedSqlShape;
    }

    fn parseNowValueJsonAlloc(self: *@This()) ![]const u8 {
        if (self.matchKeyword("now")) {
            try self.expect(.lparen);
            try self.expect(.rparen);
        } else if (self.matchKeyword("current_timestamp")) {
            if (self.match(.lparen) != null) try self.expect(.rparen);
        } else {
            return error.UnsupportedSqlShape;
        }
        return try std.fmt.allocPrint(self.alloc, "{d}", .{platform_time.realtimeNs()});
    }

    fn parseConvertFromJsonAlloc(self: *@This()) ![]const u8 {
        try self.expectKeyword("convert_from");
        try self.expect(.lparen);
        const decoded = try self.parseConvertFromInputAlloc();
        defer self.alloc.free(decoded);
        try self.expect(.comma);
        const encoding = self.match(.string) orelse return error.UnsupportedSqlShape;
        if (!std.ascii.eqlIgnoreCase(encoding.text, "UTF8") and !std.ascii.eqlIgnoreCase(encoding.text, "UTF-8")) return error.UnsupportedSqlShape;
        try self.expect(.rparen);
        if (!jsonValueIsValid(self.alloc, decoded)) return error.UnsupportedSqlShape;
        return try self.alloc.dupe(u8, decoded);
    }

    fn parseConvertFromInputAlloc(self: *@This()) ![]const u8 {
        if (self.match(.placeholder)) |token| {
            const value = try self.boundValue(token);
            return switch (value) {
                .string => |text| try self.alloc.dupe(u8, text),
                .json => |json| try self.alloc.dupe(u8, json),
                else => error.UnsupportedSqlShape,
            };
        }
        if (self.match(.string)) |token| return try self.alloc.dupe(u8, token.text);
        return error.UnsupportedSqlShape;
    }

    fn parseJsonbBuildObjectAlloc(self: *@This()) ![]const u8 {
        try self.expectKeyword("jsonb_build_object");
        try self.expect(.lparen);
        if (self.match(.rparen) != null) return try self.alloc.dupe(u8, "{}");

        var seen = std.StringHashMapUnmanaged(void).empty;
        defer seen.deinit(self.alloc);
        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.writeByte('{');
        var first = true;
        while (true) {
            const key = try self.parseJsonbBuildObjectKey();
            const entry = try seen.getOrPut(self.alloc, key);
            if (entry.found_existing) return error.UnsupportedSqlShape;
            try self.expect(.comma);
            const value_json = try self.parseJsonValueAlloc();
            defer self.alloc.free(value_json);
            if (!first) try writer.writeByte(',');
            first = false;
            try writer.print("{f}:", .{std.json.fmt(key, .{})});
            try writer.writeAll(value_json);
            if (self.match(.comma) == null) break;
        }
        try self.expect(.rparen);
        try writer.writeByte('}');
        return try out.toOwnedSlice();
    }

    fn parseJsonbBuildObjectKey(self: *@This()) ![]const u8 {
        if (self.match(.string)) |token| return token.text;
        if (self.match(.placeholder)) |token| {
            const value = try self.boundValue(token);
            return switch (value) {
                .string => |key| key,
                else => error.UnsupportedSqlShape,
            };
        }
        return error.UnsupportedSqlShape;
    }

    fn parseReturningListAlloc(self: *@This()) ![]const []const u8 {
        if (self.match(.star) != null) {
            const fields = try self.alloc.alloc([]const u8, 1);
            errdefer self.alloc.free(fields);
            fields[0] = try self.alloc.dupe(u8, "*");
            return fields;
        }

        var fields = std.ArrayListUnmanaged([]const u8).empty;
        errdefer {
            for (fields.items) |field| self.alloc.free(field);
            fields.deinit(self.alloc);
        }
        while (true) {
            const field = try self.parseIdentifierOwned();
            var field_transferred = false;
            errdefer if (!field_transferred) self.alloc.free(field);
            if (self.peekKind(.lparen) or self.peekKind(.arrow_text) or self.peekKind(.arrow_json)) return error.UnsupportedSqlShape;
            if (relationalColumnForReturningField(self.schema, field) == null) return error.InvalidSqlCatalog;
            try fields.append(self.alloc, field);
            field_transferred = true;
            if (self.match(.comma) == null) break;
        }
        return try fields.toOwnedSlice(self.alloc);
    }

    fn parseReturningProjectionAlloc(
        self: *@This(),
        returning_qualifiers: []const []const u8,
    ) !ReturningProjection {
        const previous_returning_expression_qualifiers = self.returning_expression_qualifiers;
        self.returning_expression_qualifiers = returning_qualifiers;
        defer self.returning_expression_qualifiers = previous_returning_expression_qualifiers;
        const previous_field_expression_qualifiers = self.field_expression_qualifiers;
        self.field_expression_qualifiers = returning_qualifiers;
        defer self.field_expression_qualifiers = previous_field_expression_qualifiers;

        var saw_all = false;
        var fields = std.ArrayListUnmanaged([]const u8).empty;
        errdefer {
            for (fields.items) |field| self.alloc.free(field);
            fields.deinit(self.alloc);
        }
        var expressions = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionProjection).empty;
        errdefer {
            for (expressions.items) |projection| freeExpressionProjection(self.alloc, projection);
            expressions.deinit(self.alloc);
        }

        while (true) {
            const returning_all_item = self.match(.star) != null or try self.matchQualifiedReturningAll(returning_qualifiers);
            if (returning_all_item) {
                if (saw_all or fields.items.len != 0 or expressions.items.len != 0) return error.UnsupportedSqlShape;
                const all_field = try self.alloc.dupe(u8, "*");
                var all_field_transferred = false;
                errdefer if (!all_field_transferred) self.alloc.free(all_field);
                try fields.append(self.alloc, all_field);
                all_field_transferred = true;
                saw_all = true;
                if (self.match(.comma) == null) break;
                continue;
            }
            if (self.peekSimpleReturningField()) {
                const parsed_field = try self.parseFieldExpressionOwned();
                defer self.alloc.free(parsed_field);
                const field = try self.normalizeReturningFieldAlloc(parsed_field, returning_qualifiers);
                var field_owned = true;
                errdefer if (field_owned) self.alloc.free(field);
                const alias = try self.parseOptionalProjectionAliasAlloc();
                var alias_owned = true;
                errdefer if (alias_owned) if (alias) |owned| self.alloc.free(owned);
                if (alias) |output| {
                    if (std.mem.eql(u8, output, field)) {
                        self.alloc.free(output);
                        alias_owned = false;
                        try fields.append(self.alloc, field);
                        field_owned = false;
                    } else {
                        if (saw_all and relationalColumnForReturningField(self.schema, output) != null) return error.UnsupportedSqlShape;
                        try expressions.append(self.alloc, .{
                            .output = output,
                            .expression = .{
                                .kind = .field,
                                .field = field,
                            },
                        });
                        alias_owned = false;
                        field_owned = false;
                    }
                } else {
                    if (saw_all) return error.UnsupportedSqlShape;
                    try fields.append(self.alloc, field);
                    field_owned = false;
                }
                if (self.match(.comma) == null) break;
                continue;
            }
            const item = try self.parseSelectItem();
            var item_owned = true;
            errdefer if (item_owned) freeSelectItem(self.alloc, item);
            switch (item) {
                .field => |parsed_field| {
                    if (saw_all) return error.UnsupportedSqlShape;
                    const field = try self.normalizeReturningFieldAlloc(parsed_field, returning_qualifiers);
                    var field_owned = true;
                    errdefer if (field_owned) self.alloc.free(field);
                    self.alloc.free(parsed_field);
                    try fields.append(self.alloc, field);
                    field_owned = false;
                    item_owned = false;
                },
                .field_alias => |projection| {
                    const field = try self.normalizeReturningFieldAlloc(projection.field, returning_qualifiers);
                    var field_owned = true;
                    errdefer if (field_owned) self.alloc.free(field);
                    if (saw_all and relationalColumnForReturningField(self.schema, projection.output) != null) return error.UnsupportedSqlShape;
                    try expressions.append(self.alloc, .{
                        .output = projection.output,
                        .expression = .{
                            .kind = .field,
                            .field = field,
                        },
                    });
                    self.alloc.free(projection.field);
                    field_owned = false;
                    item_owned = false;
                },
                .expression => |projection| {
                    if (saw_all and relationalColumnForReturningField(self.schema, projection.output) != null) return error.UnsupportedSqlShape;
                    try expressions.append(self.alloc, projection);
                    item_owned = false;
                },
                .coalesce => |projection| {
                    if (saw_all and relationalColumnForReturningField(self.schema, projection.output) != null) return error.UnsupportedSqlShape;
                    const expression_projection = try expressionProjectionFromCoalesceAlloc(self.alloc, projection);
                    var expression_projection_owned = true;
                    errdefer if (expression_projection_owned) freeExpressionProjection(self.alloc, expression_projection);
                    try expressions.append(self.alloc, expression_projection);
                    expression_projection_owned = false;
                    freeCoalesceProjection(self.alloc, projection);
                    item_owned = false;
                },
                else => return error.UnsupportedSqlShape,
            }
            if (self.match(.comma) == null) break;
        }

        const owned_fields = try fields.toOwnedSlice(self.alloc);
        var fields_owned = true;
        errdefer if (fields_owned) freeStringSlice(self.alloc, owned_fields);
        const owned_expressions = try expressions.toOwnedSlice(self.alloc);
        errdefer freeExpressionProjections(self.alloc, owned_expressions);
        try validateReturningProjectionOutputs(self.schema, owned_fields, owned_expressions);
        fields_owned = false;
        return .{
            .fields = owned_fields,
            .expressions = owned_expressions,
        };
    }

    fn parseJoinedMutationReturningProjectionAlloc(
        self: *@This(),
        source_alias: []const u8,
        returning_qualifiers: []const []const u8,
    ) !ReturningProjection {
        const previous_returning_expression_qualifiers = self.returning_expression_qualifiers;
        self.returning_expression_qualifiers = returning_qualifiers;
        defer self.returning_expression_qualifiers = previous_returning_expression_qualifiers;
        const previous_field_expression_qualifiers = self.field_expression_qualifiers;
        self.field_expression_qualifiers = returning_qualifiers;
        defer self.field_expression_qualifiers = previous_field_expression_qualifiers;

        var saw_all = false;
        var fields = std.ArrayListUnmanaged([]const u8).empty;
        errdefer {
            for (fields.items) |field| self.alloc.free(field);
            fields.deinit(self.alloc);
        }
        var expressions = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionProjection).empty;
        errdefer {
            for (expressions.items) |projection| freeExpressionProjection(self.alloc, projection);
            expressions.deinit(self.alloc);
        }

        while (true) {
            const returning_all_item = self.match(.star) != null or try self.matchQualifiedReturningAll(returning_qualifiers);
            if (returning_all_item) {
                if (saw_all or fields.items.len != 0 or expressions.items.len != 0) return error.UnsupportedSqlShape;
                const all_field = try self.alloc.dupe(u8, "*");
                var all_field_transferred = false;
                errdefer if (!all_field_transferred) self.alloc.free(all_field);
                try fields.append(self.alloc, all_field);
                all_field_transferred = true;
                saw_all = true;
                if (self.match(.comma) == null) break;
                continue;
            }
            if (self.peekSimpleReturningField()) {
                const parsed_field = try self.parseFieldExpressionOwned();
                defer self.alloc.free(parsed_field);
                if (try self.normalizeJoinedMutationReturningSourceFieldAlloc(parsed_field, source_alias)) |source_field| {
                    var source_field_owned = true;
                    errdefer if (source_field_owned) self.alloc.free(source_field);
                    const alias = try self.parseOptionalProjectionAliasAlloc();
                    var alias_owned = true;
                    errdefer if (alias_owned) if (alias) |owned| self.alloc.free(owned);
                    const output = alias orelse try self.alloc.dupe(u8, source_field);
                    alias_owned = false;
                    var output_owned = true;
                    errdefer if (output_owned) self.alloc.free(output);
                    try expressions.append(self.alloc, .{
                        .output = output,
                        .expression = .{
                            .kind = .field,
                            .field = source_field,
                            .field_source = .source,
                        },
                    });
                    source_field_owned = false;
                    output_owned = false;
                } else {
                    const field = try self.normalizeReturningFieldAlloc(parsed_field, returning_qualifiers);
                    var field_owned = true;
                    errdefer if (field_owned) self.alloc.free(field);
                    const alias = try self.parseOptionalProjectionAliasAlloc();
                    var alias_owned = true;
                    errdefer if (alias_owned) if (alias) |owned| self.alloc.free(owned);
                    if (alias) |output| {
                        if (std.mem.eql(u8, output, field)) {
                            self.alloc.free(output);
                            alias_owned = false;
                            try fields.append(self.alloc, field);
                            field_owned = false;
                        } else {
                            if (saw_all and relationalColumnForReturningField(self.schema, output) != null) return error.UnsupportedSqlShape;
                            try expressions.append(self.alloc, .{
                                .output = output,
                                .expression = .{
                                    .kind = .field,
                                    .field = field,
                                },
                            });
                            alias_owned = false;
                            field_owned = false;
                        }
                    } else {
                        if (saw_all) return error.UnsupportedSqlShape;
                        try fields.append(self.alloc, field);
                        field_owned = false;
                    }
                }
                if (self.match(.comma) == null) break;
                continue;
            }
            const item = if (try self.nextReturningItemReferencesSourceAlias(source_alias))
                try self.parseJoinedMutationSourceSelectItem(source_alias)
            else
                try self.parseSelectItem();
            var item_owned = true;
            errdefer if (item_owned) freeSelectItem(self.alloc, item);
            switch (item) {
                .field => |parsed_field| {
                    if (saw_all) return error.UnsupportedSqlShape;
                    if (try self.normalizeJoinedMutationReturningSourceFieldAlloc(parsed_field, source_alias)) |source_field| {
                        var source_field_owned = true;
                        errdefer if (source_field_owned) self.alloc.free(source_field);
                        const output = try self.alloc.dupe(u8, source_field);
                        var output_owned = true;
                        errdefer if (output_owned) self.alloc.free(output);
                        try expressions.append(self.alloc, .{
                            .output = output,
                            .expression = .{
                                .kind = .field,
                                .field = source_field,
                                .field_source = .source,
                            },
                        });
                        source_field_owned = false;
                        output_owned = false;
                    } else {
                        const field = try self.normalizeReturningFieldAlloc(parsed_field, returning_qualifiers);
                        var field_owned = true;
                        errdefer if (field_owned) self.alloc.free(field);
                        try fields.append(self.alloc, field);
                        field_owned = false;
                    }
                    self.alloc.free(parsed_field);
                    item_owned = false;
                },
                .field_alias => |projection| {
                    if (try self.normalizeJoinedMutationReturningSourceFieldAlloc(projection.field, source_alias)) |source_field| {
                        var source_field_owned = true;
                        errdefer if (source_field_owned) self.alloc.free(source_field);
                        try expressions.append(self.alloc, .{
                            .output = projection.output,
                            .expression = .{
                                .kind = .field,
                                .field = source_field,
                                .field_source = .source,
                            },
                        });
                        self.alloc.free(projection.field);
                        source_field_owned = false;
                        item_owned = false;
                    } else {
                        const field = try self.normalizeReturningFieldAlloc(projection.field, returning_qualifiers);
                        var field_owned = true;
                        errdefer if (field_owned) self.alloc.free(field);
                        if (saw_all and relationalColumnForReturningField(self.schema, projection.output) != null) return error.UnsupportedSqlShape;
                        try expressions.append(self.alloc, .{
                            .output = projection.output,
                            .expression = .{
                                .kind = .field,
                                .field = field,
                            },
                        });
                        self.alloc.free(projection.field);
                        field_owned = false;
                        item_owned = false;
                    }
                },
                .expression => |projection| {
                    if (saw_all and relationalColumnForReturningField(self.schema, projection.output) != null) return error.UnsupportedSqlShape;
                    try expressions.append(self.alloc, projection);
                    item_owned = false;
                },
                .coalesce => |projection| {
                    if (saw_all and relationalColumnForReturningField(self.schema, projection.output) != null) return error.UnsupportedSqlShape;
                    const expression_projection = try expressionProjectionFromCoalesceAlloc(self.alloc, projection);
                    var expression_projection_owned = true;
                    errdefer if (expression_projection_owned) freeExpressionProjection(self.alloc, expression_projection);
                    try expressions.append(self.alloc, expression_projection);
                    expression_projection_owned = false;
                    freeCoalesceProjection(self.alloc, projection);
                    item_owned = false;
                },
                else => return error.UnsupportedSqlShape,
            }
            if (self.match(.comma) == null) break;
        }

        const owned_fields = try fields.toOwnedSlice(self.alloc);
        var fields_owned = true;
        errdefer if (fields_owned) freeStringSlice(self.alloc, owned_fields);
        const owned_expressions = try expressions.toOwnedSlice(self.alloc);
        errdefer freeExpressionProjections(self.alloc, owned_expressions);
        try validateReturningProjectionOutputs(self.schema, owned_fields, owned_expressions);
        fields_owned = false;
        return .{
            .fields = owned_fields,
            .expressions = owned_expressions,
        };
    }

    fn normalizeJoinedMutationReturningSourceFieldAlloc(
        self: *@This(),
        field: []const u8,
        source_alias: []const u8,
    ) !?[]const u8 {
        var dot: ?usize = std.mem.indexOfScalar(u8, field, '.');
        while (dot) |index| {
            if (index > 0 and index + 1 < field.len) {
                const qualifier = field[0..index];
                const unqualified_field = field[index + 1 ..];
                if (try self.returningQualifierMatches(qualifier, &.{source_alias})) {
                    const source_schema = self.joined_source_schema orelse self.schema;
                    if (relationalColumnForReturningField(source_schema, unqualified_field) == null) return error.InvalidSqlCatalog;
                    return try self.alloc.dupe(u8, unqualified_field);
                }
            }
            dot = std.mem.indexOfScalarPos(u8, field, index + 1, '.');
        }
        return null;
    }

    fn nextReturningItemReferencesSourceAlias(
        self: *@This(),
        source_alias: []const u8,
    ) !bool {
        var depth: usize = 0;
        var i = self.pos;
        while (i < self.tokens.len) : (i += 1) {
            const token = self.tokens[i];
            switch (token.kind) {
                .lparen => depth += 1,
                .rparen => {
                    if (depth == 0) return false;
                    depth -= 1;
                },
                .comma, .semicolon => if (depth == 0) return false,
                .identifier => {
                    if (try self.identifierHasQualifier(token.text, source_alias)) return true;
                },
                else => {},
            }
        }
        return false;
    }

    fn identifierHasQualifier(
        self: *@This(),
        identifier: []const u8,
        qualifier: []const u8,
    ) !bool {
        var dot: ?usize = std.mem.indexOfScalar(u8, identifier, '.');
        while (dot) |index| {
            if (index > 0 and index + 1 < identifier.len) {
                const candidate = identifier[0..index];
                if (std.mem.eql(u8, candidate, qualifier)) return true;
                const normalized = try normalizeSqlObjectIdentifierAlloc(self.alloc, candidate);
                defer self.alloc.free(normalized);
                if (std.mem.eql(u8, normalized, qualifier)) return true;
            }
            dot = std.mem.indexOfScalarPos(u8, identifier, index + 1, '.');
        }
        return false;
    }

    fn parseJoinedMutationSourceSelectItem(
        self: *@This(),
        source_alias: []const u8,
    ) !SelectItem {
        const source_schema = self.joined_source_schema orelse self.schema;
        const previous_schema = self.schema;
        const previous_field_expression_qualifiers = self.field_expression_qualifiers;
        const previous_returning_expression_qualifiers = self.returning_expression_qualifiers;
        const previous_field_source_override = self.row_expression_field_source_override;
        const source_qualifiers = [_][]const u8{source_alias};
        self.schema = source_schema;
        self.field_expression_qualifiers = source_qualifiers[0..];
        self.returning_expression_qualifiers = source_qualifiers[0..];
        self.row_expression_field_source_override = .source;
        defer {
            self.schema = previous_schema;
            self.field_expression_qualifiers = previous_field_expression_qualifiers;
            self.returning_expression_qualifiers = previous_returning_expression_qualifiers;
            self.row_expression_field_source_override = previous_field_source_override;
        }
        return try self.parseSelectItem();
    }

    fn normalizeReturningFieldAlloc(
        self: *@This(),
        field: []const u8,
        returning_qualifiers: []const []const u8,
    ) ![]const u8 {
        if (relationalColumnForReturningField(self.schema, field) != null) {
            return try self.alloc.dupe(u8, field);
        }

        var dot: ?usize = std.mem.indexOfScalar(u8, field, '.');
        while (dot) |index| {
            if (index > 0 and index + 1 < field.len) {
                const qualifier = field[0..index];
                const unqualified_field = field[index + 1 ..];
                if (try self.returningQualifierMatches(qualifier, returning_qualifiers)) {
                    if (relationalColumnForReturningField(self.schema, unqualified_field) == null) return error.InvalidSqlCatalog;
                    return try self.alloc.dupe(u8, unqualified_field);
                }
            }
            dot = std.mem.indexOfScalarPos(u8, field, index + 1, '.');
        }

        return error.InvalidSqlCatalog;
    }

    fn matchQualifiedReturningAll(
        self: *@This(),
        returning_qualifiers: []const []const u8,
    ) !bool {
        if (!self.peekKind(.identifier) or self.pos + 1 >= self.tokens.len) return false;
        const token = self.tokens[self.pos];
        if (!std.mem.endsWith(u8, token.text, ".")) return false;
        if (self.tokens[self.pos + 1].kind != .star) return false;
        const qualifier = token.text[0 .. token.text.len - 1];
        if (qualifier.len == 0) return error.UnsupportedSqlShape;
        if (!try self.returningQualifierMatches(qualifier, returning_qualifiers)) return error.InvalidSqlCatalog;
        self.pos += 2;
        return true;
    }

    fn returningQualifierMatches(
        self: *@This(),
        qualifier: []const u8,
        returning_qualifiers: []const []const u8,
    ) !bool {
        for (returning_qualifiers) |expected| {
            if (std.mem.eql(u8, qualifier, expected)) return true;
        }
        const normalized = try normalizeSqlObjectIdentifierAlloc(self.alloc, qualifier);
        defer self.alloc.free(normalized);
        for (returning_qualifiers) |expected| {
            if (std.mem.eql(u8, normalized, expected)) return true;
        }
        return false;
    }

    fn validateReturningProjectionOutputs(
        schema: runtime_schema.TableSchema,
        fields: []const []const u8,
        expressions: []const db_mod.types.RelationalRowsExpressionProjection,
    ) !void {
        const returning_all = fields.len == 1 and std.mem.eql(u8, fields[0], "*");
        if (returning_all) {
            for (expressions) |projection| {
                if (projection.output.len == 0) return error.UnsupportedSqlShape;
                if (relationalColumnForReturningField(schema, projection.output) != null) return error.UnsupportedSqlShape;
                if (returningExpressionOutputCount(expressions, projection.output) > 1) return error.UnsupportedSqlShape;
            }
            return;
        }
        for (fields) |field| {
            if (field.len == 0 or std.mem.eql(u8, field, "*")) return error.UnsupportedSqlShape;
            if (returningFieldOutputCount(fields, field) > 1) return error.UnsupportedSqlShape;
            if (returningExpressionOutputCount(expressions, field) > 0) return error.UnsupportedSqlShape;
        }
        for (expressions) |projection| {
            if (projection.output.len == 0) return error.UnsupportedSqlShape;
            if (returningExpressionOutputCount(expressions, projection.output) > 1) return error.UnsupportedSqlShape;
            if (returningFieldOutputCount(fields, projection.output) > 0) return error.UnsupportedSqlShape;
        }
    }

    fn returningFieldOutputCount(fields: []const []const u8, output: []const u8) usize {
        var count: usize = 0;
        for (fields) |field| {
            if (std.mem.eql(u8, field, output)) count += 1;
        }
        return count;
    }

    fn returningExpressionOutputCount(expressions: []const db_mod.types.RelationalRowsExpressionProjection, output: []const u8) usize {
        var count: usize = 0;
        for (expressions) |projection| {
            if (std.mem.eql(u8, projection.output, output)) count += 1;
        }
        return count;
    }

    fn peekSimpleReturningField(self: *@This()) bool {
        if (!self.peekKind(.identifier)) return false;
        if (self.peekKeyword("lower") or self.peekKeyword("upper") or self.peekKeyword("trim") or self.peekKeyword("replace") or self.peekKeyword("concat") or self.peekKeyword("coalesce") or self.peekKeyword("nullif") or self.peekLengthFunctionKeyword() or self.peekKeyword("abs") or self.peekKeyword("round") or self.peekFunctionCall("floor") or self.peekFunctionCall("ceil") or self.peekKeyword("case") or self.peekKeyword("cast")) return false;
        if (self.pos + 1 >= self.tokens.len) return true;
        return switch (self.tokens[self.pos + 1].kind) {
            .plus, .minus, .star, .slash, .lparen, .arrow_json, .arrow_text, .pipe_concat => false,
            else => true,
        };
    }

    fn nextRowExpressionHasTopLevelPipeConcat(self: *@This()) bool {
        var depth: usize = 0;
        var i = self.pos;
        while (i < self.tokens.len) : (i += 1) {
            const token = self.tokens[i];
            switch (token.kind) {
                .lparen => depth += 1,
                .rparen => {
                    if (depth == 0) return false;
                    depth -= 1;
                },
                .pipe_concat => if (depth == 0) return true,
                .comma, .semicolon, .eq, .neq, .lt, .lte, .gt, .gte, .at_contains, .question, .arrow_json, .arrow_text => if (depth == 0) return false,
                .identifier => if (depth == 0 and rowExpressionBoundaryKeyword(token.text)) return false,
                else => {},
            }
        }
        return false;
    }

    fn insertBodyJsonAlloc(self: *@This(), columns: []const []const u8, rows: InsertValueRows, conflicts: []const ConflictClause, returning: ReturningProjection) ![]u8 {
        if (rows.len == 0) return error.UnsupportedSqlShape;
        if (conflicts.len != 0 and conflicts.len != rows.len) return error.UnsupportedSqlShape;
        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.writeAll("{\"operations\":[");
        for (rows, 0..) |values, row_i| {
            if (values.len != columns.len) return error.UnsupportedSqlShape;
            if (row_i != 0) try writer.writeByte(',');
            try writer.writeAll("{\"op\":\"insert\",\"row\":{");
            for (columns, values, 0..) |column, value_json, i| {
                if (i != 0) try writer.writeByte(',');
                try writer.print("{f}:", .{std.json.fmt(column, .{})});
                try writer.writeAll(value_json);
            }
            try writer.writeByte('}');
            if (conflicts.len != 0) {
                const clause = conflicts[row_i];
                try writer.writeAll(",\"on_conflict\":{\"target\":");
                try self.writeConflictTargetJson(writer, clause.target);
                try writer.print(",\"action\":{f}", .{std.json.fmt(conflictActionToken(clause.action), .{})});
                if (clause.patch.len > 0) {
                    try writer.writeAll(",\"patch\":{");
                    for (clause.patch, 0..) |item, i| {
                        if (i != 0) try writer.writeByte(',');
                        try writer.print("{f}:", .{std.json.fmt(item.field, .{})});
                        try writer.writeAll(item.value_json);
                    }
                    try writer.writeByte('}');
                }
                if (clause.patch_expr.len > 0) {
                    try writer.writeAll(",\"patch_expr\":{");
                    for (clause.patch_expr, 0..) |item, i| {
                        if (i != 0) try writer.writeByte(',');
                        try writer.print("{f}:", .{std.json.fmt(item.field, .{})});
                        try writeRowExpressionJson(writer, item.expression);
                    }
                    try writer.writeByte('}');
                }
                if (clause.increment.len > 0) {
                    try writer.writeAll(",\"increment\":{");
                    for (clause.increment, 0..) |item, i| {
                        if (i != 0) try writer.writeByte(',');
                        try writer.print("{f}:", .{std.json.fmt(item.field, .{})});
                        try writer.writeAll(item.value_json);
                    }
                    try writer.writeByte('}');
                }
                if (clause.increment_expr.len > 0) {
                    try writer.writeAll(",\"increment_expr\":{");
                    for (clause.increment_expr, 0..) |item, i| {
                        if (i != 0) try writer.writeByte(',');
                        try writer.print("{f}:", .{std.json.fmt(item.field, .{})});
                        try writeRowExpressionJson(writer, item.expression);
                    }
                    try writer.writeByte('}');
                }
                if (clause.json_set.len > 0) {
                    try writeJsonSetValuesJson(writer, clause.json_set);
                }
                if (clause.array_update.len > 0) {
                    try writer.writeAll(",\"array_update\":[");
                    for (clause.array_update, 0..) |item, i| {
                        if (i != 0) try writer.writeByte(',');
                        try writer.print("{{\"field\":{f},\"op\":{f},\"value\":", .{
                            std.json.fmt(item.field, .{}),
                            std.json.fmt(arrayTransformOpToken(item.op), .{}),
                        });
                        try writer.writeAll(item.value_json);
                        try writer.writeByte('}');
                    }
                    try writer.writeByte(']');
                }
                if (clause.where_expression) |condition| {
                    try writer.writeAll(",\"where_expression\":");
                    try writeRowExpressionConditionJson(writer, condition);
                }
                try writer.writeByte('}');
            }
            try self.writeReturningProjectionJson(writer, returning);
            try writer.writeByte('}');
        }
        try writer.writeAll("]}");
        return try out.toOwnedSlice();
    }

    fn writeConflictTargetJson(self: *@This(), writer: *std.Io.Writer, target: ConflictTarget) !void {
        _ = self;
        switch (target) {
            .primary => try writer.writeAll("{\"primary\":true}"),
            .unique => |unique| {
                try writer.print("{{\"unique\":{{\"name\":{f}", .{std.json.fmt(unique.name, .{})});
                if (unique.where_json.len > 0) {
                    try writer.writeAll(",\"where\":");
                    try writer.writeAll(unique.where_json);
                }
                try writer.writeAll("}}");
            },
        }
    }

    fn parseU32Value(self: *@This()) !u32 {
        if (self.match(.number)) |token| {
            return try std.fmt.parseInt(u32, token.text, 10);
        }
        if (self.match(.placeholder)) |token| {
            const value = try self.boundValue(token);
            return try value.asU32();
        }
        return error.UnsupportedSqlShape;
    }

    fn parseLimitValue(self: *@This()) !?u32 {
        if (self.matchKeyword("all")) return null;
        return try self.parseU32Value();
    }

    fn parseOffsetValue(self: *@This()) !u32 {
        const offset = try self.parseU32Value();
        _ = self.matchKeyword("row") or self.matchKeyword("rows");
        return offset;
    }

    fn parseFetchLimitValue(self: *@This()) !?u32 {
        if (!(self.matchKeyword("first") or self.matchKeyword("next"))) return error.UnsupportedSqlShape;
        const limit: ?u32 = if (self.peekKeyword("row") or self.peekKeyword("rows"))
            1
        else
            try self.parseLimitValue();
        if (!(self.matchKeyword("row") or self.matchKeyword("rows"))) return error.UnsupportedSqlShape;
        try self.expectKeyword("only");
        return limit;
    }

    fn parseSelectItem(self: *@This()) !SelectItem {
        if (self.nextRowExpressionHasTopLevelPipeConcat()) return .{ .expression = try self.parseTextExpressionProjectionAlloc() };
        if (self.peekKind(.minus)) return .{ .expression = try self.parseGenericExpressionProjectionAlloc() };
        if (self.peekKeyword("now") or self.peekKeyword("current_timestamp")) return .{ .expression = try self.parseNowExpressionProjectionAlloc() };
        if (self.peekKeyword("array_length")) return .{ .expression = try self.parseArrayLengthExpressionProjectionAlloc() };
        if (self.peekKeyword("string_to_array")) return .{ .expression = try self.parseStringToArrayExpressionProjectionAlloc() };
        if (self.peekKeyword("coalesce")) return .{ .expression = try self.parseCoalesceExpressionProjectionAlloc() };
        if (self.peekKeyword("lower") or self.peekKeyword("upper") or self.peekKeyword("trim")) return .{ .expression = try self.parseCaseFoldExpressionProjectionAlloc() };
        if (self.peekKeyword("replace")) return .{ .expression = try self.parseReplaceExpressionProjectionAlloc() };
        if (self.peekKeyword("concat")) return .{ .expression = try self.parseConcatExpressionProjectionAlloc() };
        if (self.peekKeyword("nullif")) return .{ .expression = try self.parseNullifExpressionProjectionAlloc() };
        if (self.peekLengthFunctionKeyword()) return .{ .expression = try self.parseLengthExpressionProjectionAlloc() };
        if (self.peekKeyword("abs")) return .{ .expression = try self.parseAbsExpressionProjectionAlloc() };
        if (self.peekKeyword("round")) return .{ .expression = try self.parseRoundExpressionProjectionAlloc() };
        if (self.peekFunctionCall("floor")) return .{ .expression = try self.parseFloorCeilExpressionProjectionAlloc(.floor) };
        if (self.peekFunctionCall("ceil")) return .{ .expression = try self.parseFloorCeilExpressionProjectionAlloc(.ceil) };
        if (self.peekKeyword("greatest") or self.peekKeyword("least")) return .{ .expression = try self.parseGreatestLeastExpressionProjectionAlloc() };
        if (self.peekKeyword("case")) return .{ .expression = try self.parseCaseExpressionProjectionAlloc() };
        if (self.peekKeyword("cast")) return .{ .expression = try self.parseCastExpressionProjectionAlloc() };
        if (self.peekKind(.lparen)) {
            if (self.peekParenthesizedNullTestProjection()) {
                return .{ .expression = try self.parseParenthesizedNullTestExpressionProjectionAlloc() };
            }
            return .{ .expression = try self.parseParenthesizedExpressionProjectionAlloc() };
        }

        const parsed_field = try self.parseFieldExpressionOwned();
        defer self.alloc.free(parsed_field);
        const field = try self.normalizeRowExpressionFieldAlloc(parsed_field);
        var field_owned = true;
        errdefer if (field_owned) self.alloc.free(field);
        if (self.peekKind(.lparen)) return error.UnsupportedSqlShape;
        if (self.peekKind(.arrow_text) or self.peekKind(.arrow_json)) {
            const as_text = self.match(.arrow_text) != null;
            if (!as_text) try self.expect(.arrow_json);
            if (relationalColumnForField(self.schema, field, .json) == null) return error.InvalidSqlCatalog;
            const path = try self.parseJsonPathOwned();
            var path_owned = true;
            errdefer if (path_owned) self.alloc.free(path);
            const output = if (self.matchKeyword("as"))
                try self.parseIdentifierOwned()
            else
                try self.alloc.dupe(u8, path);
            var output_owned = true;
            errdefer if (output_owned) self.alloc.free(output);
            const operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
            var operands_owned = true;
            errdefer if (operands_owned) self.alloc.free(operands);
            operands[0] = .{ .kind = .field, .field = field, .field_source = self.rowExpressionFieldSource() };
            field_owned = false;
            path_owned = false;
            output_owned = false;
            operands_owned = false;
            return .{ .expression = .{
                .output = output,
                .expression = .{
                    .kind = .json_extract,
                    .json_path = path,
                    .json_as_text = as_text,
                    .operands = operands,
                },
            } };
        }
        const column = relationalColumnForField(self.schema, field, null) orelse return error.InvalidSqlCatalog;
        if (self.peekArithmeticOperator()) |_| {
            if (column.field_type != .numeric and column.field_type != .datetime) return error.InvalidSqlCatalog;
            field_owned = false;
            return .{ .expression = try self.parseArithmeticExpressionProjectionFromFieldAlloc(field) };
        }
        const alias = try self.parseOptionalProjectionAliasAlloc();
        var alias_transferred = false;
        errdefer if (!alias_transferred) if (alias) |owned| self.alloc.free(owned);
        if (alias) |output| {
            if (!std.mem.eql(u8, output, field)) {
                alias_transferred = true;
                field_owned = false;
                return .{ .expression = .{
                    .output = output,
                    .expression = .{
                        .kind = .field,
                        .field = field,
                        .field_source = self.rowExpressionFieldSource(),
                    },
                } };
            }
            self.alloc.free(output);
            alias_transferred = true;
        }
        field_owned = false;
        return .{ .field = field };
    }

    fn parseTextExpressionProjectionAlloc(self: *@This()) !db_mod.types.RelationalRowsExpressionProjection {
        const expression = try self.parseRowExpressionAlloc();
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(self.alloc, expression);
        try self.validateTextRowExpression(expression);
        const output = if (self.matchKeyword("as"))
            try self.parseIdentifierOwned()
        else
            try self.alloc.dupe(u8, rowExpressionOpName(expression.kind));
        var output_transferred = false;
        errdefer if (!output_transferred) self.alloc.free(output);

        expression_transferred = true;
        output_transferred = true;
        return .{
            .output = output,
            .expression = expression,
        };
    }

    fn parseGenericExpressionProjectionAlloc(self: *@This()) !db_mod.types.RelationalRowsExpressionProjection {
        const expression = try self.parseRowExpressionAlloc();
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(self.alloc, expression);
        try self.validateNumericRowExpression(expression);
        const output = if (self.matchKeyword("as"))
            try self.parseIdentifierOwned()
        else
            try self.alloc.dupe(u8, rowExpressionOpName(expression.kind));
        var output_transferred = false;
        errdefer if (!output_transferred) self.alloc.free(output);
        expression_transferred = true;
        output_transferred = true;
        return .{
            .output = output,
            .expression = expression,
        };
    }

    fn parseParenthesizedNullTestExpressionProjectionAlloc(self: *@This()) !db_mod.types.RelationalRowsExpressionProjection {
        try self.expect(.lparen);
        const field = try self.parseFieldExpressionOwned();
        var field_transferred = false;
        errdefer if (!field_transferred) self.alloc.free(field);
        if (relationalColumnForField(self.schema, field, null) == null) return error.InvalidSqlCatalog;
        try self.expectKeyword("is");
        const op: runtime_schema.RelationalCheckOp = if (self.matchKeyword("not")) blk: {
            try self.expectKeyword("null");
            break :blk .is_not_null;
        } else blk: {
            try self.expectKeyword("null");
            break :blk .is_null;
        };
        try self.expect(.rparen);

        const output = if (self.matchKeyword("as"))
            try self.parseIdentifierOwned()
        else
            try self.alloc.dupe(u8, if (op == .is_not_null) "is_not_null" else "is_null");
        var output_transferred = false;
        errdefer if (!output_transferred) self.alloc.free(output);

        const true_json = try self.alloc.dupe(u8, "true");
        var true_transferred = false;
        errdefer if (!true_transferred) self.alloc.free(true_json);
        const false_json = try self.alloc.dupe(u8, "false");
        var false_transferred = false;
        errdefer if (!false_transferred) self.alloc.free(false_json);
        const branches = try self.alloc.alloc(db_mod.types.RelationalRowsExpressionCaseBranch, 1);
        var branches_transferred = false;
        errdefer if (!branches_transferred) self.alloc.free(branches);
        const fallback = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
        var fallback_transferred = false;
        errdefer if (!fallback_transferred) self.alloc.free(fallback);

        branches[0] = .{
            .when = .{
                .lhs = .{ .kind = .field, .field = field, .field_source = self.rowExpressionFieldSource() },
                .op = op,
            },
            .then = .{ .kind = .value, .value_json = true_json },
        };
        fallback[0] = .{ .kind = .value, .value_json = false_json };
        field_transferred = true;
        true_transferred = true;
        false_transferred = true;
        branches_transferred = true;
        fallback_transferred = true;

        const expression: db_mod.types.RelationalRowsExpression = .{
            .kind = .case,
            .case_branches = branches,
            .case_else = fallback,
        };
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(self.alloc, expression);
        output_transferred = true;
        expression_transferred = true;
        return .{
            .output = output,
            .expression = expression,
        };
    }

    fn peekParenthesizedNullTestProjection(self: *@This()) bool {
        if (self.pos + 2 >= self.tokens.len) return false;
        return self.tokens[self.pos].kind == .lparen and
            self.tokens[self.pos + 1].kind == .identifier and
            self.tokens[self.pos + 2].kind == .identifier and
            std.ascii.eqlIgnoreCase(self.tokens[self.pos + 2].text, "is");
    }

    fn parseParenthesizedExpressionProjectionAlloc(self: *@This()) !db_mod.types.RelationalRowsExpressionProjection {
        const expression = try self.parseParenthesizedRowExpressionAlloc();
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(self.alloc, expression);
        const output = if (self.matchKeyword("as"))
            try self.parseIdentifierOwned()
        else
            try self.alloc.dupe(u8, rowExpressionDefaultOutputName(expression.kind));
        var output_transferred = false;
        errdefer if (!output_transferred) self.alloc.free(output);

        expression_transferred = true;
        output_transferred = true;
        return .{
            .output = output,
            .expression = expression,
        };
    }

    fn parseNowExpressionProjectionAlloc(self: *@This()) !db_mod.types.RelationalRowsExpressionProjection {
        const expression = try self.parseNowRowExpressionAlloc();
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(self.alloc, expression);
        const output = if (self.matchKeyword("as"))
            try self.parseIdentifierOwned()
        else
            try self.alloc.dupe(u8, "now");
        var output_transferred = false;
        errdefer if (!output_transferred) self.alloc.free(output);
        expression_transferred = true;
        output_transferred = true;
        return .{
            .output = output,
            .expression = expression,
        };
    }

    fn parseArithmeticExpressionProjectionFromFieldAlloc(
        self: *@This(),
        lhs_field: []const u8,
    ) !db_mod.types.RelationalRowsExpressionProjection {
        var current: db_mod.types.RelationalRowsExpression = .{
            .kind = .field,
            .field = lhs_field,
            .field_source = self.rowExpressionFieldSource(),
        };
        var current_owned = true;
        errdefer if (current_owned) freeExpression(self.alloc, current);

        current_owned = false;
        current = try self.parseArithmeticExpressionRestAlloc(current, 0);
        current_owned = true;
        try self.validateNumericRowExpression(current);

        const output = if (self.matchKeyword("as"))
            try self.parseIdentifierOwned()
        else
            try self.alloc.dupe(u8, switch (current.kind) {
                .add => "add",
                .sub => "sub",
                .mul => "mul",
                .div => "div",
                else => "expr",
            });
        var output_owned = true;
        errdefer if (output_owned) self.alloc.free(output);

        current_owned = false;
        output_owned = false;
        return .{
            .output = output,
            .expression = current,
        };
    }

    const ArithmeticOperator = struct {
        token: TokenKind,
        kind: db_mod.types.RelationalRowsExpressionKind,
        precedence: u8,
    };

    fn peekArithmeticOperator(self: *@This()) ?ArithmeticOperator {
        if (self.peekKind(.plus)) return .{ .token = .plus, .kind = .add, .precedence = 1 };
        if (self.peekKind(.minus)) return .{ .token = .minus, .kind = .sub, .precedence = 1 };
        if (self.peekKind(.star)) return .{ .token = .star, .kind = .mul, .precedence = 2 };
        if (self.peekKind(.slash)) return .{ .token = .slash, .kind = .div, .precedence = 2 };
        return null;
    }

    fn parseArithmeticExpressionRestAlloc(
        self: *@This(),
        lhs: db_mod.types.RelationalRowsExpression,
        min_precedence: u8,
    ) anyerror!db_mod.types.RelationalRowsExpression {
        var current = lhs;
        var current_owned = true;
        errdefer if (current_owned) freeExpression(self.alloc, current);

        while (self.peekArithmeticOperator()) |op| {
            if (op.precedence < min_precedence) break;
            _ = self.match(op.token) orelse unreachable;
            var rhs = try self.parseRowExpressionOperandAlloc();
            var rhs_owned = true;
            errdefer if (rhs_owned) freeExpression(self.alloc, rhs);
            try self.validateNumericRowExpression(rhs);

            while (self.peekArithmeticOperator()) |next_op| {
                if (next_op.precedence <= op.precedence) break;
                rhs_owned = false;
                rhs = try self.parseArithmeticExpressionRestAlloc(rhs, next_op.precedence);
                rhs_owned = true;
            }

            const operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 2);
            var operands_owned = true;
            errdefer if (operands_owned) self.alloc.free(operands);
            operands[0] = current;
            operands[1] = rhs;
            current_owned = false;
            rhs_owned = false;
            operands_owned = false;
            current = .{
                .kind = op.kind,
                .operands = operands,
            };
            current_owned = true;
        }

        current_owned = false;
        return current;
    }

    fn validateNumericRowExpression(self: *@This(), expression: db_mod.types.RelationalRowsExpression) anyerror!void {
        switch (expression.kind) {
            .field => {
                const column = relationalColumnForField(self.schemaForRowExpressionField(expression), expression.field, null) orelse return error.InvalidSqlCatalog;
                if (column.field_type != .numeric) return error.InvalidSqlCatalog;
            },
            .value => {
                var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, expression.value_json, .{}) catch return error.UnsupportedSqlShape;
                defer parsed.deinit();
                switch (parsed.value) {
                    .null, .integer, .float, .number_string => {},
                    else => return error.UnsupportedSqlShape,
                }
            },
            .now => {},
            .coalesce => {
                if (expression.operands.len == 0) return error.UnsupportedSqlShape;
                for (expression.operands) |operand| try self.validateNumericRowExpression(operand);
            },
            .nullif => {
                if (expression.operands.len != 2) return error.UnsupportedSqlShape;
                for (expression.operands) |operand| try self.validateNumericRowExpression(operand);
            },
            .length => {
                if (expression.operands.len != 1) return error.UnsupportedSqlShape;
                try self.validateTextRowExpression(expression.operands[0]);
            },
            .greatest, .least => {
                if (expression.operands.len == 0) return error.UnsupportedSqlShape;
                for (expression.operands) |operand| try self.validateNumericRowExpression(operand);
            },
            .abs, .round, .floor, .ceil => {
                if (expression.operands.len != 1) return error.UnsupportedSqlShape;
                try self.validateNumericRowExpression(expression.operands[0]);
            },
            .add => {
                if (expression.operands.len < 2) return error.UnsupportedSqlShape;
                if (@This().sqlExpressionContainsInterval(expression)) {
                    if (expression.operands.len != 2) return error.UnsupportedSqlShape;
                    const lhs_interval = expression.operands[0].kind == .interval_ns;
                    const rhs_interval = expression.operands[1].kind == .interval_ns;
                    if (lhs_interval == rhs_interval) return error.UnsupportedSqlShape;
                    if (lhs_interval) {
                        try self.validateIntervalRowExpression(expression.operands[0]);
                        try self.validateNumericOrDatetimeRowExpression(expression.operands[1]);
                    } else {
                        try self.validateNumericOrDatetimeRowExpression(expression.operands[0]);
                        try self.validateIntervalRowExpression(expression.operands[1]);
                    }
                    return;
                }
                for (expression.operands) |operand| try self.validateNumericRowExpression(operand);
            },
            .mul => {
                if (expression.operands.len < 2) return error.UnsupportedSqlShape;
                if (@This().sqlExpressionContainsInterval(expression)) return error.UnsupportedSqlShape;
                for (expression.operands) |operand| try self.validateNumericRowExpression(operand);
            },
            .sub => {
                if (expression.operands.len != 2) return error.UnsupportedSqlShape;
                if (@This().sqlExpressionContainsInterval(expression)) {
                    if (expression.operands[0].kind == .interval_ns or expression.operands[1].kind != .interval_ns) return error.UnsupportedSqlShape;
                    try self.validateNumericOrDatetimeRowExpression(expression.operands[0]);
                    try self.validateIntervalRowExpression(expression.operands[1]);
                    return;
                }
                for (expression.operands) |operand| try self.validateNumericRowExpression(operand);
            },
            .div => {
                if (expression.operands.len != 2) return error.UnsupportedSqlShape;
                if (@This().sqlExpressionContainsInterval(expression)) return error.UnsupportedSqlShape;
                for (expression.operands) |operand| try self.validateNumericRowExpression(operand);
            },
            .case => {
                if (expression.case_branches.len == 0 or expression.case_else.len != 1) return error.UnsupportedSqlShape;
                for (expression.case_branches) |branch| try self.validateNumericRowExpression(branch.then);
                try self.validateNumericRowExpression(expression.case_else[0]);
            },
            .cast => {
                if (expression.operands.len != 1 or expression.cast_type != .numeric) return error.UnsupportedSqlShape;
            },
            .array_length => {
                if (expression.operands.len != 1) return error.UnsupportedSqlShape;
            },
            .interval_ns => try self.validateIntervalRowExpression(expression),
            else => return error.UnsupportedSqlShape,
        }
    }

    fn schemaForRowExpressionField(
        self: *@This(),
        expression: db_mod.types.RelationalRowsExpression,
    ) runtime_schema.TableSchema {
        if (expression.field_source == .source) return self.joined_source_schema orelse self.schema;
        return self.schema;
    }

    fn sqlExpressionContainsInterval(expression: db_mod.types.RelationalRowsExpression) bool {
        if (expression.kind == .interval_ns) return true;
        for (expression.operands) |operand| {
            if (sqlExpressionContainsInterval(operand)) return true;
        }
        return false;
    }

    fn validateIntervalRowExpression(self: *@This(), expression: db_mod.types.RelationalRowsExpression) anyerror!void {
        if (expression.kind != .interval_ns or expression.operands.len != 1) return error.UnsupportedSqlShape;
        if (@This().sqlExpressionContainsInterval(expression.operands[0])) return error.UnsupportedSqlShape;
        try self.validateNumericRowExpression(expression.operands[0]);
    }

    fn validateNumericOrDatetimeRowExpression(self: *@This(), expression: db_mod.types.RelationalRowsExpression) anyerror!void {
        switch (expression.kind) {
            .field => {
                const column = relationalColumnForField(self.schemaForRowExpressionField(expression), expression.field, null) orelse return error.InvalidSqlCatalog;
                if (column.field_type != .numeric and column.field_type != .datetime) return error.InvalidSqlCatalog;
            },
            .now => {},
            else => try self.validateNumericRowExpression(expression),
        }
    }

    fn rowExpressionOutputType(self: *@This(), expression: db_mod.types.RelationalRowsExpression) !runtime_schema.AntflyType {
        switch (expression.kind) {
            .field => {
                const column = relationalColumnForField(self.schemaForRowExpressionField(expression), expression.field, null) orelse return error.InvalidSqlCatalog;
                return column.field_type;
            },
            .value => {
                var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, expression.value_json, .{}) catch return error.UnsupportedSqlShape;
                defer parsed.deinit();
                return switch (parsed.value) {
                    .integer, .float, .number_string => .numeric,
                    .string => .keyword,
                    .bool => .boolean,
                    .array => .array,
                    .object, .null => .json,
                };
            },
            .now => return .datetime,
            .lower, .upper, .trim, .replace, .concat => return .keyword,
            .nullif => {
                if (expression.operands.len != 2) return error.UnsupportedSqlShape;
                return try self.rowExpressionOutputType(expression.operands[0]);
            },
            .length, .abs, .round, .floor, .ceil, .mul, .div, .array_length, .interval_ns => return .numeric,
            .add, .sub => {
                if (expression.operands.len > 0 and @This().sqlExpressionContainsInterval(expression)) {
                    return try self.rowExpressionOutputType(expression.operands[0]);
                }
                return .numeric;
            },
            .coalesce, .greatest, .least => {
                if (expression.operands.len == 0) return error.UnsupportedSqlShape;
                return try self.expressionOperandOutputType(expression.operands);
            },
            .case => {
                return try self.caseExpressionOutputType(expression.case_branches, expression.case_else);
            },
            .cast => return switch (expression.cast_type orelse return error.UnsupportedSqlShape) {
                .text => .keyword,
                .numeric => .numeric,
                .bool => .boolean,
            },
            .json_extract => return if (expression.json_as_text) .keyword else .json,
            .string_to_array => return .array,
        }
    }

    fn expressionOperandOutputType(
        self: *@This(),
        operands: []const db_mod.types.RelationalRowsExpression,
    ) anyerror!runtime_schema.AntflyType {
        if (operands.len == 0) return error.UnsupportedSqlShape;
        for (operands) |operand| {
            if (try self.rowExpressionIsNullLiteral(operand)) continue;
            return try self.rowExpressionOutputType(operand);
        }
        return .json;
    }

    fn caseExpressionOutputType(
        self: *@This(),
        branches: []const db_mod.types.RelationalRowsExpressionCaseBranch,
        fallback: []const db_mod.types.RelationalRowsExpression,
    ) anyerror!runtime_schema.AntflyType {
        if (branches.len == 0 or fallback.len != 1) return error.UnsupportedSqlShape;
        var result_type: ?runtime_schema.AntflyType = null;
        for (branches) |branch| {
            try self.mergeCaseExpressionArmType(branch.then, &result_type);
        }
        try self.mergeCaseExpressionArmType(fallback[0], &result_type);
        return result_type orelse .json;
    }

    fn mergeCaseExpressionArmType(
        self: *@This(),
        expression: db_mod.types.RelationalRowsExpression,
        result_type: *?runtime_schema.AntflyType,
    ) anyerror!void {
        if (try self.rowExpressionIsNullLiteral(expression)) return;
        const arm_type = try self.rowExpressionOutputType(expression);
        if (result_type.*) |existing| {
            if (!sqlExpressionResultTypesCompatible(existing, arm_type)) return error.UnsupportedSqlShape;
        } else {
            result_type.* = arm_type;
        }
    }

    fn sqlExpressionResultTypesCompatible(lhs: runtime_schema.AntflyType, rhs: runtime_schema.AntflyType) bool {
        return sqlExpressionTypesComparable(lhs, rhs);
    }

    fn validateExpressionOperandDomains(
        self: *@This(),
        expression: db_mod.types.RelationalRowsExpression,
    ) anyerror!void {
        switch (expression.kind) {
            .coalesce => {
                if (expression.operands.len == 0) return error.UnsupportedSqlShape;
                try self.validateExpressionSameDomainOperands(expression.operands, false);
            },
            .nullif => {
                if (expression.operands.len != 2) return error.UnsupportedSqlShape;
                try self.validateExpressionSameDomainOperands(expression.operands, false);
            },
            .greatest, .least => {
                if (expression.operands.len == 0) return error.UnsupportedSqlShape;
                try self.validateExpressionSameDomainOperands(expression.operands, true);
            },
            else => return error.UnsupportedSqlShape,
        }
    }

    fn validateExpressionSameDomainOperands(
        self: *@This(),
        operands: []const db_mod.types.RelationalRowsExpression,
        require_orderable: bool,
    ) anyerror!void {
        var result_type: ?runtime_schema.AntflyType = null;
        for (operands) |operand| {
            if (try self.rowExpressionIsNullLiteral(operand)) continue;
            const operand_type = try self.rowExpressionOutputType(operand);
            if (result_type) |existing| {
                if (!sqlExpressionResultTypesCompatible(existing, operand_type)) return error.UnsupportedSqlShape;
            } else {
                result_type = operand_type;
            }
        }
        if (require_orderable) {
            const operand_type = result_type orelse return;
            if (!sqlExpressionTypeIsOrderable(operand_type)) return error.UnsupportedSqlShape;
        }
    }

    fn validateTextRowExpression(self: *@This(), expression: db_mod.types.RelationalRowsExpression) !void {
        switch (expression.kind) {
            .field => {
                const column = relationalColumnForField(self.schemaForRowExpressionField(expression), expression.field, null) orelse return error.InvalidSqlCatalog;
                if (column.field_type != .keyword and column.field_type != .text and column.field_type != .link) return error.InvalidSqlCatalog;
            },
            .value => {
                var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, expression.value_json, .{}) catch return error.UnsupportedSqlShape;
                defer parsed.deinit();
                switch (parsed.value) {
                    .null, .string => {},
                    else => return error.UnsupportedSqlShape,
                }
            },
            .coalesce => {
                if (expression.operands.len == 0) return error.UnsupportedSqlShape;
                for (expression.operands) |operand| try self.validateTextRowExpression(operand);
            },
            .lower, .upper, .trim => {
                if (expression.operands.len != 1) return error.UnsupportedSqlShape;
                try self.validateTextRowExpression(expression.operands[0]);
            },
            .replace => {
                if (expression.operands.len != 3) return error.UnsupportedSqlShape;
                for (expression.operands) |operand| try self.validateTextRowExpression(operand);
            },
            .concat => {
                if (expression.operands.len == 0) return error.UnsupportedSqlShape;
            },
            .nullif => {
                if (expression.operands.len != 2) return error.UnsupportedSqlShape;
                for (expression.operands) |operand| try self.validateTextRowExpression(operand);
            },
            .case => {
                if (expression.case_branches.len == 0 or expression.case_else.len != 1) return error.UnsupportedSqlShape;
                for (expression.case_branches) |branch| try self.validateTextRowExpression(branch.then);
                try self.validateTextRowExpression(expression.case_else[0]);
            },
            .cast => {
                if (expression.operands.len != 1 or expression.cast_type != .text) return error.UnsupportedSqlShape;
            },
            .json_extract => {
                if (expression.operands.len != 1 or !expression.json_as_text) return error.UnsupportedSqlShape;
            },
            else => return error.UnsupportedSqlShape,
        }
    }

    fn validateStringToArrayExpression(self: *@This(), expression: db_mod.types.RelationalRowsExpression) anyerror!void {
        if (expression.kind != .string_to_array or expression.operands.len != 2) return error.UnsupportedSqlShape;
        try self.validateTextRowExpression(expression.operands[0]);
        try self.validateTextRowExpression(expression.operands[1]);
        try self.validateStringToArrayDelimiterLiteral(expression.operands[1]);
    }

    fn validateStringToArrayDelimiterLiteral(self: *@This(), expression: db_mod.types.RelationalRowsExpression) anyerror!void {
        if (expression.kind != .value) return;
        var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, expression.value_json, .{}) catch return error.UnsupportedSqlShape;
        defer parsed.deinit();
        switch (parsed.value) {
            .null => {},
            .string => |delimiter| if (delimiter.len == 0) return error.UnsupportedSqlShape,
            else => return error.UnsupportedSqlShape,
        }
    }

