    fn parseReplaceRowExpressionAlloc(self: *@This()) !db_mod.types.RelationalRowsExpression {
        try self.expectKeyword("replace");
        try self.expect(.lparen);
        const operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 3);
        var initialized: usize = 0;
        errdefer {
            for (operands[0..initialized]) |operand| freeExpression(self.alloc, operand);
            self.alloc.free(operands);
        }
        while (initialized < operands.len) {
            operands[initialized] = try self.parseRowExpressionAlloc();
            try self.validateTextRowExpression(operands[initialized]);
            initialized += 1;
            if (initialized < operands.len) try self.expect(.comma);
        }
        try self.expect(.rparen);
        return .{
            .kind = .replace,
            .operands = operands,
        };
    }

    fn parseConcatExpressionProjectionAlloc(self: *@This()) !db_mod.types.RelationalRowsExpressionProjection {
        try self.expectKeyword("concat");
        try self.expect(.lparen);

        var operands = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpression).empty;
        errdefer {
            for (operands.items) |operand| freeExpression(self.alloc, operand);
            operands.deinit(self.alloc);
