    fn parseRowExpressionAlloc(self: *@This()) anyerror!db_mod.types.RelationalRowsExpression {
        var expression = try self.parseRowExpressionOperandAlloc();
        var expression_owned = true;
        errdefer if (expression_owned) freeExpression(self.alloc, expression);
        if (self.peekArithmeticOperator()) |_| {
            try self.validateNumericOrDatetimeRowExpression(expression);
            expression_owned = false;
            expression = try self.parseArithmeticExpressionRestAlloc(expression, 0);
            expression_owned = true;
            try self.validateNumericRowExpression(expression);
        }
        if (self.peekKind(.pipe_concat)) {
            expression_owned = false;
            expression = try self.parsePipeConcatExpressionRestAlloc(expression);
            expression_owned = true;
        }
        expression_owned = false;
        return expression;
    }

    fn parsePipeConcatExpressionRestAlloc(
        self: *@This(),
        left: db_mod.types.RelationalRowsExpression,
    ) anyerror!db_mod.types.RelationalRowsExpression {
        try self.validateTextRowExpression(left);
        var operands = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpression).empty;
        errdefer {
            for (operands.items) |operand| freeExpression(self.alloc, operand);
            operands.deinit(self.alloc);
        }
        try operands.append(self.alloc, left);
        while (self.match(.pipe_concat) != null) {
            const rhs = try self.parseRowExpressionOperandAlloc();
            var rhs_transferred = false;
            errdefer if (!rhs_transferred) freeExpression(self.alloc, rhs);
            try self.validateTextRowExpression(rhs);
            try operands.append(self.alloc, rhs);
            rhs_transferred = true;
        }
        if (operands.items.len < 2) return error.UnsupportedSqlShape;
        return .{
            .kind = .concat,
            .operands = try operands.toOwnedSlice(self.alloc),
        };
    }

    fn parseRowExpressionOperandAlloc(self: *@This()) anyerror!db_mod.types.RelationalRowsExpression {
        if (self.peekKind(.lparen)) {
            return try self.parseParenthesizedRowExpressionAlloc();
        }
        if (self.peekKind(.minus)) {
            return try self.parseUnaryNegativeRowExpressionAlloc();
        }
        if (self.peekKeyword("cast")) {
            return try self.parseCastRowExpressionAlloc();
        }
        if (self.peekKeyword("case")) {
            return try self.parseCaseRowExpressionAlloc();
        }
        if (self.peekKeyword("now") or self.peekKeyword("current_timestamp")) {
            return try self.parseNowRowExpressionAlloc();
        }
        if (self.peekKeyword("interval")) {
            return try self.parseIntervalRowExpressionAlloc();
        }
        if (self.peekKeyword("lower") or self.peekKeyword("upper") or self.peekKeyword("trim")) {
            return try self.parseCaseFoldRowExpressionAlloc();
        }
        if (self.peekKeyword("replace")) {
            return try self.parseReplaceRowExpressionAlloc();
        }
        if (self.peekKeyword("concat")) {
            return try self.parseConcatRowExpressionAlloc();
        }
        if (self.peekKeyword("coalesce")) {
            return try self.parseCoalesceRowExpressionAlloc();
        }
        if (self.peekKeyword("nullif")) {
            return try self.parseNullifRowExpressionAlloc();
        }
        if (self.peekLengthFunctionKeyword()) {
            return try self.parseLengthRowExpressionAlloc();
        }
        if (self.peekKeyword("abs")) {
            return try self.parseAbsRowExpressionAlloc();
        }
        if (self.peekKeyword("round")) {
            return try self.parseRoundRowExpressionAlloc();
        }
        if (self.peekFunctionCall("floor")) {
            return try self.parseFloorCeilRowExpressionAlloc(.floor);
        }
        if (self.peekFunctionCall("ceil")) {
            return try self.parseFloorCeilRowExpressionAlloc(.ceil);
        }
        if (self.peekKeyword("greatest") or self.peekKeyword("least")) {
            return try self.parseGreatestLeastRowExpressionAlloc();
        }
        if (self.peekKeyword("array_length")) {
            return try self.parseArrayLengthRowExpressionAlloc();
        }
        if (self.peekKeyword("string_to_array")) {
            return try self.parseStringToArrayRowExpressionAlloc();
        }
        if (self.peekKind(.identifier) and
            !self.peekKeyword("null") and
            !self.peekKeyword("true") and
            !self.peekKeyword("false"))
        {
            const parsed_field = try self.parseFieldExpressionOwned();
            defer self.alloc.free(parsed_field);
            const resolved = try self.resolveRowExpressionFieldAlloc(parsed_field);
            var field_transferred = false;
            errdefer if (!field_transferred) self.alloc.free(resolved.field);
            if (self.peekKind(.lparen)) return error.UnsupportedSqlShape;
            if (self.peekKind(.arrow_text) or self.peekKind(.arrow_json)) {
                const as_text = self.match(.arrow_text) != null;
                if (!as_text) try self.expect(.arrow_json);
                if (relationalColumnForField(resolved.schema, resolved.field, .json) == null) return error.InvalidSqlCatalog;
                const path = try self.parseJsonPathOwned();
                var path_transferred = false;
                errdefer if (!path_transferred) self.alloc.free(path);
                const operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
                var operands_transferred = false;
                errdefer if (!operands_transferred) self.alloc.free(operands);
                operands[0] = .{ .kind = .field, .field = resolved.field, .field_source = resolved.source };
                field_transferred = true;
                path_transferred = true;
                operands_transferred = true;
                return .{
                    .kind = .json_extract,
                    .json_path = path,
                    .json_as_text = as_text,
                    .operands = operands,
                };
            }
            if (relationalColumnForField(resolved.schema, resolved.field, null) == null) return error.InvalidSqlCatalog;
            field_transferred = true;
            return .{ .kind = .field, .field = resolved.field, .field_source = resolved.source };
        }

        const value_json = try self.parseJsonValueAlloc();
        errdefer self.alloc.free(value_json);
        return .{ .kind = .value, .value_json = value_json };
    }

    fn normalizeRowExpressionFieldAlloc(self: *@This(), field: []const u8) ![]const u8 {
        const qualifiers = if (self.field_expression_qualifiers.len != 0)
            self.field_expression_qualifiers
        else
            self.returning_expression_qualifiers;
        if (qualifiers.len == 0) {
            return try self.alloc.dupe(u8, field);
        }
        return try self.normalizeReturningFieldAlloc(field, qualifiers);
    }

    const ResolvedRowExpressionField = struct {
        field: []const u8,
        source: db_mod.types.RelationalRowsExpressionFieldSource,
        schema: runtime_schema.TableSchema,
    };

    fn resolveRowExpressionFieldAlloc(self: *@This(), field: []const u8) !ResolvedRowExpressionField {
        if (self.joined_source_expression_qualifiers.len != 0) {
            if (try self.normalizeQualifiedRowExpressionFieldAlloc(field, self.joined_source_expression_qualifiers, self.joined_source_schema orelse self.schema)) |source_field| {
                return .{
                    .field = source_field,
                    .source = .source,
                    .schema = self.joined_source_schema orelse self.schema,
                };
            }
        }
        if (self.joined_target_expression_qualifiers.len != 0) {
            if (try self.normalizeQualifiedRowExpressionFieldAlloc(field, self.joined_target_expression_qualifiers, self.schema)) |target_field| {
                return .{
                    .field = target_field,
                    .source = .row,
                    .schema = self.schema,
                };
            }
        }
        return .{
            .field = try self.normalizeRowExpressionFieldAlloc(field),
            .source = self.rowExpressionFieldSource(),
            .schema = if (self.rowExpressionFieldSource() == .source) self.joined_source_schema orelse self.schema else self.schema,
        };
    }

    fn normalizeQualifiedRowExpressionFieldAlloc(
        self: *@This(),
        field: []const u8,
        qualifiers: []const []const u8,
        schema: runtime_schema.TableSchema,
    ) !?[]const u8 {
        var dot: ?usize = std.mem.indexOfScalar(u8, field, '.');
        while (dot) |index| {
            if (index > 0 and index + 1 < field.len) {
                const qualifier = field[0..index];
                const unqualified_field = field[index + 1 ..];
                if (try self.returningQualifierMatches(qualifier, qualifiers)) {
                    if (relationalColumnForReturningField(schema, unqualified_field) == null) return error.InvalidSqlCatalog;
                    return try self.alloc.dupe(u8, unqualified_field);
                }
            }
            dot = std.mem.indexOfScalarPos(u8, field, index + 1, '.');
        }
        return null;
    }

    fn rowExpressionFieldSource(self: *@This()) db_mod.types.RelationalRowsExpressionFieldSource {
        return self.row_expression_field_source_override orelse .row;
    }

    fn parseParenthesizedRowExpressionAlloc(self: *@This()) anyerror!db_mod.types.RelationalRowsExpression {
        try self.expect(.lparen);
        const expression = try self.parseRowExpressionAlloc();
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeExpression(self.alloc, expression);
        try self.expect(.rparen);
        expression_transferred = true;
        return expression;
    }

    fn parseUnaryNegativeRowExpressionAlloc(self: *@This()) anyerror!db_mod.types.RelationalRowsExpression {
        _ = self.match(.minus) orelse return error.UnsupportedSqlShape;
        if (self.match(.number)) |token| {
            return .{
                .kind = .value,
                .value_json = try std.fmt.allocPrint(self.alloc, "-{s}", .{token.text}),
            };
        }

        const operand = try self.parseRowExpressionOperandAlloc();
        var operand_transferred = false;
        errdefer if (!operand_transferred) freeExpression(self.alloc, operand);
        const negative_one = try self.alloc.dupe(u8, "-1");
        var negative_one_transferred = false;
        errdefer if (!negative_one_transferred) self.alloc.free(negative_one);
        const operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 2);
        var operands_transferred = false;
        errdefer if (!operands_transferred) self.alloc.free(operands);
        operands[0] = .{ .kind = .value, .value_json = negative_one };
        operands[1] = operand;
        negative_one_transferred = true;
        operand_transferred = true;
        operands_transferred = true;
        return .{
            .kind = .mul,
            .operands = operands,
        };
    }

    fn parseNowRowExpressionAlloc(self: *@This()) !db_mod.types.RelationalRowsExpression {
        if (self.matchKeyword("now")) {
            try self.expect(.lparen);
            try self.expect(.rparen);
        } else if (self.matchKeyword("current_timestamp")) {
            if (self.match(.lparen) != null) try self.expect(.rparen);
        } else {
            return error.UnsupportedSqlShape;
        }
        return .{
            .kind = .now,
            .value_json = try std.fmt.allocPrint(self.alloc, "{d}", .{platform_time.realtimeNs()}),
        };
    }

    fn parseIntervalRowExpressionAlloc(self: *@This()) !db_mod.types.RelationalRowsExpression {
        try self.expectKeyword("interval");
        const token = self.match(.string) orelse return error.UnsupportedSqlShape;
        const interval_ns = try sqlIntervalLiteralNs(token.text);
        const value_json = try std.fmt.allocPrint(self.alloc, "{d}", .{interval_ns});
        var value_transferred = false;
        errdefer if (!value_transferred) self.alloc.free(value_json);
        const operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
        var operands_transferred = false;
        errdefer if (!operands_transferred) self.alloc.free(operands);
        operands[0] = .{ .kind = .value, .value_json = value_json };
        value_transferred = true;
        operands_transferred = true;
        return .{
            .kind = .interval_ns,
            .operands = operands,
        };
    }

    fn parseCastRowExpressionAlloc(self: *@This()) anyerror!db_mod.types.RelationalRowsExpression {
        try self.expectKeyword("cast");
        try self.expect(.lparen);
        const operand = try self.parseRowExpressionOperandAlloc();
        var operand_transferred = false;
        errdefer if (!operand_transferred) freeExpression(self.alloc, operand);
        try self.expectKeyword("as");
        const cast_type = try self.parseExpressionCastType();
        try self.expect(.rparen);

        const operands = try self.alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
        var operands_transferred = false;
        errdefer if (!operands_transferred) self.alloc.free(operands);
        operands[0] = operand;

        operand_transferred = true;
        operands_transferred = true;
        return .{
            .kind = .cast,
            .operands = operands,
            .cast_type = cast_type,
