    fn parseFieldExpressionOwned(self: *@This()) ![]const u8 {
        if ((self.peekKeyword("lower") or self.peekKeyword("upper")) and self.pos + 1 < self.tokens.len and self.tokens[self.pos + 1].kind == .lparen) {
            const op: runtime_schema.RelationalGeneratedOp = if (self.peekKeyword("lower")) .lower else .upper;
            self.pos += 1;
            try self.expect(.lparen);
            const parsed_source = try self.parseIdentifierOwned();
            defer self.alloc.free(parsed_source);
            const source = try self.normalizeRowExpressionFieldAlloc(parsed_source);
            defer self.alloc.free(source);
            if (relationalColumnForField(self.schema, source, null) == null) return error.InvalidSqlCatalog;
            try self.expect(.rparen);
            const generated = generatedCaseFoldColumnForField(self.schema, op, source) orelse return error.UnsupportedSqlShape;
            return try self.alloc.dupe(u8, generated.name);
        }
        if (self.peekKeyword("concat") and self.pos + 1 < self.tokens.len and self.tokens[self.pos + 1].kind == .lparen) {
            const generated = (try self.generatedConcatColumnAtCurrent()) orelse return error.UnsupportedSqlShape;
            self.pos += 2;
            for (generated.generated.?.fields, 0..) |field, i| {
                const parsed_source = try self.parseIdentifierOwned();
                defer self.alloc.free(parsed_source);
                const source = try self.normalizeRowExpressionFieldAlloc(parsed_source);
                defer self.alloc.free(source);
                if (!std.mem.eql(u8, source, field)) return error.UnsupportedSqlShape;
                if (i + 1 < generated.generated.?.fields.len) {
                    try self.expect(.comma);
                    const separator = self.match(.string) orelse return error.UnsupportedSqlShape;
                    if (!std.mem.eql(u8, separator.text, generated.generated.?.separator)) return error.UnsupportedSqlShape;
                    try self.expect(.comma);
                }
            }
            try self.expect(.rparen);
            return try self.alloc.dupe(u8, generated.name);
        }
        return try self.parseIdentifierOwned();
    }

    fn generatedConcatColumnAtCurrent(self: *@This()) !?runtime_schema.RelationalColumn {
        for (self.schema.relational_columns) |column| {
            const generated = column.generated orelse continue;
            if (generated.op != .concat) continue;
            if (try self.concatCallMatchesGeneratedAtCurrent(generated)) return column;
        }
        return null;
    }

    fn concatCallMatchesGeneratedAtCurrent(
        self: *@This(),
        generated: runtime_schema.RelationalGeneratedValue,
    ) !bool {
        if (generated.fields.len == 0) return false;
        if (self.pos + 2 >= self.tokens.len) return false;
        if (self.tokens[self.pos].kind != .identifier or !std.ascii.eqlIgnoreCase(self.tokens[self.pos].text, "concat")) return false;
        if (self.tokens[self.pos + 1].kind != .lparen) return false;
        var i: usize = self.pos + 2;
        for (generated.fields, 0..) |field, field_index| {
            if (i >= self.tokens.len or self.tokens[i].kind != .identifier) return false;
            const normalized_field = try self.normalizeRowExpressionFieldAlloc(self.tokens[i].text);
            defer self.alloc.free(normalized_field);
            if (!std.mem.eql(u8, normalized_field, field)) return false;
            i += 1;
            if (field_index + 1 < generated.fields.len) {
                if (i >= self.tokens.len or self.tokens[i].kind != .comma) return false;
                i += 1;
                if (i >= self.tokens.len or self.tokens[i].kind != .string) return false;
                if (!std.mem.eql(u8, self.tokens[i].text, generated.separator)) return false;
                i += 1;
                if (i >= self.tokens.len or self.tokens[i].kind != .comma) return false;
                i += 1;
            }
        }
        return i < self.tokens.len and self.tokens[i].kind == .rparen;
    }

