    var rename_unique_constraint = try lowerDdlPlanAlloc(alloc, "ALTER TABLE usage_records RENAME CONSTRAINT usage_records_tenant_status_key TO usage_records_tenant_state_key;");
    defer rename_unique_constraint.deinit(alloc);
