test "postgres sql adapter lowers boolean is predicates" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"customer":{"type":"keyword"},"status":{"type":"keyword"},"enabled":{"type":"boolean"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var true_lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE enabled IS TRUE ORDER BY id",
        schema,
        &.{},
    );
    defer true_lowered.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), true_lowered.query.predicates.len);
    try std.testing.expectEqualStrings("enabled", true_lowered.query.predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.eq, true_lowered.query.predicates[0].op);
    try std.testing.expectEqualStrings("true", true_lowered.query.predicates[0].value_json.?);

    var false_lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE enabled IS FALSE ORDER BY id",
        schema,
        &.{},
    );
    defer false_lowered.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), false_lowered.query.predicates.len);
    try std.testing.expectEqualStrings("enabled", false_lowered.query.predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.eq, false_lowered.query.predicates[0].op);
    try std.testing.expectEqualStrings("false", false_lowered.query.predicates[0].value_json.?);

    var unknown_lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE enabled IS UNKNOWN ORDER BY id",
        schema,
        &.{},
    );
    defer unknown_lowered.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), unknown_lowered.query.predicates.len);
    try std.testing.expectEqualStrings("enabled", unknown_lowered.query.predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.is_null, unknown_lowered.query.predicates[0].op);
    try std.testing.expect(unknown_lowered.query.predicates[0].value_json == null);

    var not_unknown_lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE enabled IS NOT UNKNOWN ORDER BY id",
        schema,
        &.{},
    );
    defer not_unknown_lowered.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), not_unknown_lowered.query.predicates.len);
    try std.testing.expectEqualStrings("enabled", not_unknown_lowered.query.predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.is_not_null, not_unknown_lowered.query.predicates[0].op);
    try std.testing.expect(not_unknown_lowered.query.predicates[0].value_json == null);

    var aggregate_filter = try lowerAggregateAlloc(
        alloc,
        "SELECT customer, COUNT(*) FILTER (WHERE enabled IS TRUE) AS enabled_count FROM usage_records GROUP BY customer",
        schema,
        &.{},
    );
    defer aggregate_filter.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), aggregate_filter.aggregate.aggregations.len);
    try std.testing.expectEqual(@as(usize, 1), aggregate_filter.aggregate.aggregations[0].filter_predicates.len);
    try std.testing.expectEqualStrings("enabled", aggregate_filter.aggregate.aggregations[0].filter_predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.eq, aggregate_filter.aggregate.aggregations[0].filter_predicates[0].op);
    try std.testing.expectEqualStrings("true", aggregate_filter.aggregate.aggregations[0].filter_predicates[0].value_json.?);

    var aggregate_unknown_filter = try lowerAggregateAlloc(
        alloc,
        "SELECT customer, COUNT(*) FILTER (WHERE enabled IS UNKNOWN) AS unknown_count FROM usage_records GROUP BY customer",
        schema,
        &.{},
    );
    defer aggregate_unknown_filter.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), aggregate_unknown_filter.aggregate.aggregations[0].filter_predicates.len);
    try std.testing.expectEqualStrings("enabled", aggregate_unknown_filter.aggregate.aggregations[0].filter_predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.is_null, aggregate_unknown_filter.aggregate.aggregations[0].filter_predicates[0].op);
    try std.testing.expect(aggregate_unknown_filter.aggregate.aggregations[0].filter_predicates[0].value_json == null);

    var aggregate_not_unknown_filter = try lowerAggregateAlloc(
        alloc,
        "SELECT customer, COUNT(*) FILTER (WHERE enabled IS NOT UNKNOWN OR status = 'queued') AS known_or_queued_count FROM usage_records GROUP BY customer",
        schema,
        &.{},
    );
    defer aggregate_not_unknown_filter.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 2), aggregate_not_unknown_filter.aggregate.aggregations[0].filter_any.len);
    try std.testing.expectEqualStrings("enabled", aggregate_not_unknown_filter.aggregate.aggregations[0].filter_any[0].conditions[0].lhs.field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.is_not_null, aggregate_not_unknown_filter.aggregate.aggregations[0].filter_any[0].conditions[0].op);
    try std.testing.expectEqual(@as(usize, 0), aggregate_not_unknown_filter.aggregate.aggregations[0].filter_any[0].conditions[0].rhs.len);
    try std.testing.expectEqualStrings("status", aggregate_not_unknown_filter.aggregate.aggregations[0].filter_any[1].conditions[0].lhs.field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.eq, aggregate_not_unknown_filter.aggregate.aggregations[0].filter_any[1].conditions[0].op);

    var not_true_lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE enabled IS NOT TRUE ORDER BY id",
        schema,
        &.{},
    );
    defer not_true_lowered.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 0), not_true_lowered.query.predicates.len);
    try std.testing.expectEqual(@as(usize, 2), not_true_lowered.query.or_predicates.len);
    try std.testing.expectEqual(@as(usize, 1), not_true_lowered.query.or_predicates[0].predicates.len);
    try std.testing.expectEqualStrings("enabled", not_true_lowered.query.or_predicates[0].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.ne, not_true_lowered.query.or_predicates[0].predicates[0].op);
    try std.testing.expectEqualStrings("true", not_true_lowered.query.or_predicates[0].predicates[0].value_json.?);
    try std.testing.expectEqualStrings("enabled", not_true_lowered.query.or_predicates[1].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.is_null, not_true_lowered.query.or_predicates[1].predicates[0].op);
    try std.testing.expect(not_true_lowered.query.or_predicates[1].predicates[0].value_json == null);

    var not_false_or_lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE enabled IS NOT FALSE OR status = 'queued' ORDER BY id",
        schema,
        &.{},
    );
    defer not_false_or_lowered.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 3), not_false_or_lowered.query.or_predicates.len);
    try std.testing.expectEqualStrings("enabled", not_false_or_lowered.query.or_predicates[0].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.ne, not_false_or_lowered.query.or_predicates[0].predicates[0].op);
    try std.testing.expectEqualStrings("false", not_false_or_lowered.query.or_predicates[0].predicates[0].value_json.?);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.is_null, not_false_or_lowered.query.or_predicates[1].predicates[0].op);
    try std.testing.expectEqualStrings("status", not_false_or_lowered.query.or_predicates[2].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.eq, not_false_or_lowered.query.or_predicates[2].predicates[0].op);
    try std.testing.expectEqualStrings("\"queued\"", not_false_or_lowered.query.or_predicates[2].predicates[0].value_json.?);

    try std.testing.expectError(error.InvalidSqlCatalog, lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status IS TRUE",
        schema,
        &.{},
    ));
    try std.testing.expectError(error.InvalidSqlCatalog, lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status IS UNKNOWN",
        schema,
        &.{},
    ));
}

test "postgres sql adapter lowers text pattern predicates" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"name":{"type":"text"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE name ILIKE $1 AND name NOT LIKE 'bot%'",
        schema,
        &.{.{ .string = "a%" }},
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 2), lowered.query.text_patterns.len);
    try std.testing.expectEqualStrings("name", lowered.query.text_patterns[0].field);
    try std.testing.expectEqualStrings("a%", lowered.query.text_patterns[0].pattern);
    try std.testing.expect(lowered.query.text_patterns[0].case_insensitive);
    try std.testing.expect(!lowered.query.text_patterns[0].negated);
    try std.testing.expectEqualStrings("bot%", lowered.query.text_patterns[1].pattern);
    try std.testing.expect(!lowered.query.text_patterns[1].case_insensitive);
    try std.testing.expect(lowered.query.text_patterns[1].negated);
}

