    try std.testing.expectEqualStrings("status", not_in_lowered.query.or_predicates[0].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.ne, not_in_lowered.query.or_predicates[0].predicates[0].op);
    try std.testing.expectEqualStrings("\"closed\"", not_in_lowered.query.or_predicates[0].predicates[0].value_json.?);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.ne, not_in_lowered.query.or_predicates[0].predicates[1].op);
    try std.testing.expectEqualStrings("\"pending\"", not_in_lowered.query.or_predicates[0].predicates[1].value_json.?);
    try std.testing.expectEqualStrings("amount", not_in_lowered.query.or_predicates[0].predicates[2].field);
    try std.testing.expectEqual(@as(usize, 1), not_in_lowered.query.or_predicates[1].predicates.len);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status NOT IN ('closed', NULL) OR status = 'open'",
        schema,
        &.{},
