fn expectOptionalUsize(expected: ?usize, actual: usize) !void {
    if (expected) |value| try std.testing.expectEqual(value, actual);
}

fn expectOptionalU32(expected: ?u32, actual: ?u32) !void {
    if (expected) |value| try std.testing.expectEqual(value, actual orelse return error.TestUnexpectedResult);
}

fn expectOptionalTableName(expected: ?[]const u8, actual: []const u8) !void {
    if (expected) |value| try std.testing.expectEqualStrings(value, actual);
}

fn expectAppParityPlan(expected: []const u8, actual: []const u8) !void {
    if (expected.len == 0) return;
    try std.testing.expectEqualStrings(expected, actual);
}

fn expectAppParityReturningRows(expected: []const []const u8, actual: []const []const u8) !void {
    if (expected.len == 0) return;
    try std.testing.expectEqual(expected.len, actual.len);
    for (expected, actual) |expected_row, actual_row| {
        try std.testing.expectEqualStrings(expected_row, actual_row);
    }
}

fn unsupportedFingerprintAlloc(
    alloc: std.mem.Allocator,
    family: []const u8,
    reason: []const u8,
) ![]u8 {
    if (reason.len == 0) return error.TestUnexpectedResult;
    return try std.fmt.allocPrint(alloc, "unsupported:{s}:requires={s}", .{ family, reason });
}

fn adapterNoopFingerprintAlloc(
    alloc: std.mem.Allocator,
    family: []const u8,
    reason: []const u8,
) ![]u8 {
    if (reason.len == 0) return error.TestUnexpectedResult;
    return try std.fmt.allocPrint(alloc, "adapter_noop:{s}:reason={s}", .{ family, reason });
}

fn expectFailClosedUnsupported(result: anytype) !void {
    if (result) |_| {
        return error.TestExpectedError;
    } else |err| switch (err) {
        error.UnsupportedSqlShape, error.InvalidSqlCatalog => return,
        else => return err,
    }
}

fn appParityLimitValue(limit: ?u32) i64 {
    return if (limit) |value| @intCast(value) else -1;
}

fn freeInsertValueRows(alloc: std.mem.Allocator, rows: InsertValueRows) void {
    for (rows) |row| {
        for (row) |value| alloc.free(value);
        alloc.free(row);
    }
}

fn appParityBoolValue(value: bool) u8 {
    return if (value) 1 else 0;
}

fn appParityGeneratedExpressionCount(plan: CreateIndexPlan) usize {
    return if (plan.generated_expression != null) 1 else 0;
}

fn appendNonZeroU32FingerprintAlloc(
    alloc: std.mem.Allocator,
    owned_base: []u8,
    label: []const u8,
    value: u32,
) ![]u8 {
    if (value == 0) return owned_base;
    errdefer alloc.free(owned_base);
    const out = try std.fmt.allocPrint(alloc, "{s}:{s}={d}", .{ owned_base, label, value });
    alloc.free(owned_base);
    return out;
}

fn appendNonZeroUsizeFingerprintAlloc(
    alloc: std.mem.Allocator,
    owned_base: []u8,
    label: []const u8,
    value: usize,
) ![]u8 {
    if (value == 0) return owned_base;
    errdefer alloc.free(owned_base);
    const out = try std.fmt.allocPrint(alloc, "{s}:{s}={d}", .{ owned_base, label, value });
    alloc.free(owned_base);
    return out;
}

fn appendNamedNonZeroUsizeFingerprintAlloc(
    alloc: std.mem.Allocator,
    owned_base: []u8,
    prefix: []const u8,
    label: []const u8,
    value: usize,
) ![]u8 {
    if (value == 0) return owned_base;
    errdefer alloc.free(owned_base);
    const out = try std.fmt.allocPrint(alloc, "{s}:{s}_{s}={d}", .{ owned_base, prefix, label, value });
    alloc.free(owned_base);
    return out;
}

fn appendTrueBoolFingerprintAlloc(
    alloc: std.mem.Allocator,
    owned_base: []u8,
    label: []const u8,
    value: bool,
) ![]u8 {
    if (!value) return owned_base;
    errdefer alloc.free(owned_base);
    const out = try std.fmt.allocPrint(alloc, "{s}:{s}=1", .{ owned_base, label });
    alloc.free(owned_base);
    return out;
}

fn expressionOrderCount(order_by: []const db_mod.types.RelationalRowsQueryOrder) usize {
    var count: usize = 0;
    for (order_by) |order| {
        if (order.expression != null) count += 1;
    }
    return count;
}

fn aggregateFilterExpressionCount(aggregations: []const db_mod.types.RelationalRowsAggregateSpec) usize {
    var count: usize = 0;
    for (aggregations) |aggregation| {
        count += aggregation.filter_expressions.len;
    }
    return count;
}

fn aggregateFilterExpressionArrayCount(aggregations: []const db_mod.types.RelationalRowsAggregateSpec) usize {
    var count: usize = 0;
    for (aggregations) |aggregation| {
        count += aggregation.filter_expression_array_contains.len;
    }
    return count;
}

fn aggregateFilterJsonAccessCount(aggregations: []const db_mod.types.RelationalRowsAggregateSpec) usize {
    var count: usize = 0;
    for (aggregations) |aggregation| {
        count += aggregation.filter_json_contains.len +
            aggregation.filter_json_path_eq.len +
            aggregation.filter_json_path_exists.len;
    }
    return count;
}

fn aggregateFilterStructuredAccessCount(aggregations: []const db_mod.types.RelationalRowsAggregateSpec) usize {
    var count: usize = 0;
    for (aggregations) |aggregation| {
        count += aggregation.filter_array_any.len +
            aggregation.filter_array_contains.len +
            aggregation.filter_array_eq.len +
            aggregation.filter_in_predicates.len +
            aggregation.filter_text_patterns.len;
    }
    return count;
}

fn aggregateFilterGroupCount(aggregations: []const db_mod.types.RelationalRowsAggregateSpec) usize {
    var count: usize = 0;
    for (aggregations) |aggregation| {
        count += aggregation.filter_any.len + aggregation.filter_not.len;
    }
    return count;
}

fn aggregateInputExpressionCount(aggregations: []const db_mod.types.RelationalRowsAggregateSpec) usize {
    var count: usize = 0;
    for (aggregations) |aggregation| {
        if (aggregation.expression != null) count += 1;
    }
    return count;
}

fn windowValueExpressionCount(windows: []const db_mod.types.RelationalRowsWindowSpec) usize {
    var count: usize = 0;
    for (windows) |window| {
        if (window.value_expression != null) count += 1;
    }
    return count;
}

fn windowDefaultCount(windows: []const db_mod.types.RelationalRowsWindowSpec) usize {
    var count: usize = 0;
    for (windows) |window| {
        if (window.default_json.len > 0) count += 1;
    }
    return count;
}

fn windowFrameSignature(windows: []const db_mod.types.RelationalRowsWindowSpec) u64 {
    var signature: u64 = 0;
    for (windows) |window| {
        if (window.frame) |frame| {
            signature = signature *% 131 +% 17;
            signature = signature *% 131 +% windowFrameUnitCode(frame.unit);
            signature = signature *% 131 +% windowFrameBoundCode(frame.start);
            signature = signature *% 131 +% @as(u64, @intCast(frame.start_offset));
            signature = signature *% 131 +% windowFrameBoundCode(frame.end);
            signature = signature *% 131 +% @as(u64, @intCast(frame.end_offset));
        } else {
            signature = signature *% 131;
        }
    }
    return signature;
}

fn windowFrameUnitCode(unit: db_mod.types.RelationalRowsWindowFrameUnit) u64 {
    return switch (unit) {
        .rows => 1,
        .range => 2,
    };
}

fn windowFrameBoundCode(bound: db_mod.types.RelationalRowsWindowFrameBound) u64 {
    return switch (bound) {
        .unbounded_preceding => 1,
        .offset_preceding => 2,
        .current_row => 3,
        .offset_following => 4,
        .unbounded_following => 5,
    };
}

fn queryFingerprintAlloc(alloc: std.mem.Allocator, family: []const u8, table_name: []const u8, query: db_mod.types.RelationalRowsQueryRequest, ctes: usize) ![]u8 {
    const claim = if (query.row_claim) |claim_value| if (claim_value.skip_locked) "skip_locked" else "locked" else "none";
    const order_expr = expressionOrderCount(query.order_by);
    if (query.distinct_on.len > 0) {
        return try std.fmt.allocPrint(
            alloc,
            "{s}:table={s}:ctes={d}:pred={d}:expr_pred={d}:json_eq={d}:or={d}:not={d}:select={d}:expr={d}:alias={d}:distinct_on={d}:order={d}:order_expr={d}:limit={d}:claim={s}",
            .{
                family,
                table_name,
                ctes,
                query.predicates.len,
                query.expression_predicates.len,
                query.json_path_eq.len,
                query.or_predicates.len,
                query.not_predicates.len,
                query.select.len,
                query.expressions.len,
                query.field_aliases.len,
                query.distinct_on.len,
                query.order_by.len,
                order_expr,
                appParityLimitValue(query.limit),
                claim,
            },
        );
    }
    if (ctes > 0 or query.source_cte.len > 0) {
        return try std.fmt.allocPrint(
            alloc,
            "{s}:table={s}:ctes={d}:source_cte={d}:pred={d}:array_any={d}:expr_pred={d}:expr_or={d}:expr_not={d}:expr_array={d}:json_eq={d}:or={d}:not={d}:select={d}:expr={d}:alias={d}:order={d}:order_expr={d}:limit={d}:claim={s}",
            .{
                family,
                table_name,
                ctes,
                @as(u8, if (query.source_cte.len > 0) 1 else 0),
                query.predicates.len,
                query.array_any.len,
                query.expression_predicates.len,
                query.expression_or_predicates.len,
                query.expression_not_predicates.len,
                query.expression_array_contains.len,
                query.json_path_eq.len,
                query.or_predicates.len,
                query.not_predicates.len,
                query.select.len,
                query.expressions.len,
                query.field_aliases.len,
                query.order_by.len,
                order_expr,
                appParityLimitValue(query.limit),
                claim,
            },
        );
    }
    if (query.array_any.len > 0 or query.expression_or_predicates.len > 0 or query.expression_not_predicates.len > 0) {
        return try std.fmt.allocPrint(
            alloc,
            "{s}:table={s}:ctes={d}:pred={d}:array_any={d}:expr_pred={d}:expr_or={d}:expr_not={d}:expr_array={d}:json_eq={d}:or={d}:not={d}:select={d}:expr={d}:alias={d}:order={d}:order_expr={d}:limit={d}:claim={s}",
            .{
                family,
                table_name,
                ctes,
                query.predicates.len,
                query.array_any.len,
                query.expression_predicates.len,
                query.expression_or_predicates.len,
                query.expression_not_predicates.len,
                query.expression_array_contains.len,
                query.json_path_eq.len,
                query.or_predicates.len,
                query.not_predicates.len,
                query.select.len,
                query.expressions.len,
                query.field_aliases.len,
                query.order_by.len,
                order_expr,
                appParityLimitValue(query.limit),
                claim,
            },
        );
    }
    if (query.expression_array_contains.len > 0) {
        if (query.limit) |limit| {
            return try std.fmt.allocPrint(
                alloc,
