fn appendCteAccessPathFingerprintAlloc(
    alloc: std.mem.Allocator,
    owned_base: []u8,
    ctes: []const db_mod.types.RelationalRowsCte,
) ![]u8 {
    var fingerprint = owned_base;
    for (ctes, 0..) |cte, i| {
        const prefix = try std.fmt.allocPrint(alloc, "cte{d}", .{i});
        defer alloc.free(prefix);
        fingerprint = try appendNamedNonZeroUsizeFingerprintAlloc(alloc, fingerprint, prefix, "array_any", cte.query.array_any.len);
        fingerprint = try appendNamedNonZeroUsizeFingerprintAlloc(alloc, fingerprint, prefix, "in", cte.query.in_predicates.len);
        fingerprint = try appendNamedNonZeroUsizeFingerprintAlloc(alloc, fingerprint, prefix, "json_eq", cte.query.json_path_eq.len);
        fingerprint = try appendNamedNonZeroUsizeFingerprintAlloc(alloc, fingerprint, prefix, "json_contains", cte.query.json_contains.len);
        fingerprint = try appendNamedNonZeroUsizeFingerprintAlloc(alloc, fingerprint, prefix, "json_exists", cte.query.json_path_exists.len);
        fingerprint = try appendNamedNonZeroUsizeFingerprintAlloc(alloc, fingerprint, prefix, "array_contains", cte.query.array_contains.len);
        fingerprint = try appendNamedNonZeroUsizeFingerprintAlloc(alloc, fingerprint, prefix, "array_eq", cte.query.array_eq.len);
        fingerprint = try appendNamedNonZeroUsizeFingerprintAlloc(alloc, fingerprint, prefix, "text_pattern", cte.query.text_patterns.len);
        fingerprint = try appendNamedNonZeroUsizeFingerprintAlloc(alloc, fingerprint, prefix, "access_or", cte.query.access_or_predicates.len);
        fingerprint = try appendNamedNonZeroUsizeFingerprintAlloc(alloc, fingerprint, prefix, "access_not", cte.query.access_not_predicates.len);
        fingerprint = try appendNamedNonZeroUsizeFingerprintAlloc(alloc, fingerprint, prefix, "expr_pred", cte.query.expression_predicates.len);
        fingerprint = try appendNamedNonZeroUsizeFingerprintAlloc(alloc, fingerprint, prefix, "expr_or", cte.query.expression_or_predicates.len);
        fingerprint = try appendNamedNonZeroUsizeFingerprintAlloc(alloc, fingerprint, prefix, "expr_not", cte.query.expression_not_predicates.len);
        fingerprint = try appendNamedNonZeroUsizeFingerprintAlloc(alloc, fingerprint, prefix, "expr_array", cte.query.expression_array_contains.len);
    }
    return fingerprint;
}

fn ddlFingerprintAlloc(alloc: std.mem.Allocator, lowered: LoweredDdlPlan) ![]u8 {
    return switch (lowered) {
        .create_table => |plan| if (plan.replace_existing)
            try std.fmt.allocPrint(
                alloc,
                "ddl:create_table:table={s}:columns={d}:unique={d}:fk={d}:checks={d}:if_not_exists={}:replace=true",
                .{ plan.table_name, plan.columns.len, plan.unique_constraints.len, plan.foreign_keys.len, plan.checks.len, plan.if_not_exists },
            )
        else
            try std.fmt.allocPrint(
                alloc,
                "ddl:create_table:table={s}:columns={d}:unique={d}:fk={d}:checks={d}:if_not_exists={}",
                .{ plan.table_name, plan.columns.len, plan.unique_constraints.len, plan.foreign_keys.len, plan.checks.len, plan.if_not_exists },
            ),
        .create_index => |plan| if (plan.method == .gin)
            try std.fmt.allocPrint(
                alloc,
                "ddl:create_index:table={s}:columns={d}:expr={d}:generated_expr={d}:where={d}:unique={}:if_not_exists={}:method=gin",
                .{ plan.table_name, plan.columns.len, plan.expressions.len, appParityGeneratedExpressionCount(plan), plan.where.len, plan.unique, plan.if_not_exists },
            )
        else
            try std.fmt.allocPrint(
                alloc,
                "ddl:create_index:table={s}:columns={d}:expr={d}:generated_expr={d}:where={d}:unique={}:if_not_exists={}",
                .{ plan.table_name, plan.columns.len, plan.expressions.len, appParityGeneratedExpressionCount(plan), plan.where.len, plan.unique, plan.if_not_exists },
            ),
        .drop_index => |plan| try std.fmt.allocPrint(
            alloc,
            "ddl:drop_index:index={s}:if_exists={}",
            .{ plan.index_name, plan.if_exists },
        ),
        .drop_table => |plan| if (plan.cascade)
            try std.fmt.allocPrint(
                alloc,
                "ddl:drop_table:table={s}:if_exists={}:cascade=true",
                .{ plan.table_name, plan.if_exists },
            )
        else
            try std.fmt.allocPrint(
                alloc,
                "ddl:drop_table:table={s}:if_exists={}",
                .{ plan.table_name, plan.if_exists },
            ),
        .alter_table => |plan| try std.fmt.allocPrint(
            alloc,
            "ddl:alter_table:table={s}:ops={d}:if_exists={}",
            .{ plan.table_name, plan.operations.len, plan.if_exists },
        ),
        .create_update_policy => |plan| try std.fmt.allocPrint(
            alloc,
            "ddl:create_update_policy:table={s}:column={s}",
            .{ plan.table_name, plan.column_name },
        ),
    };
}

fn ddlAppliedFingerprintAlloc(alloc: std.mem.Allocator, applied: AppliedDdlSchemaJson) ![]u8 {
    var parsed = try schema_api.parseValidatedTableSchema(alloc, applied.schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var building_indexes: usize = 0;
    var update_policies: usize = 0;
    for (schema.relational_columns) |column| {
        if (column.index_lifecycle != .ready) building_indexes += 1;
        if (column.on_update_value != null) update_policies += 1;
    }

    var unvalidated_unique: usize = 0;
    for (schema.unique_constraints) |constraint| {
        if (constraint.validation_state != .enforced) unvalidated_unique += 1;
    }
    var unvalidated_fk: usize = 0;
    for (schema.foreign_keys) |foreign_key| {
        if (foreign_key.validation_state != .enforced) unvalidated_fk += 1;
    }
    var unvalidated_check: usize = 0;
    for (schema.checks) |check| {
        if (check.validation_state != .enforced) unvalidated_check += 1;
    }

    return try std.fmt.allocPrint(
        alloc,
        "applied:rebuild={}:validation={}:rewrite={}:building_indexes={d}:unvalidated_unique={d}:unvalidated_fk={d}:unvalidated_check={d}:update_policy={d}",
        .{
            applied.requires_rebuild,
            applied.validation_required,
            applied.rewrite_required,
            building_indexes,
            unvalidated_unique,
            unvalidated_fk,
            unvalidated_check,
            update_policies,
        },
    );
}

fn expectAppliedDdlCorpusPlan(
    alloc: std.mem.Allocator,
    base_schema_json: []const u8,
    entry: AppParityCorpusEntry,
    lowered: LoweredDdlPlan,
) !void {
    if (entry.applied_plan.len == 0) return;

    var current_schema_json: []const u8 = base_schema_json;
    var owned_current_schema_json: ?[]u8 = null;
    defer if (owned_current_schema_json) |schema_json| alloc.free(schema_json);

    if (entry.apply_setup_sql.len > 0) current_schema_json = "";
    for (entry.apply_setup_sql) |setup_sql| {
        var setup_plan = try lowerDdlPlanAlloc(alloc, setup_sql);
        defer setup_plan.deinit(alloc);
        const setup_applied = try applyDdlPlanToSchemaJsonAlloc(alloc, current_schema_json, setup_plan);
        if (owned_current_schema_json) |schema_json| alloc.free(schema_json);
        owned_current_schema_json = setup_applied.schema_json;
        current_schema_json = setup_applied.schema_json;
    }

    var applied = try applyDdlPlanToSchemaJsonAlloc(alloc, current_schema_json, lowered);
    defer applied.deinit(alloc);
    const fingerprint = try ddlAppliedFingerprintAlloc(alloc, applied);
    defer alloc.free(fingerprint);
    try expectAppParityPlan(entry.applied_plan, fingerprint);
}

fn schemaJsonFromSetupSqlAlloc(
    alloc: std.mem.Allocator,
    setup_sql: []const []const u8,
) ![]u8 {
    var current_schema_json: []const u8 = "";
    var owned_current_schema_json: ?[]u8 = null;
    errdefer if (owned_current_schema_json) |schema_json| alloc.free(schema_json);

    for (setup_sql) |sql| {
        var setup_plan = try lowerDdlPlanAlloc(alloc, sql);
        defer setup_plan.deinit(alloc);
        const setup_applied = try applyDdlPlanToSchemaJsonAlloc(alloc, current_schema_json, setup_plan);
        if (owned_current_schema_json) |schema_json| alloc.free(schema_json);
        owned_current_schema_json = setup_applied.schema_json;
        current_schema_json = setup_applied.schema_json;
    }

    return owned_current_schema_json orelse try alloc.dupe(u8, current_schema_json);
}

fn expectQuerySummary(summary: AppParityPlanSummary, query: db_mod.types.RelationalRowsQueryRequest) !void {
    try expectOptionalUsize(summary.predicates, query.predicates.len);
    try expectOptionalUsize(summary.array_any, query.array_any.len);
    try expectOptionalUsize(summary.in_predicates, query.in_predicates.len);
    try expectOptionalUsize(summary.json_path_eq, query.json_path_eq.len);
    try expectOptionalUsize(summary.json_contains, query.json_contains.len);
    try expectOptionalUsize(summary.json_path_exists, query.json_path_exists.len);
    try expectOptionalUsize(summary.array_contains, query.array_contains.len);
    try expectOptionalUsize(summary.array_eq, query.array_eq.len);
    try expectOptionalUsize(summary.text_patterns, query.text_patterns.len);
    try expectOptionalUsize(summary.access_or_predicates, query.access_or_predicates.len);
    try expectOptionalUsize(summary.access_not_predicates, query.access_not_predicates.len);
    try expectOptionalUsize(summary.expression_predicates, query.expression_predicates.len);
    try expectOptionalUsize(summary.expression_or_predicates, query.expression_or_predicates.len);
    try expectOptionalUsize(summary.expression_not_predicates, query.expression_not_predicates.len);
    try expectOptionalUsize(summary.expression_array_contains, query.expression_array_contains.len);
    try expectOptionalUsize(summary.select, query.select.len);
    if (summary.select_all) |expected| try std.testing.expectEqual(expected, query.select_all);
    try expectOptionalUsize(summary.distinct_on, query.distinct_on.len);
    try expectOptionalUsize(summary.order_by, query.order_by.len);
    try expectOptionalU32(summary.limit, query.limit);
    if (summary.offset) |expected| try std.testing.expectEqual(expected, query.offset);
    if (summary.row_claim_skip_locked) |expected| {
        try std.testing.expect(query.row_claim != null);
        try std.testing.expectEqual(expected, query.row_claim.?.skip_locked);
    }
}

