fn expectDdlSummary(summary: AppParityPlanSummary, lowered: LoweredDdlPlan) !void {
    const expected = summary.ddl_tag orelse return;
    switch (lowered) {
        .create_table => |plan| {
            try std.testing.expectEqual(AppParityDdlTag.create_table, expected);
            try expectOptionalTableName(summary.table_name, plan.table_name);
            try expectOptionalUsize(summary.select, plan.columns.len);
            try expectOptionalUsize(summary.operations, plan.unique_constraints.len + plan.foreign_keys.len + plan.checks.len);
        },
        .create_index => |plan| {
            try std.testing.expectEqual(AppParityDdlTag.create_index, expected);
            try expectOptionalTableName(summary.table_name, plan.table_name);
            try expectOptionalUsize(summary.select, plan.columns.len + plan.expressions.len + appParityGeneratedExpressionCount(plan));
            try expectOptionalUsize(summary.predicates, plan.where.len);
        },
        .drop_index => |plan| {
            try std.testing.expectEqual(AppParityDdlTag.drop_index, expected);
            _ = plan;
        },
        .drop_table => |plan| {
            try std.testing.expectEqual(AppParityDdlTag.drop_table, expected);
            try expectOptionalTableName(summary.table_name, plan.table_name);
        },
        .alter_table => |plan| {
            try std.testing.expectEqual(AppParityDdlTag.alter_table, expected);
            try expectOptionalTableName(summary.table_name, plan.table_name);
            try expectOptionalUsize(summary.operations, plan.operations.len);
        },
        .create_update_policy => |plan| {
            try std.testing.expectEqual(AppParityDdlTag.create_update_policy, expected);
            try expectOptionalTableName(summary.table_name, plan.table_name);
        },
    }
}

fn sourceQueryUsesExtendedPredicates(query: db_mod.types.RelationalRowsQueryRequest) bool {
    return query.array_any.len > 0 or
        query.in_predicates.len > 0 or
        query.json_contains.len > 0 or
        query.json_path_exists.len > 0 or
        query.array_contains.len > 0 or
        query.array_eq.len > 0 or
        query.access_or_predicates.len > 0 or
        query.access_not_predicates.len > 0 or
        query.expression_predicates.len > 0 or
        query.expression_or_predicates.len > 0 or
        query.expression_not_predicates.len > 0 or
        query.expression_array_contains.len > 0;
}

fn insertSourceFingerprintAlloc(alloc: std.mem.Allocator, lowered: LoweredInsertSource) ![]u8 {
    const req = lowered.insert_source.req;
    const source = req.source;
    const conflict = req.on_conflict != null;
    const base = if (sourceQueryUsesExtendedPredicates(source))
        try std.fmt.allocPrint(
            alloc,
            "insert_source:table={s}:source_table={s}:source_pred={d}:source_array_any={d}:source_expr_pred={d}:source_expr_or={d}:source_expr_not={d}:source_expr_array={d}:source_order={d}:source_limit={d}:assignments={d}:conflict={d}:returning={d}:returning_expr={d}:returning_all={d}",
            .{
                lowered.table_name,
                req.source_table,
                source.predicates.len,
                source.array_any.len,
                source.expression_predicates.len,
                source.expression_or_predicates.len,
                source.expression_not_predicates.len,
                source.expression_array_contains.len,
                source.order_by.len,
                appParityLimitValue(source.limit),
                req.assignments.len,
                appParityBoolValue(conflict),
                req.returning.len,
                req.returning_expressions.len,
                appParityBoolValue(req.returning_all),
            },
        )
    else
        try std.fmt.allocPrint(
            alloc,
            "insert_source:table={s}:source_table={s}:source_pred={d}:source_order={d}:source_limit={d}:assignments={d}:conflict={d}:returning={d}:returning_expr={d}:returning_all={d}",
            .{
                lowered.table_name,
                req.source_table,
                source.predicates.len,
                source.order_by.len,
                appParityLimitValue(source.limit),
                req.assignments.len,
                appParityBoolValue(conflict),
                req.returning.len,
                req.returning_expressions.len,
                appParityBoolValue(req.returning_all),
            },
        );
    const with_in = try appendNonZeroUsizeFingerprintAlloc(alloc, base, "source_in", source.in_predicates.len);
    const with_or = try appendNonZeroUsizeFingerprintAlloc(alloc, with_in, "source_or", source.or_predicates.len);
    const with_not = try appendNonZeroUsizeFingerprintAlloc(alloc, with_or, "source_not", source.not_predicates.len);
    const with_access = try appendSourceQueryAccessOnlyFingerprintAlloc(alloc, with_not, source);
    if (req.on_conflict) |on_conflict| {
        const with_action = try std.fmt.allocPrint(alloc, "{s}:conflict_action={s}", .{ with_access, conflictActionName(on_conflict.action) });
        alloc.free(with_access);
        const with_ops = try appendNonZeroUsizeFingerprintAlloc(alloc, with_action, "conflict_ops", on_conflict.operations.len);
        const with_patch = try appendNonZeroUsizeFingerprintAlloc(alloc, with_ops, "conflict_patch_expr", on_conflict.patch_expressions.len);
        const with_increment = try appendNonZeroUsizeFingerprintAlloc(alloc, with_patch, "conflict_increment_expr", on_conflict.increment_expressions.len);
        const with_json_set = try appendNonZeroUsizeFingerprintAlloc(alloc, with_increment, "conflict_json_set_expr", on_conflict.json_set_expressions.len);
        return try appendTrueBoolFingerprintAlloc(alloc, with_json_set, "conflict_where_expr", on_conflict.where_expression != null);
    }
    return with_access;
}

fn conflictActionName(action: db_mod.types.RelationalRowsConflictAction) []const u8 {
    return switch (action) {
        .update => "update",
        .nothing => "nothing",
    };
}

