                try expectCombinedQuerySourceSummary(entry.summary, delete_joined_source.mutation.req.join.left, delete_joined_source.mutation.req.join.right);
                try expectOptionalUsize(entry.summary.join_on, delete_joined_source.mutation.req.join.on.len);
                try expectOptionalUsize(entry.summary.order_by, delete_joined_source.mutation.req.join.order_by.len);
                try expectOptionalU32(entry.summary.limit, delete_joined_source.mutation.req.join.limit);
                try expectOptionalU32(entry.summary.offset, delete_joined_source.mutation.req.join.offset);
                try expectOptionalUsize(entry.summary.returning, delete_joined_source.mutation.req.returning.len);
                if (entry.summary.returning_all) |expected| try std.testing.expectEqual(expected, delete_joined_source.mutation.req.returning_all);
                const fingerprint = try joinedSourceFingerprintAlloc(alloc, "delete_joined_source", delete_joined_source);
                defer alloc.free(fingerprint);
                try expectAppParityPlan(entry.plan, fingerprint);
            },
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }
}

fn appParityPlanFamilyIsSupportedWrite(family: AppParityCorpusPlanFamily) bool {
    return switch (family) {
        .insert,
        .insert_source,
        .update,
        .delete,
        .update_source,
        .delete_source,
        .truncate_source,
        .update_joined_source,
        .delete_joined_source,
        => true,
        else => false,
    };
}

fn unsupportedWritePlanFamilyPrefix(family: AppParityCorpusPlanFamily) ?[]const u8 {
    return switch (family) {
        .unsupported_insert => "insert",
        .unsupported_update => "update",
        .unsupported_update_source => "update_source",
        .unsupported_delete => "delete",
        .unsupported_update_joined_source => "update_joined_source",
        .unsupported_delete_joined_source => "delete_joined_source",
        else => null,
    };
}

fn expectAppParityUnsupportedWritePlanEntry(
    alloc: std.mem.Allocator,
    effective_schema: runtime_schema.TableSchema,
    entry: AppParityCorpusEntry,
    unique_resolver: relational_rows.UniqueSelectorResolver,
    row_claim: db_mod.types.RowClaimRequest,
) !void {
    const family = unsupportedWritePlanFamilyPrefix(entry.family) orelse return error.TestUnexpectedResult;
    try expectFailClosedUnsupported(lowerWritePlanAlloc(alloc, entry.sql, effective_schema, entry.params, .{
        .unique_resolver = unique_resolver,
        .row_claim = row_claim,
    }));
    const fingerprint = try unsupportedFingerprintAlloc(alloc, family, entry.classification_reason);
    defer alloc.free(fingerprint);
    try expectAppParityPlan(entry.plan, fingerprint);
}

fn expectAppParityCorpusEntry(
    alloc: std.mem.Allocator,
    base_schema_json: []const u8,
    schema: runtime_schema.TableSchema,
    entry: AppParityCorpusEntry,
    unique_resolver: relational_rows.UniqueSelectorResolver,
    row_claim: db_mod.types.RowClaimRequest,
) !void {
    var effective_schema = schema;
    var owned_setup_schema: ?runtime_schema.TableSchema = null;
    defer if (owned_setup_schema) |value| runtime_schema.freeSchema(alloc, value);
    if (entry.family != .ddl and entry.apply_setup_sql.len > 0) {
        const setup_schema_json = try schemaJsonFromSetupSqlAlloc(alloc, entry.apply_setup_sql);
        defer alloc.free(setup_schema_json);
        var parsed_setup_schema = try schema_api.parseValidatedTableSchema(alloc, setup_schema_json);
        defer parsed_setup_schema.deinit(alloc);
        owned_setup_schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed_setup_schema);
        effective_schema = owned_setup_schema.?;
    }
    var override_resolver_ctx = TestPrimaryResolver{
        .row_json = entry.resolver_row_json,
        .version = entry.resolver_version,
        .exists = entry.resolver_exists orelse true,
    };
    const effective_unique_resolver = if (entry.resolver_row_json.len > 0 or entry.resolver_exists != null)
        override_resolver_ctx.resolver()
    else
        unique_resolver;

    if (appParityPlanFamilyIsSupportedRead(entry.family)) {
        return try expectAppParityReadPlanEntry(alloc, effective_schema, entry);
    }
    if (appParityPlanFamilyIsSupportedWrite(entry.family)) {
        return try expectAppParityWritePlanEntry(alloc, effective_schema, entry, effective_unique_resolver, row_claim);
    }
    if (unsupportedWritePlanFamilyPrefix(entry.family) != null) {
        return try expectAppParityUnsupportedWritePlanEntry(alloc, effective_schema, entry, effective_unique_resolver, row_claim);
    }

    switch (entry.family) {
        .ddl => {
            var lowered = try lowerDdlPlanAlloc(alloc, entry.sql);
            defer lowered.deinit(alloc);
            try expectDdlSummary(entry.summary, lowered);
            const fingerprint = try ddlFingerprintAlloc(alloc, lowered);
            defer alloc.free(fingerprint);
            try expectAppParityPlan(entry.plan, fingerprint);
            try expectAppliedDdlCorpusPlan(alloc, base_schema_json, entry, lowered);
        },
        .read => {
            var lowered = try lowerAppParityReadPlanAlloc(alloc, effective_schema, entry);
            defer lowered.deinit(alloc);
            const fingerprint = try readPlanFingerprintAlloc(alloc, lowered);
            defer alloc.free(fingerprint);
            try expectAppParityPlan(entry.plan, fingerprint);
        },
        .query => {
            var lowered = try lowerQueryPlanAlloc(alloc, entry.sql, effective_schema, entry.params);
            defer lowered.deinit(alloc);
            try expectOptionalTableName(entry.summary.table_name, lowered.table_name);
            try expectOptionalUsize(entry.summary.ctes, lowered.plan.ctes.len);
            try expectQuerySummary(entry.summary, lowered.plan.query);
            var fingerprint = try queryFingerprintAlloc(alloc, "query", lowered.table_name, lowered.plan.query, lowered.plan.ctes.len);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", lowered.plan.query.offset);
            fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "select_all", lowered.plan.query.select_all);
            fingerprint = try appendQueryAccessPathFingerprintAlloc(alloc, fingerprint, lowered.plan.query);
