test "postgres sql adapter lowers claimed update mutation source" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"priority":{"type":"numeric"},"enabled":{"type":"boolean"},"metadata":{"type":"json"},"tags":{"type":"array","items":{"type":"keyword"}}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);
    const txn_id = [_]u8{ 0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17, 0x18, 0x19, 0x1a, 0x1b, 0x1c, 0x1d, 0x1e, 0x1f };
    const claim: db_mod.types.RowClaimRequest = .{
        .mode = .for_update,
        .owner_id = "worker-a",
        .txn_id = txn_id,
    };

    var lowered = try lowerUpdateMutationSourceAlloc(
        alloc,
        "UPDATE usage_records SET status = $1, priority = priority + 1, metadata = jsonb_set(metadata, '{billing,plan}', $2, true) WHERE status = $3 ORDER BY priority DESC, id ASC LIMIT $4 FOR UPDATE SKIP LOCKED RETURNING id, status, priority, priority + 1 AS next_priority, CASE WHEN priority > 5 THEN 'high' ELSE status END AS priority_label, CAST(priority AS text) AS priority_text, (status IS NOT NULL) AS has_status",
        schema,
        &.{ .{ .string = "processing" }, .{ .string = "pro" }, .{ .string = "queued" }, .{ .integer = 5 } },
        claim,
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqualStrings("usage_records", lowered.table_name);
    try std.testing.expectEqual(db_mod.types.RelationalRowsMutationKind.update, lowered.mutation.req.kind);
    try std.testing.expectEqual(@as(usize, 1), lowered.mutation.req.source.predicates.len);
