    switch (row_value_semijoin_delete_plan) {
        .delete_joined_source => |delete_joined_source| {
            try std.testing.expectEqualStrings("usage_records", delete_joined_source.target_table_name);
            try std.testing.expectEqualStrings("archived_records", delete_joined_source.source_table_name);
            try std.testing.expectEqual(db_mod.types.RelationalRowsMutationKind.delete, delete_joined_source.mutation.req.kind);
            try std.testing.expectEqual(@as(usize, 2), delete_joined_source.mutation.req.join.on.len);
            try std.testing.expectEqualStrings("id", delete_joined_source.mutation.req.join.on[0].left_field);
            try std.testing.expectEqualStrings("organization_id", delete_joined_source.mutation.req.join.on[0].right_field);
            try std.testing.expectEqualStrings("status", delete_joined_source.mutation.req.join.on[1].left_field);
            try std.testing.expectEqualStrings("status", delete_joined_source.mutation.req.join.on[1].right_field);
            try std.testing.expect(delete_joined_source.mutation.req.join.left.row_claim.?.skip_locked);
            try std.testing.expectEqual(@as(usize, 1), delete_joined_source.mutation.req.returning.len);
        },
        else => return error.TestUnexpectedResult,
    }

    var truncate_plan = try lowerWritePlanAlloc(
        alloc,
        "TRUNCATE usage_records",
        schema,
        &.{},
        options,
    );
    defer truncate_plan.deinit(alloc);
    switch (truncate_plan) {
        .truncate_source => |truncate_source| {
            try std.testing.expectEqualStrings("usage_records", truncate_source.table_name);
            try std.testing.expectEqual(db_mod.types.RelationalRowsMutationKind.delete, truncate_source.mutation.req.kind);
            try std.testing.expectEqual(@as(usize, 0), truncate_source.mutation.req.source.predicates.len);
            try std.testing.expectEqual(@as(usize, 0), truncate_source.mutation.req.source.order_by.len);
            try std.testing.expectEqual(@as(?u32, null), truncate_source.mutation.req.source.limit);
            try std.testing.expect(truncate_source.mutation.req.source.row_claim != null);
        },
        else => return error.TestUnexpectedResult,
    }
}

test "postgres sql adapter typed write plans execute through relational storage" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"organization_id":{"type":"keyword"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/sql-write-plan-execution", .{tmp.sub_path});
    defer alloc.free(path);

    var db = try db_mod.DB.open(alloc, path, .{});
    defer db.close();
    try db.applyTableSchemaJson(alloc, schema_json, .{});

    var no_existing_primary = TestPrimaryResolver{ .row_json = "", .version = 0, .exists = false };
    var insert_plan = try lowerWritePlanAlloc(
        alloc,
        "INSERT INTO usage_records (id, status, organization_id) VALUES ('u1', 'queued', 'o1'), ('u2', 'queued', 'o1'), ('u3', 'queued', 'o2') RETURNING id, status",
        schema,
        &.{},
        .{ .unique_resolver = no_existing_primary.resolver() },
    );
    defer insert_plan.deinit(alloc);

    switch (insert_plan) {
        .insert => |insert| {
            try std.testing.expectEqual(@as(u32, 3), insert.batch.inserted);
            try std.testing.expectEqual(@as(usize, 3), insert.batch.returning_rows.len);
            try std.testing.expectEqualStrings("{\"id\":\"u1\",\"status\":\"queued\"}", insert.batch.returning_rows[0]);
            try std.testing.expectEqualStrings("{\"id\":\"u2\",\"status\":\"queued\"}", insert.batch.returning_rows[1]);
            try std.testing.expectEqualStrings("{\"id\":\"u3\",\"status\":\"queued\"}", insert.batch.returning_rows[2]);
            try db.batch(insert.batch.req);
        },
        else => return error.TestUnexpectedResult,
    }

    const update_txn = try db.beginTransaction(2_001);
    var update_committed = false;
    defer if (!update_committed) db.abortTransaction(update_txn, 2_002) catch {};
    const update_claim: db_mod.types.RowClaimRequest = .{
        .mode = .for_update,
        .owner_id = "sql-write-update",
        .txn_id = update_txn,
    };
    var update_plan = try lowerWritePlanAlloc(
        alloc,
        "UPDATE usage_records SET status = 'processed' WHERE organization_id = 'o1' ORDER BY id ASC LIMIT 2 FOR UPDATE SKIP LOCKED RETURNING id, status",
        schema,
        &.{},
        .{ .row_claim = update_claim },
    );
    defer update_plan.deinit(alloc);

    switch (update_plan) {
        .update_source => |update_source| {
            try std.testing.expect(update_source.mutation.req.source.row_claim.?.skip_locked);
            var result = try db.mutateRelationalRowsFromSource(alloc, schema, update_source.mutation.req);
            defer result.deinit(alloc);
            try std.testing.expectEqual(@as(u32, 2), result.matched);
            try std.testing.expectEqual(@as(u32, 2), result.staged);
            try std.testing.expectEqual(@as(usize, 2), result.returning_rows.len);
            try std.testing.expectEqualStrings("{\"id\":\"u1\",\"status\":\"processed\"}", result.returning_rows[0]);
            try std.testing.expectEqualStrings("{\"id\":\"u2\",\"status\":\"processed\"}", result.returning_rows[1]);
        },
        else => return error.TestUnexpectedResult,
    }
    try db.commitTransaction(update_txn, 2_010);
    update_committed = true;

    const delete_txn = try db.beginTransaction(2_101);
    var delete_committed = false;
    defer if (!delete_committed) db.abortTransaction(delete_txn, 2_102) catch {};
    const delete_claim: db_mod.types.RowClaimRequest = .{
        .mode = .for_update,
        .owner_id = "sql-write-delete",
        .txn_id = delete_txn,
    };
    var delete_plan = try lowerWritePlanAlloc(
        alloc,
        "DELETE FROM usage_records WHERE status = 'processed' ORDER BY id ASC FOR UPDATE RETURNING id",
        schema,
        &.{},
        .{ .row_claim = delete_claim },
    );
    defer delete_plan.deinit(alloc);

    switch (delete_plan) {
        .delete_source => |delete_source| {
            var result = try db.mutateRelationalRowsFromSource(alloc, schema, delete_source.mutation.req);
            defer result.deinit(alloc);
            try std.testing.expectEqual(@as(u32, 2), result.matched);
            try std.testing.expectEqual(@as(u32, 2), result.staged);
            try std.testing.expectEqual(@as(usize, 2), result.returning_rows.len);
            try std.testing.expectEqualStrings("{\"id\":\"u1\"}", result.returning_rows[0]);
            try std.testing.expectEqualStrings("{\"id\":\"u2\"}", result.returning_rows[1]);
        },
        else => return error.TestUnexpectedResult,
    }
    try db.commitTransaction(delete_txn, 2_110);
    delete_committed = true;

    const select = [_][]const u8{ "id", "status" };
    const order_by = [_]db_mod.types.RelationalRowsQueryOrder{.{
        .field = "id",
        .direction = .asc,
    }};
    var rows = try db.queryRelationalRows(alloc, schema, .{
        .select = select[0..],
        .order_by = order_by[0..],
    });
    defer rows.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 1), rows.total);
    try std.testing.expectEqual(@as(usize, 1), rows.rows.len);
    try std.testing.expectEqualStrings("{\"id\":\"u3\",\"status\":\"queued\"}", rows.rows[0]);

    try db.batch(.{
        .writes = &.{
            .{ .key = "row:s1", .value = "{\"id\":\"s1\",\"kind\":\"source\",\"status\":\"synced\",\"quantity\":42}" },
            .{ .key = "row:s2", .value = "{\"id\":\"s2\",\"kind\":\"source\",\"status\":\"stale\",\"quantity\":7}" },
            .{ .key = "row:t1", .value = "{\"id\":\"t1\",\"kind\":\"target\",\"source_id\":\"s1\",\"status\":\"ready\",\"quantity\":1}" },
            .{ .key = "row:t2", .value = "{\"id\":\"t2\",\"kind\":\"target\",\"source_id\":\"s1\",\"status\":\"expired\",\"quantity\":2}" },
            .{ .key = "row:t3", .value = "{\"id\":\"t3\",\"kind\":\"target\",\"source_id\":\"s2\",\"status\":\"ready\",\"quantity\":3}" },
        },
        .sync_level = .write,
    });

    const joined_update_txn = try db.beginTransaction(3_001);
    var joined_update_committed = false;
    defer if (!joined_update_committed) db.abortTransaction(joined_update_txn, 3_002) catch {};
    const joined_update_claim: db_mod.types.RowClaimRequest = .{
        .mode = .for_update,
        .owner_id = "sql-write-joined-update",
        .txn_id = joined_update_txn,
    };
    var joined_update_plan = try lowerWritePlanAlloc(
        alloc,
        "UPDATE usage_records SET status = 'joined' FROM usage_records AS source WHERE usage_records.id = source.id AND source.id = 't1' FOR UPDATE RETURNING id, status, lower(source.status) AS source_status_key",
        schema,
        &.{},
        .{ .row_claim = joined_update_claim },
    );
    defer joined_update_plan.deinit(alloc);

    switch (joined_update_plan) {
        .update_joined_source => |joined_update| {
            var result = try db.mutateRelationalRowsJoinedSourceAlloc(alloc, schema, joined_update.mutation.req);
            defer result.deinit(alloc);
            try std.testing.expectEqual(@as(u32, 1), result.matched);
            try std.testing.expectEqual(@as(u32, 1), result.staged);
            try std.testing.expectEqual(@as(usize, 1), result.returning_rows.len);
            try std.testing.expectEqualStrings("{\"id\":\"t1\",\"status\":\"joined\",\"source_status_key\":\"ready\"}", result.returning_rows[0]);
        },
        else => return error.TestUnexpectedResult,
    }
    try db.commitTransaction(joined_update_txn, 3_010);
    joined_update_committed = true;

    const joined_delete_txn = try db.beginTransaction(3_101);
    var joined_delete_committed = false;
    defer if (!joined_delete_committed) db.abortTransaction(joined_delete_txn, 3_102) catch {};
    const joined_delete_claim: db_mod.types.RowClaimRequest = .{
        .mode = .for_update,
        .owner_id = "sql-write-joined-delete",
        .txn_id = joined_delete_txn,
    };
    var joined_delete_plan = try lowerWritePlanAlloc(
        alloc,
        "DELETE FROM usage_records USING usage_records AS source WHERE usage_records.id = source.id AND source.id = 't2' FOR UPDATE RETURNING id, lower(source.status) AS source_status_key",
        schema,
        &.{},
        .{ .row_claim = joined_delete_claim },
    );
    defer joined_delete_plan.deinit(alloc);

    switch (joined_delete_plan) {
        .delete_joined_source => |joined_delete| {
            var result = try db.mutateRelationalRowsJoinedSourceAlloc(alloc, schema, joined_delete.mutation.req);
            defer result.deinit(alloc);
            try std.testing.expectEqual(@as(u32, 1), result.matched);
            try std.testing.expectEqual(@as(u32, 1), result.staged);
            try std.testing.expectEqual(@as(usize, 1), result.returning_rows.len);
            try std.testing.expectEqualStrings("{\"id\":\"t2\",\"source_status_key\":\"expired\"}", result.returning_rows[0]);
        },
        else => return error.TestUnexpectedResult,
    }
    try db.commitTransaction(joined_delete_txn, 3_110);
    joined_delete_committed = true;

    const joined_select = [_][]const u8{ "id", "status" };
    const joined_order_by = [_]db_mod.types.RelationalRowsQueryOrder{.{
        .field = "id",
        .direction = .asc,
    }};
    var joined_rows = try db.queryRelationalRows(alloc, schema, .{
        .select = joined_select[0..],
        .order_by = joined_order_by[0..],
    });
    defer joined_rows.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 5), joined_rows.total);
    try std.testing.expectEqualStrings("{\"id\":\"s1\",\"status\":\"synced\"}", joined_rows.rows[0]);
    try std.testing.expectEqualStrings("{\"id\":\"s2\",\"status\":\"stale\"}", joined_rows.rows[1]);
    try std.testing.expectEqualStrings("{\"id\":\"t1\",\"status\":\"joined\"}", joined_rows.rows[2]);
    try std.testing.expectEqualStrings("{\"id\":\"t3\",\"status\":\"ready\"}", joined_rows.rows[3]);
}

test "postgres sql adapter lowers truncate into claimed table-emptying mutation source" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);
    const txn_id = [_]u8{ 0x70, 0x71, 0x72, 0x73, 0x74, 0x75, 0x76, 0x77, 0x78, 0x79, 0x7a, 0x7b, 0x7c, 0x7d, 0x7e, 0x7f };
    const claim: db_mod.types.RowClaimRequest = .{
        .mode = .for_update,
        .owner_id = "truncate-worker",
        .txn_id = txn_id,
    };

    var lowered = try lowerTruncateMutationSourceAlloc(
        alloc,
        "TRUNCATE TABLE ONLY usage_records RESTRICT;",
        schema,
        claim,
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqualStrings("usage_records", lowered.table_name);
    try std.testing.expectEqual(db_mod.types.RelationalRowsMutationKind.delete, lowered.mutation.req.kind);
    try std.testing.expectEqual(@as(usize, 0), lowered.mutation.req.source.predicates.len);
    try std.testing.expectEqual(@as(usize, 0), lowered.mutation.req.source.order_by.len);
    try std.testing.expectEqual(@as(?u32, null), lowered.mutation.req.source.limit);
    try std.testing.expect(lowered.mutation.req.source.row_claim != null);
    try std.testing.expect(!lowered.mutation.req.source.row_claim.?.skip_locked);
    try std.testing.expectEqualStrings("truncate-worker", lowered.mutation.req.source.row_claim.?.owner_id);
    try std.testing.expectEqualSlices(u8, &txn_id, &lowered.mutation.req.source.row_claim.?.txn_id.?);
    try std.testing.expectEqual(@as(usize, 0), lowered.mutation.req.operations.len);
    try std.testing.expectEqual(@as(usize, 0), lowered.mutation.req.returning.len);
    try std.testing.expectEqual(@as(usize, 0), lowered.mutation.req.returning_expressions.len);
    try std.testing.expect(!lowered.mutation.req.returning_all);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerTruncateMutationSourceAlloc(
        alloc,
        "TRUNCATE usage_records, other_records",
        schema,
        claim,
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerTruncateMutationSourceAlloc(
        alloc,
        "TRUNCATE usage_records RESTART IDENTITY",
        schema,
        claim,
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerTruncateMutationSourceAlloc(
        alloc,
        "TRUNCATE usage_records CASCADE",
        schema,
        claim,
    ));
}

test "postgres sql adapter lowers on conflict primary do nothing" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);
    var resolver_ctx = TestPrimaryResolver{ .row_json = "{\"id\":\"u1\",\"status\":\"existing\"}", .version = 12 };

    var lowered = try lowerInsertWithResolverAlloc(
        alloc,
        "INSERT INTO usage_records (id, status) VALUES ($1, $2) ON CONFLICT (id) DO NOTHING RETURNING *",
        schema,
        &.{ .{ .string = "u1" }, .{ .string = "pending" } },
        resolver_ctx.resolver(),
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 0), lowered.batch.inserted);
    try std.testing.expectEqual(@as(usize, 0), lowered.batch.writes.len);
    try std.testing.expectEqual(@as(usize, 0), lowered.batch.returning_rows.len);

    var named_primary = try lowerInsertWithResolverAlloc(
        alloc,
        "INSERT INTO usage_records (id, status) VALUES ($1, $2) ON CONFLICT ON CONSTRAINT usage_records_pkey DO NOTHING RETURNING *",
        schema,
        &.{ .{ .string = "u1" }, .{ .string = "pending" } },
        resolver_ctx.resolver(),
    );
    defer named_primary.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 0), named_primary.batch.inserted);
    try std.testing.expectEqual(@as(usize, 0), named_primary.batch.writes.len);
    try std.testing.expectEqual(@as(usize, 0), named_primary.batch.returning_rows.len);

    try std.testing.expectError(error.InvalidSqlCatalog, lowerInsertWithResolverAlloc(
        alloc,
        "INSERT INTO usage_records (id, status) VALUES ($1, $2) ON CONFLICT ON CONSTRAINT usage_records_id_key DO NOTHING",
        schema,
        &.{ .{ .string = "u1" }, .{ .string = "pending" } },
        resolver_ctx.resolver(),
    ));

    try std.testing.expectError(error.UnsupportedSqlShape, lowerInsertWithResolverAlloc(
        alloc,
        "INSERT INTO usage_records (id, status) VALUES ($1, $2) ON CONFLICT (id, id) DO NOTHING",
        schema,
        &.{ .{ .string = "u1" }, .{ .string = "pending" } },
        resolver_ctx.resolver(),
    ));
}

test "postgres sql adapter lowers on conflict primary do update with excluded values" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);
    var resolver_ctx = TestPrimaryResolver{ .row_json = "{\"id\":\"u1\",\"status\":\"existing\"}", .version = 12 };

    var lowered = try lowerInsertWithResolverAlloc(
        alloc,
        "INSERT INTO usage_records (id, status) VALUES ('u1', 'pending') ON CONFLICT (id) DO UPDATE SET status = excluded.status RETURNING status, CASE WHEN status = 'pending' THEN 'updated' ELSE status END AS status_label",
        schema,
        &.{},
        resolver_ctx.resolver(),
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 0), lowered.batch.inserted);
    try std.testing.expectEqual(@as(u32, 1), lowered.batch.transformed);
    try std.testing.expectEqual(@as(usize, 1), lowered.batch.transforms.len);
    try std.testing.expectEqualStrings("status", lowered.batch.transforms[0].operations[0].path);
    try std.testing.expectEqualStrings("\"pending\"", lowered.batch.transforms[0].operations[0].value_json.?);
    try std.testing.expectEqual(@as(usize, 1), lowered.batch.predicates.len);
    try std.testing.expectEqual(@as(u64, 12), lowered.batch.predicates[0].expected_version);
    try std.testing.expectEqual(@as(usize, 1), lowered.returning_expression_count);
    try std.testing.expectEqualStrings("{\"status\":\"pending\",\"status_label\":\"updated\"}", lowered.batch.returning_rows[0]);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerInsertWithResolverAlloc(
        alloc,
        "INSERT INTO usage_records (id, status) VALUES ('u1', 'pending') ON CONFLICT (id) DO UPDATE SET status = excluded.status, status = lower(status)",
        schema,
        &.{},
        resolver_ctx.resolver(),
    ));
}

