        schema,
        &.{},
    ));
}

test "postgres sql adapter classifies read sql into typed plan families" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"kind":{"type":"keyword"},"tenant":{"type":"keyword"},"id":{"type":"keyword"},"organization_id":{"type":"keyword"},"customer_id":{"type":"keyword"},"status":{"type":"keyword"},"amount":{"type":"numeric"},"created_at":{"type":"numeric"},"name":{"type":"keyword"}},"required":["kind","tenant","id"],"additionalProperties":false}}},"primary_key":{"columns":["kind","tenant","id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var query = try lowerReadPlanAlloc(
        alloc,
        "SELECT id, status FROM usage_records WHERE kind = 'order' ORDER BY created_at DESC LIMIT 5",
        schema,
        &.{},
    );
    defer query.deinit(alloc);
    switch (query) {
        .query => |lowered| {
            try std.testing.expectEqualStrings("usage_records", lowered.table_name);
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.query.predicates.len);
        },
        else => return error.TestUnexpectedResult,
    }

    var aggregate = try lowerReadPlanAlloc(
        alloc,
        "SELECT status, SUM(amount) AS total FROM usage_records WHERE kind = 'order' GROUP BY status ORDER BY total DESC LIMIT 5",
        schema,
        &.{},
    );
    defer aggregate.deinit(alloc);
    switch (aggregate) {
        .aggregate => |lowered| {
            try std.testing.expectEqualStrings("usage_records", lowered.table_name);
            try std.testing.expectEqual(@as(usize, 0), lowered.plan.ctes.len);
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.aggregate.aggregations.len);
            try std.testing.expectEqual(db_mod.types.RelationalRowsAggregateOp.sum, lowered.plan.aggregate.aggregations[0].op);
        },
        else => return error.TestUnexpectedResult,
    }

    var cte_aggregate = try lowerReadPlanAlloc(
        alloc,
        "WITH open_usage AS (SELECT tenant, amount, status FROM usage_records WHERE status = 'open') SELECT tenant, SUM(amount) AS total FROM open_usage GROUP BY tenant ORDER BY total DESC LIMIT 5",
        schema,
        &.{},
    );
    defer cte_aggregate.deinit(alloc);
    switch (cte_aggregate) {
        .aggregate => |lowered| {
            try std.testing.expectEqualStrings("usage_records", lowered.table_name);
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.ctes.len);
            try std.testing.expectEqualStrings("open_usage", lowered.plan.aggregate.source.source_cte);
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.aggregate.aggregations.len);
        },
        else => return error.TestUnexpectedResult,
    }

    var join = try lowerReadPlanAlloc(
        alloc,
        "SELECT o.id AS order_id, c.name AS customer_name FROM usage_records AS o LEFT JOIN usage_records AS c ON o.tenant = c.tenant AND o.customer_id = c.id WHERE o.kind = 'order' AND c.kind = 'customer' ORDER BY order_id ASC LIMIT 5",
        schema,
        &.{},
    );
    defer join.deinit(alloc);
    switch (join) {
        .join => |lowered| {
            try std.testing.expectEqualStrings("usage_records", lowered.left_table_name);
            try std.testing.expectEqualStrings("usage_records", lowered.right_table_name);
            try std.testing.expectEqual(@as(usize, 2), lowered.join.on.len);
            try std.testing.expectEqual(@as(usize, 2), lowered.join.select.len);
        },
        else => return error.TestUnexpectedResult,
    }

    var lateral = try lowerReadPlanAlloc(
        alloc,
        "SELECT org.id AS organization_id, latest.amount AS latest_amount FROM usage_records AS org LEFT JOIN LATERAL (SELECT amount, created_at FROM usage_records AS bal WHERE bal.organization_id = org.id AND bal.kind = 'balance' ORDER BY 2 DESC LIMIT 1) AS latest ON true WHERE org.kind = 'organization' ORDER BY latest_amount DESC LIMIT 10",
        schema,
        &.{},
    );
    defer lateral.deinit(alloc);
    switch (lateral) {
        .lateral => |lowered| {
            try std.testing.expectEqualStrings("usage_records", lowered.left_table_name);
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.lateral.correlations.len);
        },
        else => return error.TestUnexpectedResult,
    }

    var window = try lowerReadPlanAlloc(
        alloc,
        "SELECT tenant, id, row_number() OVER (PARTITION BY tenant ORDER BY amount DESC, id ASC) AS row_num FROM usage_records WHERE status = 'open' ORDER BY row_num ASC LIMIT 5",
        schema,
        &.{},
    );
    defer window.deinit(alloc);
    switch (window) {
        .window => |lowered| {
            try std.testing.expectEqualStrings("usage_records", lowered.table_name);
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.window.windows.len);
        },
        else => return error.TestUnexpectedResult,
    }
}

test "postgres sql adapter typed read plans execute through relational storage" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"kind":{"type":"keyword"},"tenant":{"type":"keyword"},"id":{"type":"keyword"},"customer_id":{"type":"keyword"},"organization_id":{"type":"keyword"},"status":{"type":"keyword"},"name":{"type":"keyword"},"amount":{"type":"numeric"},"created_at":{"type":"numeric"}},"required":["kind","tenant","id"],"additionalProperties":false}}},"primary_key":{"columns":["kind","tenant","id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/sql-read-plan-execution", .{tmp.sub_path});
    defer alloc.free(path);

    var db = try db_mod.DB.open(alloc, path, .{});
    defer db.close();
    try db.applyTableSchemaJson(alloc, schema_json, .{});

    try db.batch(.{
        .writes = &.{
            .{ .key = "row:c1", .value = "{\"kind\":\"customer\",\"tenant\":\"t1\",\"id\":\"c1\",\"name\":\"Alice\"}" },
            .{ .key = "row:c2", .value = "{\"kind\":\"customer\",\"tenant\":\"t1\",\"id\":\"c2\",\"name\":\"Bob\"}" },
            .{ .key = "row:o1", .value = "{\"kind\":\"order\",\"tenant\":\"t1\",\"id\":\"o1\",\"customer_id\":\"c1\",\"status\":\"open\",\"amount\":10}" },
            .{ .key = "row:o2", .value = "{\"kind\":\"order\",\"tenant\":\"t1\",\"id\":\"o2\",\"customer_id\":\"missing\",\"status\":\"open\",\"amount\":5}" },
            .{ .key = "row:o3", .value = "{\"kind\":\"order\",\"tenant\":\"t2\",\"id\":\"o3\",\"customer_id\":\"c1\",\"status\":\"open\",\"amount\":7}" },
            .{ .key = "row:org1", .value = "{\"kind\":\"organization\",\"tenant\":\"t1\",\"id\":\"org1\"}" },
            .{ .key = "row:org2", .value = "{\"kind\":\"organization\",\"tenant\":\"t1\",\"id\":\"org2\"}" },
            .{ .key = "row:org3", .value = "{\"kind\":\"organization\",\"tenant\":\"t1\",\"id\":\"org3\"}" },
            .{ .key = "row:b1", .value = "{\"kind\":\"balance\",\"tenant\":\"t1\",\"id\":\"b1\",\"organization_id\":\"org1\",\"amount\":4,\"created_at\":10}" },
            .{ .key = "row:b2", .value = "{\"kind\":\"balance\",\"tenant\":\"t1\",\"id\":\"b2\",\"organization_id\":\"org1\",\"amount\":9,\"created_at\":20}" },
            .{ .key = "row:b3", .value = "{\"kind\":\"balance\",\"tenant\":\"t1\",\"id\":\"b3\",\"organization_id\":\"org2\",\"amount\":7,\"created_at\":15}" },
        },
        .sync_level = .write,
    });

    var join_plan = try lowerReadPlanAlloc(
        alloc,
        "SELECT o.id AS order_id, c.name AS customer_name, o.amount AS amount FROM usage_records AS o LEFT JOIN usage_records AS c ON o.tenant = c.tenant AND o.customer_id = c.id WHERE o.kind = 'order' ORDER BY amount DESC LIMIT 10",
        schema,
        &.{},
    );
    defer join_plan.deinit(alloc);

    switch (join_plan) {
        .join => |lowered| {
            try std.testing.expectEqual(db_mod.types.RelationalRowsJoinType.left, lowered.join.join_type);
            var result = try db.joinRelationalRows(alloc, schema, lowered.join);
            defer result.deinit(alloc);

            try std.testing.expectEqual(@as(u32, 3), result.total_rows);
            try std.testing.expectEqual(@as(usize, 3), result.rows.len);
            try std.testing.expectEqualStrings("{\"order_id\":\"o1\",\"customer_name\":\"Alice\",\"amount\":10}", result.rows[0]);
            try std.testing.expectEqualStrings("{\"order_id\":\"o3\",\"customer_name\":null,\"amount\":7}", result.rows[1]);
            try std.testing.expectEqualStrings("{\"order_id\":\"o2\",\"customer_name\":null,\"amount\":5}", result.rows[2]);
        },
        else => return error.TestUnexpectedResult,
    }

    var aggregate_plan = try lowerReadPlanAlloc(
        alloc,
        "WITH open_usage AS (SELECT tenant, amount, status FROM usage_records WHERE kind = 'order' AND status = 'open') SELECT tenant, SUM(amount) AS total_amount FROM open_usage GROUP BY tenant ORDER BY total_amount DESC LIMIT 5",
        schema,
        &.{},
    );
    defer aggregate_plan.deinit(alloc);

    switch (aggregate_plan) {
        .aggregate => |lowered| {
            try std.testing.expectEqual(@as(usize, 1), lowered.plan.ctes.len);
            try std.testing.expectEqualStrings("open_usage", lowered.plan.aggregate.source.source_cte);
            var result = try db.aggregateRelationalRowsPlan(alloc, schema, lowered.plan);
            defer result.deinit(alloc);

            try std.testing.expectEqual(@as(u32, 2), result.total_groups);
            try std.testing.expectEqual(@as(usize, 2), result.rows.len);
            try std.testing.expectEqualStrings("{\"tenant\":\"t1\",\"total_amount\":15}", result.rows[0]);
            try std.testing.expectEqualStrings("{\"tenant\":\"t2\",\"total_amount\":7}", result.rows[1]);
        },
        else => return error.TestUnexpectedResult,
    }

    var window_plan = try lowerReadPlanAlloc(
        alloc,
        "SELECT tenant, id, row_number() OVER (PARTITION BY tenant ORDER BY amount DESC, id ASC) AS row_num FROM usage_records WHERE kind = 'order' ORDER BY row_num ASC, id ASC LIMIT 10",
        schema,
        &.{},
    );
    defer window_plan.deinit(alloc);

    switch (window_plan) {
        .window => |lowered| {
            var result = try db.windowRelationalRowsPlan(alloc, schema, lowered.plan);
            defer result.deinit(alloc);

            try std.testing.expectEqual(@as(u32, 3), result.total_rows);
            try std.testing.expectEqual(@as(usize, 3), result.rows.len);
            try std.testing.expectEqualStrings("{\"tenant\":\"t1\",\"id\":\"o1\",\"row_num\":1}", result.rows[0]);
            try std.testing.expectEqualStrings("{\"tenant\":\"t2\",\"id\":\"o3\",\"row_num\":1}", result.rows[1]);
            try std.testing.expectEqualStrings("{\"tenant\":\"t1\",\"id\":\"o2\",\"row_num\":2}", result.rows[2]);
        },
        else => return error.TestUnexpectedResult,
    }

    var lateral_plan = try lowerReadPlanAlloc(
        alloc,
        "SELECT org.id AS organization_id, latest.amount AS latest_amount, latest.created_at AS latest_created_at FROM usage_records AS org LEFT JOIN LATERAL (SELECT amount, created_at FROM usage_records AS bal WHERE bal.organization_id = org.id AND bal.kind = 'balance' ORDER BY 2 DESC LIMIT 1) AS latest ON true WHERE org.kind = 'organization' ORDER BY latest_amount DESC NULLS LAST LIMIT 10",
        schema,
        &.{},
    );
    defer lateral_plan.deinit(alloc);

    switch (lateral_plan) {
        .lateral => |lowered| {
            var result = try db.lateralRelationalRowsPlan(alloc, schema, lowered.plan);
            defer result.deinit(alloc);

            try std.testing.expectEqual(@as(u32, 3), result.total_rows);
            try std.testing.expectEqual(@as(usize, 3), result.rows.len);
            try std.testing.expectEqualStrings("{\"organization_id\":\"org1\",\"latest_amount\":9,\"latest_created_at\":20}", result.rows[0]);
            try std.testing.expectEqualStrings("{\"organization_id\":\"org2\",\"latest_amount\":7,\"latest_created_at\":15}", result.rows[1]);
            try std.testing.expectEqualStrings("{\"organization_id\":\"org3\",\"latest_amount\":null,\"latest_created_at\":null}", result.rows[2]);
        },
        else => return error.TestUnexpectedResult,
    }
}

